-- ==== 02_tables_core.sql ====
-- =============================================================================
-- Harmony Database Schema - Core Tables
-- =============================================================================
-- Foundational tables that other tables depend on
-- =============================================================================

-- ---------------------------------------------------------------------------
-- PROFILES - Core user table
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.profiles (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone,
    username text,
    display_name text,
    avatar_url text DEFAULT '/default_avatar.webp'::text,
    bio text,
    color character varying,
    status smallint DEFAULT 0,
    
    -- Federation fields
    -- Domain of the user's instance
    -- For local users: set from instance_config 'domain' during profile creation
    -- For federated users: the remote instance domain
    -- Default 'localhost' is for development; production instances MUST configure this
    domain text DEFAULT 'localhost'::text NOT NULL,
    federated_id text,
    public_key text,
    -- Note: private_key is stored in user_private_keys table, NOT here
    inbox_url text,
    outbox_url text,
    followers_url text,
    following_url text,
    featured_url text,
    shared_inbox_url text,
    is_local boolean DEFAULT true,
    last_synced_at timestamp with time zone,
    federation_metadata jsonb DEFAULT '{}'::jsonb,
    supported_activities text[] DEFAULT '{}'::text[],
    last_federation_sync timestamp with time zone,
    
    -- Admin & moderation
    is_admin boolean DEFAULT false,
    is_moderator boolean DEFAULT false,
    is_suspended boolean DEFAULT false,
    suspended_at timestamp with time zone,
    suspension_reason text,
    force_sensitive boolean DEFAULT false,
    is_silenced boolean DEFAULT false,
    silenced_at timestamp with time zone,
    silenced_reason text,
    
    -- Denormalized counts (maintained by triggers)
    followers_count integer DEFAULT 0,
    following_count integer DEFAULT 0,
    posts_count integer DEFAULT 0,
    
    -- Auth reference
    auth_user_id uuid UNIQUE,
    
    -- Profile customization
    banner_url text,
    appearance_settings jsonb,
    locale text DEFAULT 'en'::text,
    profile_fields jsonb DEFAULT '[]'::jsonb,
    custom_status jsonb,
    last_status_update timestamp with time zone DEFAULT now(),

    -- Denormalized activity counters (kept up to date by triggers; see
    -- 40_triggers.sql -> tg_profile_message_counter / tg_profile_voice_counter
    -- and migrations/20260524_bot_grants_and_activity_counters.sql).
    message_count bigint NOT NULL DEFAULT 0,
    voice_minutes bigint NOT NULL DEFAULT 0,

    -- Federation settings
    federation_enabled boolean DEFAULT true,
    federation_discoverable boolean DEFAULT true,
    federation_followers_only boolean DEFAULT false,
    manually_approves_followers boolean DEFAULT false,

    web_handle text GENERATED ALWAYS AS (
        CASE
            WHEN COALESCE(is_local, true) THEN '@' || username
            WHEN domain IS NOT NULL AND domain <> '' THEN '@' || username || '@' || domain
            ELSE '@' || username
        END
    ) STORED,

    CONSTRAINT profiles_username_check CHECK (username ~* '^[a-zA-Z0-9_]+$'),
    -- `display_name` is optional (some federated profiles may legitimately
    -- omit it), but if present it must contain at least one non-whitespace
    -- character. A blank display name makes the user appear as
    -- `Unknown User` everywhere via the `getUserDisplayName` fallback,
    -- which is confusing UX and a passive impersonation surface.
    CONSTRAINT profiles_display_name_not_blank CHECK (
        display_name IS NULL OR length(btrim(display_name)) > 0
    ),
    -- Length backstops. The sanitize_profile_text() BEFORE trigger already
    -- clamps these on every write (local + federated), so these constraints
    -- should never fire in practice -- they make the invariant explicit and
    -- enforced even if the trigger is ever dropped/bypassed.
    CONSTRAINT profiles_username_length_check CHECK (
        username IS NULL OR char_length(username) <= 64
    ),
    CONSTRAINT profiles_display_name_length_check CHECK (
        display_name IS NULL OR char_length(display_name) <= 80
    ),
    CONSTRAINT profiles_bio_length_check CHECK (
        bio IS NULL OR char_length(bio) <= 500
    ),
    CONSTRAINT profiles_username_domain_key UNIQUE (username, domain)
);

-- Link profiles to auth.users
ALTER TABLE public.profiles 
    ADD CONSTRAINT profiles_auth_user_id_fkey 
    FOREIGN KEY (auth_user_id) REFERENCES auth.users(id) ON DELETE CASCADE;

-- Full replica identity for realtime
ALTER TABLE public.profiles REPLICA IDENTITY FULL;

-- Unique constraint on federated_id for federation (ON CONFLICT upserts)
ALTER TABLE public.profiles
    ADD CONSTRAINT profiles_federated_id_unique UNIQUE (federated_id);

-- Index for username lookups
CREATE INDEX IF NOT EXISTS idx_profiles_username ON public.profiles(username);
CREATE INDEX IF NOT EXISTS idx_profiles_domain ON public.profiles(domain);
CREATE INDEX IF NOT EXISTS idx_profiles_username_domain ON public.profiles(username, domain);
CREATE INDEX IF NOT EXISTS idx_profiles_is_local ON public.profiles(is_local);

COMMENT ON TABLE public.profiles IS 'User profiles - both local and federated users';
COMMENT ON COLUMN public.profiles.domain IS 'Instance domain (e.g., harmony.example.com)';
COMMENT ON COLUMN public.profiles.federated_id IS 'Full ActivityPub actor URL';
COMMENT ON COLUMN public.profiles.is_local IS 'True if user is from this instance';
COMMENT ON COLUMN public.profiles.web_handle IS 'Precomputed @handle for UI (local @user, remote @user@domain)';

-- ---------------------------------------------------------------------------
-- INSTANCE CONFIG - Server-wide configuration
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.instance_config (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    config_key text NOT NULL UNIQUE,
    config_value jsonb NOT NULL,
    description text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    updated_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL
);

-- Note: Default instance config is seeded in 98_seed_data.sql

COMMENT ON TABLE public.instance_config IS 'Server-wide configuration settings';

-- ---------------------------------------------------------------------------
-- OAUTH PROVIDERS - For OAuth login providers
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.oauth_providers (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    provider_name text NOT NULL UNIQUE,
    client_id text NOT NULL,
    client_secret text,
    enabled boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    settings jsonb DEFAULT '{}'::jsonb
);

COMMENT ON TABLE public.oauth_providers IS 'OAuth provider configurations';

-- ---------------------------------------------------------------------------
-- SESSIONS / DEVICES
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.user_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    session_token text NOT NULL,
    
    -- Device/browser info
    platform text DEFAULT 'web'::text,
    form_factor text DEFAULT 'desktop'::text,
    is_pwa boolean DEFAULT false,
    browser text,
    user_agent text,
    ip_address text,
    
    -- Activity tracking
    last_heartbeat timestamp with time zone DEFAULT now() NOT NULL,
    last_activity timestamp with time zone DEFAULT now() NOT NULL,
    is_active boolean DEFAULT true,
    status text DEFAULT 'online'::text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    
    -- Current context (for smart notifications)
    -- Note: No FK constraints to avoid circular dependencies
    current_server_id uuid,
    current_channel_id uuid,
    current_conversation_id uuid,
    
    UNIQUE(user_id, session_token)
);

CREATE INDEX IF NOT EXISTS idx_user_sessions_user_id ON public.user_sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_user_sessions_active ON public.user_sessions(is_active) WHERE is_active = true;

COMMENT ON TABLE public.user_sessions IS 'Tracks active user sessions for smart push notifications. If user has an active session, push notifications are suppressed (Discord-like behavior).';

DO $$
BEGIN
    RAISE NOTICE 'Core tables created successfully';
END $$;


-- ==== 03_tables_social.sql ====
-- =============================================================================
-- Harmony Database Schema - Social Tables
-- =============================================================================
-- Tables for social features: posts, follows, interactions
-- =============================================================================

-- ---------------------------------------------------------------------------
-- POSTS - Timeline posts (Mastodon-style)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.posts (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    -- Author
    author_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    -- Content
    content jsonb NOT NULL,
    content_warning text,
    language text DEFAULT 'en'::text,
    
    -- ActivityPub
    ap_id text,
    ap_type text DEFAULT 'Note'::text,
    url text,
    
    -- Reply chain
    in_reply_to uuid REFERENCES public.posts(id) ON DELETE SET NULL,
    conversation_id uuid,
    conversation_root_id uuid,
    
    -- Visibility: public, unlisted, followers, direct
    visibility text DEFAULT 'public'::text,
    
    -- Local/Federation state
    is_local boolean DEFAULT true,
    is_federated boolean DEFAULT true,
    federation_status text DEFAULT 'pending'::text,
    federated_to text[] DEFAULT '{}'::text[],
    last_federated_at timestamp with time zone,
    
    -- Denormalized counts
    replies_count integer DEFAULT 0,
    reblogs_count integer DEFAULT 0,
    favorites_count integer DEFAULT 0,
    
    -- Media
    media_attachments jsonb DEFAULT '[]'::jsonb,
    voice_attachments jsonb DEFAULT '[]'::jsonb,
    
    -- Metadata
    metadata jsonb DEFAULT '{}'::jsonb,
    is_sensitive boolean DEFAULT false,
    
    -- Soft delete
    is_deleted boolean DEFAULT false,
    deleted_at timestamp with time zone,
    
    -- Edit history
    edit_history jsonb DEFAULT '[]'::jsonb,
    
    -- Reblog support (embedded reblog data for performance)
    reblog jsonb,
    reblog_author jsonb,
    
    -- Pin to profile
    is_pinned boolean DEFAULT false,
    
    -- Denormalized user interaction states (computed per-user in queries)
    -- These are placeholder columns used by RPC functions
    is_favorited boolean DEFAULT false,
    is_reblogged boolean DEFAULT false,
    is_bookmarked boolean DEFAULT false,
    
    -- Constraints
    CONSTRAINT posts_content_is_array CHECK (jsonb_typeof(content) = 'array'),
    CONSTRAINT posts_content_not_empty CHECK (jsonb_array_length(content) > 0 OR reblog IS NOT NULL),
    CONSTRAINT posts_visibility_check CHECK (visibility IN ('public', 'unlisted', 'followers', 'direct')),
    CONSTRAINT posts_federation_status_check CHECK (federation_status IN ('pending', 'queued', 'processing', 'completed', 'failed', 'skipped')),
    CONSTRAINT posts_content_warning_length_check CHECK (content_warning IS NULL OR char_length(content_warning) <= 200)
);

ALTER TABLE public.posts REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_posts_author_id ON public.posts(author_id);
CREATE INDEX IF NOT EXISTS idx_posts_created_at ON public.posts(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_posts_visibility ON public.posts(visibility);
CREATE INDEX IF NOT EXISTS idx_posts_is_local ON public.posts(is_local);
-- UNIQUE: federated posts are keyed by ap_id; the check-then-insert path in
-- ActivityProcessor relies on this to be race-proof against concurrent delivery.
CREATE UNIQUE INDEX IF NOT EXISTS idx_posts_ap_id ON public.posts(ap_id) WHERE ap_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_posts_in_reply_to ON public.posts(in_reply_to) WHERE in_reply_to IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_posts_conversation_id ON public.posts(conversation_id) WHERE conversation_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_posts_conversation_root ON public.posts(conversation_root_id) WHERE conversation_root_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_posts_not_deleted ON public.posts(created_at DESC) WHERE is_deleted = false;

COMMENT ON TABLE public.posts IS 'Timeline posts - federated with Mastodon/Misskey';
COMMENT ON COLUMN public.posts.conversation_root_id IS 'UUID of the root post in this ActivityPub conversation thread. Enables O(1) conversation lookups.';
COMMENT ON COLUMN public.posts.is_favorited IS 'Whether the current user has favorited this post (computed in queries)';
COMMENT ON COLUMN public.posts.is_reblogged IS 'Whether the current user has reblogged this post (computed in queries)';
COMMENT ON COLUMN public.posts.is_bookmarked IS 'Whether the current user has bookmarked this post (computed in queries)';
COMMENT ON CONSTRAINT posts_content_not_empty ON public.posts IS 'Ensures posts have content OR are reblogs. Pure reblogs can have empty content if reblog field is present.';

-- ---------------------------------------------------------------------------
-- FOLLOWS - Following relationships
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.follows (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    
    follower_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    following_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    -- Federation
    ap_id text,
    accepted_at timestamp with time zone,
    
    -- Status: pending (awaiting approval), accepted, rejected
    status text DEFAULT 'pending'::text,
    is_local boolean DEFAULT true,
    metadata jsonb DEFAULT '{}'::jsonb,
    federation_status text DEFAULT 'pending'::text,
    
    UNIQUE(follower_id, following_id),
    CONSTRAINT follows_no_self_follow CHECK (follower_id != following_id),
    CONSTRAINT follows_status_check CHECK (status IN ('pending', 'accepted', 'rejected')),
    CONSTRAINT follows_federation_status_check CHECK (federation_status IN ('pending', 'queued', 'processing', 'completed', 'failed', 'skipped'))
);

ALTER TABLE public.follows REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_follows_follower_id ON public.follows(follower_id);
CREATE INDEX IF NOT EXISTS idx_follows_following_id ON public.follows(following_id);
CREATE INDEX IF NOT EXISTS idx_follows_status ON public.follows(status);

COMMENT ON TABLE public.follows IS 'User following relationships';
COMMENT ON COLUMN public.follows.follower_id IS 'ID of the user doing the following. This is the source of the follow relationship (follower_id -> following_id)';
COMMENT ON COLUMN public.follows.following_id IS 'ID of the user being followed. IMPORTANT: Code should use following_id, NOT followed_id. This is the target of the follow relationship (follower_id -> following_id)';

-- ---------------------------------------------------------------------------
-- POST INTERACTIONS - Likes, reblogs, emoji reactions
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.post_interactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    post_id uuid NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE,
    
    -- Type: favorite, reblog, emoji_reaction, bookmark
    interaction_type text NOT NULL,
    
    -- For emoji reactions. The FK is added in 04_tables_servers.sql: emojis
    -- is created there, after this file.
    emoji_id uuid,
    custom_emoji_content text,
    
    -- Federation
    is_local boolean DEFAULT true,
    federation_status text DEFAULT 'pending'::text,
    ap_id text,
    metadata jsonb DEFAULT '{}'::jsonb,
    
    CONSTRAINT post_interactions_type_check CHECK (interaction_type IN ('favorite', 'reblog', 'emoji_reaction', 'bookmark')),
    CONSTRAINT post_interactions_federation_status_check CHECK (federation_status IN ('pending', 'queued', 'processing', 'completed', 'failed', 'skipped')),
    CONSTRAINT post_interactions_custom_emoji_length_check CHECK (custom_emoji_content IS NULL OR char_length(custom_emoji_content) <= 256)
);

ALTER TABLE public.post_interactions REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_post_interactions_user_id ON public.post_interactions(user_id);
CREATE INDEX IF NOT EXISTS idx_post_interactions_post_id ON public.post_interactions(post_id);
CREATE INDEX IF NOT EXISTS idx_post_interactions_type ON public.post_interactions(interaction_type);

-- Unique constraint for non-emoji interactions
CREATE UNIQUE INDEX IF NOT EXISTS idx_post_interactions_unique
    ON public.post_interactions(user_id, post_id, interaction_type)
    WHERE interaction_type != 'emoji_reaction';

-- One row per (user, post, emoji). The index above excludes emoji reactions because a user
-- may hold several distinct ones on a post; without this they are covered by no unique index
-- at all, any ON CONFLICT target raises 42P10, and update_post_reaction_counts adds 1 to
-- favorites_count per duplicate row.
--
-- NULLS NOT DISTINCT rather than COALESCE sentinels: emoji_id is null on a unicode or remote
-- reaction, custom_emoji_content is null on an emoji_id-only row, and the nil uuid and the
-- empty string are both legal values a sentinel would collide with. NULLS NOT DISTINCT is
-- PostgreSQL 15+; prod and staging dump as 15.8 and every image in the repo is
-- supabase/postgres:15.8.x.
CREATE UNIQUE INDEX IF NOT EXISTS idx_post_interactions_emoji_unique
    ON public.post_interactions(user_id, post_id, emoji_id, custom_emoji_content)
    NULLS NOT DISTINCT
    WHERE interaction_type = 'emoji_reaction';

COMMENT ON TABLE public.post_interactions IS 'Post likes, reblogs, emoji reactions, and bookmarks';

-- ---------------------------------------------------------------------------
-- HASHTAGS - With trending support
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.hashtags (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    
    -- Tag name
    tag text NOT NULL,
    normalized_tag text NOT NULL,
    
    -- Usage counts
    total_uses integer DEFAULT 0,
    daily_uses integer DEFAULT 0,
    weekly_uses integer DEFAULT 0,
    
    -- Peak tracking
    peak_daily_uses integer DEFAULT 0,
    peak_daily_date date,
    
    -- Timestamps
    first_used_at timestamp with time zone DEFAULT now(),
    last_used_at timestamp with time zone DEFAULT now(),
    
    -- Trending
    trending_score numeric DEFAULT 0,
    trending_rank integer,
    last_trending_update timestamp with time zone,
    
    UNIQUE(normalized_tag)
);

CREATE INDEX IF NOT EXISTS idx_hashtags_tag ON public.hashtags(tag);
CREATE INDEX IF NOT EXISTS idx_hashtags_normalized ON public.hashtags(normalized_tag);
CREATE INDEX IF NOT EXISTS idx_hashtags_trending ON public.hashtags(trending_score DESC);
CREATE INDEX IF NOT EXISTS idx_hashtags_daily_uses ON public.hashtags(daily_uses DESC);

COMMENT ON TABLE public.hashtags IS 'Hashtag registry for trending and discovery';

-- ---------------------------------------------------------------------------
-- POST HASHTAGS - Junction table
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.post_hashtags (
    post_id uuid NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE,
    hashtag_id uuid NOT NULL REFERENCES public.hashtags(id) ON DELETE CASCADE,
    created_at timestamp with time zone DEFAULT now(),
    position_in_content integer DEFAULT 0,
    PRIMARY KEY (post_id, hashtag_id)
);

CREATE INDEX IF NOT EXISTS idx_post_hashtags_hashtag ON public.post_hashtags(hashtag_id);
CREATE INDEX IF NOT EXISTS idx_post_hashtags_created ON public.post_hashtags(created_at DESC);

-- ---------------------------------------------------------------------------
-- USER BLOCKS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.user_blocks (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    blocker_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    blocked_user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    -- Block type: full, posts_only, interactions_only
    block_type text DEFAULT 'full'::text,
    reason text,
    expires_at timestamp with time zone,
    
    -- Federation
    metadata jsonb DEFAULT '{}'::jsonb,
    ap_id text,
    is_federated boolean DEFAULT false,
    federation_status text DEFAULT 'pending'::text,
    
    UNIQUE(blocker_id, blocked_user_id),
    CONSTRAINT user_blocks_no_self_block CHECK (blocker_id != blocked_user_id),
    CONSTRAINT user_blocks_block_type_check CHECK (block_type IN ('full', 'posts_only', 'interactions_only')),
    CONSTRAINT user_blocks_federation_status_check CHECK (federation_status IN ('pending', 'queued', 'processing', 'completed', 'failed', 'skipped'))
);

ALTER TABLE public.user_blocks REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_user_blocks_blocker ON public.user_blocks(blocker_id);
CREATE INDEX IF NOT EXISTS idx_user_blocks_blocked ON public.user_blocks(blocked_user_id);
CREATE INDEX IF NOT EXISTS idx_user_blocks_blocker_blocked ON public.user_blocks(blocker_id, blocked_user_id);
CREATE INDEX IF NOT EXISTS idx_user_blocks_blocked_blocker ON public.user_blocks(blocked_user_id, blocker_id);

COMMENT ON TABLE public.user_blocks IS 'User-level blocking with granular control and optional expiration';
COMMENT ON COLUMN public.user_blocks.ap_id IS 'ActivityPub ID for federated Block activities';
COMMENT ON COLUMN public.user_blocks.is_federated IS 'Whether this block was received via federation';

-- ---------------------------------------------------------------------------
-- TIMELINE ENTRIES - Cached timeline for fast retrieval
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.timeline_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    post_id uuid NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE,
    timeline_type text DEFAULT 'home'::text,
    position bigint NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    
    UNIQUE(user_id, post_id, timeline_type),
    CONSTRAINT timeline_entries_timeline_type_check CHECK (timeline_type = ANY (ARRAY['home'::text, 'public'::text, 'local'::text, 'notifications'::text]))
);

ALTER TABLE public.timeline_entries REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_timeline_entries_user_type ON public.timeline_entries(user_id, timeline_type);
CREATE INDEX IF NOT EXISTS idx_timeline_entries_position ON public.timeline_entries(user_id, timeline_type, position DESC);

COMMENT ON TABLE public.timeline_entries IS 'Cached timeline entries for fast feed retrieval';

-- ---------------------------------------------------------------------------
-- USER LISTS - Mastodon-style lists for organizing followed accounts
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.user_lists (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    -- Owner of the list
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    -- List metadata
    title text NOT NULL,
    description text,
    
    -- Visibility controls
    -- 'followed': Only show replies to other list members
    -- 'list': Only show replies to list members  
    -- 'none': Hide all replies
    replies_policy text DEFAULT 'list'::text,
    
    -- Whether the list is exclusive (members removed from home timeline)
    is_exclusive boolean DEFAULT false,
    
    -- Whether the list can be viewed by others
    is_public boolean DEFAULT false,
    
    -- ActivityPub federation
    federated_id text,
    ap_id text,
    is_local boolean DEFAULT true,
    
    CONSTRAINT user_lists_replies_policy_check 
        CHECK (replies_policy IN ('followed', 'list', 'none')),
    CONSTRAINT user_lists_title_length_check CHECK (char_length(title) <= 100),
    CONSTRAINT user_lists_description_length_check CHECK (description IS NULL OR char_length(description) <= 500)
);

ALTER TABLE public.user_lists REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_user_lists_user_id ON public.user_lists(user_id);
CREATE INDEX IF NOT EXISTS idx_user_lists_created_at ON public.user_lists(created_at);
CREATE UNIQUE INDEX IF NOT EXISTS user_lists_federated_id_key 
    ON public.user_lists(federated_id) WHERE federated_id IS NOT NULL;

COMMENT ON TABLE public.user_lists IS 'User-created lists for organizing followed accounts (Mastodon-compatible)';
COMMENT ON COLUMN public.user_lists.replies_policy IS 'Controls which replies are shown: followed, list, or none';
COMMENT ON COLUMN public.user_lists.is_exclusive IS 'When true, list members are hidden from home timeline';

-- ---------------------------------------------------------------------------
-- USER LIST MEMBERS - Junction table for list membership
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.user_list_members (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    
    -- The list this membership belongs to
    list_id uuid NOT NULL REFERENCES public.user_lists(id) ON DELETE CASCADE,
    
    -- The user being added to the list (must be followed by list owner)
    account_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    -- Unique constraint: a user can only be in a list once
    CONSTRAINT user_list_members_unique UNIQUE (list_id, account_id)
);

ALTER TABLE public.user_list_members REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_user_list_members_list_id ON public.user_list_members(list_id);
CREATE INDEX IF NOT EXISTS idx_user_list_members_account_id ON public.user_list_members(account_id);

COMMENT ON TABLE public.user_list_members IS 'Membership junction table for user lists';

DO $$
BEGIN
    RAISE NOTICE 'Social tables created successfully';
END $$;


-- ==== 04_tables_servers.sql ====
-- =============================================================================
-- Harmony Database Schema - Server Tables
-- =============================================================================
-- Discord-like servers, channels, and messages
-- =============================================================================

-- ---------------------------------------------------------------------------
-- SERVERS (Discord-like communities)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.servers (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    name text NOT NULL,
    description text,
    -- NULL means "no custom icon"; the UI renders the bundled default asset.
    -- Never store the default as a sentinel string - it leaks into federation.
    icon text,
    banner text,
    
    -- Owner. NULL when the owner's profile was deleted; administrators
    -- manage the server until ownership is claimed/transferred.
    owner uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    
    -- Settings
    public boolean DEFAULT false,
    allow_cross_server_emojis boolean DEFAULT true,
    
    -- Federation
    is_local_server boolean DEFAULT true,
    federation_enabled boolean DEFAULT false,
    federation_domain text,
    federation_inbox_url text,
    federation_metadata jsonb DEFAULT '{}'::jsonb,
    supported_activities text[] DEFAULT '{}'::text[],
    ap_id text,
    host_domain text,
    
    -- Invite code
    invite_code text UNIQUE,

    -- WebFinger/federation handle (acct:{slug}@domain). Unique among local
    -- servers; NULL for remote servers. Auto-assigned by trg_assign_server_slug.
    slug text,
    
    -- Member count (denormalized)
    member_count integer DEFAULT 0,

    -- Featured communities (admin-managed)
    is_featured boolean DEFAULT false,
    featured_order integer DEFAULT 0,

    -- Owner-set rules (string array) agreed to in the invite accept flow
    rules jsonb NOT NULL DEFAULT '[]'::jsonb,

    -- Length backstops (sanitize_server_text() trigger clamps on every write)
    CONSTRAINT servers_rules_shape_check CHECK (jsonb_typeof(rules) = 'array' AND jsonb_array_length(rules) <= 25),
    CONSTRAINT servers_name_length_check CHECK (char_length(name) <= 100),
    CONSTRAINT servers_description_length_check CHECK (description IS NULL OR char_length(description) <= 500),
    CONSTRAINT servers_slug_format CHECK (slug IS NULL OR slug ~ '^[a-z0-9][a-z0-9_-]{0,63}$')
);

ALTER TABLE public.servers REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_servers_owner ON public.servers(owner);
CREATE INDEX IF NOT EXISTS idx_servers_invite_code ON public.servers(invite_code) WHERE invite_code IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_servers_federation ON public.servers(federation_enabled, is_local_server);
CREATE INDEX IF NOT EXISTS idx_servers_ap_id ON public.servers(ap_id) WHERE ap_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_servers_featured ON public.servers(is_featured, featured_order) WHERE is_featured = true;
CREATE UNIQUE INDEX IF NOT EXISTS idx_servers_slug_local ON public.servers (lower(slug)) WHERE is_local_server = true AND slug IS NOT NULL;

COMMENT ON TABLE public.servers IS 'Discord-like community servers';
COMMENT ON COLUMN public.servers.allow_cross_server_emojis IS 'Whether server emojis can be used in other servers';
COMMENT ON COLUMN public.servers.ap_id IS 'ActivityPub ID for this server (Group actor)';
COMMENT ON COLUMN public.servers.host_domain IS 'Domain where this server is hosted (null if local)';
COMMENT ON COLUMN public.servers.is_local_server IS 'True if server is hosted on this instance';

-- ---------------------------------------------------------------------------
-- CHANNEL CATEGORIES
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.channel_categories (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    server_id uuid NOT NULL REFERENCES public.servers(id) ON DELETE CASCADE,
    name text NOT NULL,
    "order" integer DEFAULT 0,
    
    -- Federation
    federation_status text DEFAULT 'pending'::text,

    CONSTRAINT channel_categories_name_length_check CHECK (char_length(name) <= 100)
);

CREATE INDEX IF NOT EXISTS idx_channel_categories_server ON public.channel_categories(server_id);
CREATE INDEX IF NOT EXISTS idx_channel_categories_federation_status ON public.channel_categories(federation_status) WHERE federation_status = 'pending';

COMMENT ON TABLE public.channel_categories IS 'Channel category groupings within servers';

-- ---------------------------------------------------------------------------
-- CHANNELS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.channels (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    server_id uuid REFERENCES public.servers(id) ON DELETE CASCADE,
    category uuid REFERENCES public.channel_categories(id) ON DELETE SET NULL,
    
    name text NOT NULL,
    description text,
    
    -- Type: 0=text, 1=voice, 2=category
    type smallint DEFAULT 0,
    "order" integer DEFAULT 0,
    
    slowmode_seconds integer DEFAULT 0,
    
    -- Federation
    ap_id text,
    is_remote boolean DEFAULT false,
    federation_status text DEFAULT 'pending'::text,
    
    CONSTRAINT channels_federation_status_check CHECK (federation_status IN ('pending', 'queued', 'processing', 'completed', 'failed', 'skipped')),
    CONSTRAINT channels_name_length_check CHECK (char_length(name) <= 100),
    CONSTRAINT channels_description_length_check CHECK (description IS NULL OR char_length(description) <= 1024)
);

ALTER TABLE public.channels REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_channels_server ON public.channels(server_id);
CREATE INDEX IF NOT EXISTS idx_channels_category ON public.channels(category);
CREATE INDEX IF NOT EXISTS idx_channels_federation_status ON public.channels(federation_status) WHERE federation_status = 'pending';
-- Upserted ON CONFLICT (ap_id). Full, not partial: ON CONFLICT infers a full index
-- only, and NULLs are distinct, so a NULL ap_id is unconstrained.
CREATE UNIQUE INDEX IF NOT EXISTS idx_channels_ap_id ON public.channels(ap_id);

COMMENT ON TABLE public.channels IS 'Server channels (text and voice)';

-- ---------------------------------------------------------------------------
-- MESSAGES
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    
    -- Author (either user or bot, mutually exclusive)
    user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    bot_id uuid,
    
    -- Location (either channel or conversation, mutually exclusive)
    channel_id uuid REFERENCES public.channels(id) ON DELETE CASCADE,
    conversation_id uuid,
    
    -- Thread support
    thread_id uuid,
    reply_to uuid REFERENCES public.messages(id) ON DELETE SET NULL,
    
    -- Content
    content jsonb NOT NULL,
    
    -- Message state
    is_deleted boolean DEFAULT false,
    is_system boolean DEFAULT false,
    is_pinned boolean DEFAULT false,
    pinned_at timestamp with time zone,
    pinned_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    
    -- Encryption
    encrypted boolean DEFAULT false,
    encryption_metadata jsonb,
    megolm_session_id text,
    megolm_message_index integer,
    
    -- Legacy reactions array (deprecated, use reactions table)
    reactions uuid[],
    
    -- Federation
    federation_status text DEFAULT 'pending'::text,
    metadata jsonb DEFAULT '{}'::jsonb,
    
    CONSTRAINT messages_content_is_array CHECK (jsonb_typeof(content) = 'array'),
    CONSTRAINT messages_content_not_empty CHECK (jsonb_array_length(content) > 0),
    CONSTRAINT messages_federation_status_check CHECK (federation_status IN ('pending', 'queued', 'processing', 'completed', 'failed', 'skipped')),
    -- At most one author. Both NULL is a message from a deleted user; both set
    -- is the only rejected combination.
    CONSTRAINT messages_user_or_bot_check CHECK (
        (user_id IS NULL) OR (bot_id IS NULL)
    )
    -- NOTE: per-message text length is enforced by `messages_text_length_check`
    -- added in `10_functions_core.sql` after the helper function is defined.
);

ALTER TABLE public.messages REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_messages_channel ON public.messages(channel_id);
CREATE INDEX IF NOT EXISTS idx_messages_conversation ON public.messages(conversation_id);
CREATE INDEX IF NOT EXISTS idx_messages_user ON public.messages(user_id);
CREATE INDEX IF NOT EXISTS idx_messages_created ON public.messages(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_messages_thread ON public.messages(thread_id) WHERE thread_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_messages_channel_created_main
  ON public.messages (channel_id, created_at DESC)
  WHERE thread_id IS NULL AND (is_deleted IS NULL OR is_deleted = false);

CREATE INDEX IF NOT EXISTS idx_messages_conversation_created
  ON public.messages (conversation_id, created_at DESC)
  WHERE conversation_id IS NOT NULL
    AND thread_id IS NULL
    AND (is_deleted IS NULL OR is_deleted = false);

CREATE INDEX IF NOT EXISTS idx_messages_thread_created
  ON public.messages (thread_id, created_at ASC)
  WHERE thread_id IS NOT NULL;

COMMENT ON TABLE public.messages IS 'Channel and DM messages';

-- ---------------------------------------------------------------------------
-- THREADS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.threads (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    
    channel_id uuid NOT NULL REFERENCES public.channels(id) ON DELETE CASCADE,
    parent_message_id uuid NOT NULL,
    
    name text NOT NULL,
    created_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    
    archived boolean DEFAULT false,
    archived_at timestamp with time zone,
    auto_archive_duration integer DEFAULT 1440,
    locked boolean DEFAULT false,
    
    -- Denormalized counts
    message_count integer DEFAULT 0,
    member_count integer DEFAULT 0,
    
    last_message_id uuid,
    last_message_at timestamp with time zone,
    
    -- Federation
    ap_id text,
    federation_status text DEFAULT 'pending',

    CONSTRAINT threads_name_length_check CHECK (char_length(name) <= 100)
);

ALTER TABLE public.threads REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_threads_channel ON public.threads(channel_id);
CREATE INDEX IF NOT EXISTS idx_threads_parent_message ON public.threads(parent_message_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_threads_ap_id ON public.threads(ap_id) WHERE ap_id IS NOT NULL;

COMMENT ON TABLE public.threads IS 'Message threads within channels';

-- FK: threads.parent_message_id → messages.id (needed for PostgREST joins in federation)
ALTER TABLE public.threads
    ADD CONSTRAINT threads_parent_message_id_fkey
    FOREIGN KEY (parent_message_id) REFERENCES public.messages(id) ON DELETE CASCADE;

-- Add FK for messages.thread_id after threads table exists
ALTER TABLE public.messages 
    ADD CONSTRAINT messages_thread_id_fkey 
    FOREIGN KEY (thread_id) REFERENCES public.threads(id) ON DELETE SET NULL;

-- ---------------------------------------------------------------------------
-- THREAD MEMBERS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.thread_members (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    thread_id uuid NOT NULL REFERENCES public.threads(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    joined_at timestamp with time zone DEFAULT now() NOT NULL,
    last_read_at timestamp with time zone,
    last_read_message_id uuid,
    muted boolean DEFAULT false,

    UNIQUE(thread_id, user_id)
);

ALTER TABLE public.thread_members REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_thread_members_thread ON public.thread_members(thread_id);
CREATE INDEX IF NOT EXISTS idx_thread_members_user ON public.thread_members(user_id);

-- ---------------------------------------------------------------------------
-- EMOJIS (moved here from 06_tables_misc.sql - reactions FK depends on it)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.emojis (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    name character varying,
    url character varying,
    server_id uuid REFERENCES public.servers(id) ON DELETE CASCADE,
    uploader uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    
    usage_count integer DEFAULT 0,
    last_used timestamp with time zone,
    file_size integer,
    
    domain text,

    -- Ownership scope: 'server' (server_id set), 'instance' (server_id NULL,
    -- e.g. remote imports), or 'user' (personal emoji owned by `uploader`).
    scope text NOT NULL DEFAULT 'server',
    -- True for emoji created via the Klipy AI generation API (a 'user' scope).
    is_ai_generated boolean NOT NULL DEFAULT false,

    CONSTRAINT emojis_name_length_check CHECK (name IS NULL OR char_length(name::text) <= 64),
    CONSTRAINT emojis_scope_check CHECK (scope IN ('server', 'instance', 'user'))
);

-- Deferred from 03_tables_social.sql, which declares post_interactions before
-- emojis exists.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'post_interactions_emoji_id_fkey'
  ) THEN
    ALTER TABLE public.post_interactions
      ADD CONSTRAINT post_interactions_emoji_id_fkey
      FOREIGN KEY (emoji_id) REFERENCES public.emojis(id) ON DELETE SET NULL;
  END IF;
END
$$;

CREATE INDEX IF NOT EXISTS idx_emojis_server ON public.emojis(server_id);
CREATE INDEX IF NOT EXISTS idx_emojis_name ON public.emojis(lower(name::text));
CREATE INDEX IF NOT EXISTS idx_emojis_user ON public.emojis(uploader) WHERE scope = 'user';
CREATE INDEX IF NOT EXISTS idx_emojis_scope ON public.emojis(scope);
CREATE INDEX IF NOT EXISTS idx_emojis_ai_generated
    ON public.emojis(uploader, created_at) WHERE is_ai_generated;

COMMENT ON TABLE public.emojis IS 'Custom emoji library';

-- ---------------------------------------------------------------------------
-- REACTIONS (for messages)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.reactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,

    message_id uuid NOT NULL REFERENCES public.messages(id) ON DELETE CASCADE,
    user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,
    bot_id uuid,  -- For bot reactions

    emoji_id uuid REFERENCES public.emojis(id) ON DELETE CASCADE,
    custom_emoji_content text,

    -- Denormalized from parent message for CDC server-side filtering
    channel_id uuid,
    conversation_id uuid,

    federation_status text DEFAULT 'pending'::text,
    metadata jsonb DEFAULT '{}'::jsonb,

    CONSTRAINT reactions_has_emoji CHECK (emoji_id IS NOT NULL OR custom_emoji_content IS NOT NULL),
    CONSTRAINT reactions_has_author CHECK (user_id IS NOT NULL OR bot_id IS NOT NULL),
    CONSTRAINT reactions_custom_emoji_length_check CHECK (custom_emoji_content IS NULL OR char_length(custom_emoji_content) <= 256)
);

ALTER TABLE public.reactions REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_reactions_message ON public.reactions(message_id);
CREATE INDEX IF NOT EXISTS idx_reactions_user ON public.reactions(user_id);
CREATE INDEX IF NOT EXISTS idx_reactions_channel_id ON public.reactions(channel_id) WHERE channel_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_reactions_conversation_id ON public.reactions(conversation_id) WHERE conversation_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS reactions_message_user_emoji_unique
ON public.reactions (
  message_id,
  user_id,
  COALESCE(emoji_id, '00000000-0000-0000-0000-000000000000'::uuid),
  COALESCE(custom_emoji_content, '')
);

COMMENT ON TABLE public.reactions IS 'Message emoji reactions';

-- Auto-populate channel_id/conversation_id from the parent message on INSERT
CREATE OR REPLACE FUNCTION public.populate_reaction_context()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.channel_id IS NULL AND NEW.conversation_id IS NULL AND NEW.message_id IS NOT NULL THEN
    SELECT m.channel_id, m.conversation_id
    INTO NEW.channel_id, NEW.conversation_id
    FROM messages m
    WHERE m.id = NEW.message_id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_populate_reaction_context ON reactions;
CREATE TRIGGER trg_populate_reaction_context
  BEFORE INSERT ON reactions
  FOR EACH ROW
  EXECUTE FUNCTION populate_reaction_context();

-- ---------------------------------------------------------------------------
-- USER SERVERS (membership)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.user_servers (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    server_id uuid NOT NULL REFERENCES public.servers(id) ON DELETE CASCADE,
    
    -- Status: pending, accepted, banned
    status text DEFAULT 'accepted'::text,
    
    -- Federation
    member_instance text,
    
    -- Nickname in this server
    nickname text,
    
    -- Server organization
    folder_id uuid,  -- References server_folders, added after that table is created
    position integer DEFAULT 0,
    
    -- Notifications
    muted boolean DEFAULT false,
    muted_until timestamp with time zone,

    -- Membership created by a temporary invite; the join is not permanent.
    temporary boolean,

    UNIQUE(user_id, server_id),
    CONSTRAINT user_servers_status_check CHECK (status IN ('pending', 'accepted', 'banned')),
    CONSTRAINT user_servers_nickname_length_check CHECK (nickname IS NULL OR char_length(nickname) <= 64)
);

ALTER TABLE public.user_servers REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_user_servers_user ON public.user_servers(user_id);
CREATE INDEX IF NOT EXISTS idx_user_servers_server ON public.user_servers(server_id);
CREATE INDEX IF NOT EXISTS idx_user_servers_folder_id ON public.user_servers(folder_id);
CREATE INDEX IF NOT EXISTS idx_user_servers_user_position ON public.user_servers(user_id, position);
CREATE INDEX IF NOT EXISTS idx_user_servers_by_instance ON public.user_servers(server_id, member_instance);
CREATE INDEX IF NOT EXISTS idx_user_servers_status ON public.user_servers(server_id, status);
CREATE INDEX IF NOT EXISTS idx_user_servers_user_server ON public.user_servers(user_id, server_id);

COMMENT ON TABLE public.user_servers IS 'Server membership records';
COMMENT ON COLUMN public.user_servers.member_instance IS 'Instance domain of the member (for efficient batching)';
COMMENT ON COLUMN public.user_servers.status IS 'Membership status: pending, accepted, rejected';
COMMENT ON COLUMN public.user_servers.folder_id IS 'Optional folder this server belongs to (null = root level)';
COMMENT ON COLUMN public.user_servers.position IS 'Sort order position within the folder or at root level';

-- ---------------------------------------------------------------------------
-- SERVER ROLES
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.server_roles (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    server_id uuid NOT NULL REFERENCES public.servers(id) ON DELETE CASCADE,
    
    name text NOT NULL,
    color text,
    position integer DEFAULT 0,
    
    -- Permission bits (Discord-style)
    permissions bigint DEFAULT 0,
    
    -- Special flags
    is_default boolean DEFAULT false,
    is_admin boolean DEFAULT false,
    mentionable boolean DEFAULT true,
    hoist boolean DEFAULT false,

    -- Role icon: an uploaded image or a single unicode glyph.
    icon_url text,
    unicode_emoji text,

    -- ActivityPub id when the role originates on another instance.
    ap_id text,

    CONSTRAINT server_roles_name_length_check CHECK (char_length(name) <= 100)
);

ALTER TABLE public.server_roles REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_server_roles_server ON public.server_roles(server_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_server_roles_default ON public.server_roles(server_id) WHERE is_default = true;
-- Upserted ON CONFLICT (ap_id). Full index, as above.
CREATE UNIQUE INDEX IF NOT EXISTS idx_server_roles_ap_id ON public.server_roles(ap_id);

COMMENT ON TABLE public.server_roles IS 'Server role definitions';

-- ---------------------------------------------------------------------------
-- USER ROLES (role assignments)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.user_roles (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    role_id uuid NOT NULL REFERENCES public.server_roles(id) ON DELETE CASCADE,
    server_id uuid NOT NULL REFERENCES public.servers(id) ON DELETE CASCADE,
    assigned_at timestamp with time zone DEFAULT now(),
    assigned_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    
    UNIQUE(user_id, role_id)
);

ALTER TABLE public.user_roles REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_user_roles_user ON public.user_roles(user_id);
CREATE INDEX IF NOT EXISTS idx_user_roles_server ON public.user_roles(server_id);

COMMENT ON TABLE public.user_roles IS 'User role assignments';

-- ---------------------------------------------------------------------------
-- CONVERSATIONS (DMs)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.conversations (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    
    -- Conversation info
    name text,
    type text DEFAULT 'direct'::text,
    created_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    is_active boolean DEFAULT true,
    
    -- Metadata for federation etc.
    metadata jsonb DEFAULT '{}'::jsonb,
    
    CONSTRAINT conversations_type_check CHECK (type IN ('direct', 'group', 'channel')),
    CONSTRAINT conversations_name_length_check CHECK (name IS NULL OR char_length(name) <= 100)
);

ALTER TABLE public.conversations REPLICA IDENTITY FULL;

-- Add FK to messages.conversation_id
ALTER TABLE public.messages 
    ADD CONSTRAINT messages_conversation_id_fkey 
    FOREIGN KEY (conversation_id) REFERENCES public.conversations(id) ON DELETE CASCADE;

COMMENT ON TABLE public.conversations IS 'DM conversations between users. Supports both local users (in auth.users) and federated users (profiles only). Foreign keys reference profiles to enable federated DMs.';

-- ---------------------------------------------------------------------------
-- CONVERSATION PARTICIPANTS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.conversation_participants (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    role text DEFAULT 'member'::text,
    joined_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    left_at timestamp with time zone,
    
    -- Last read tracking
    last_read_at timestamp with time zone,
    last_read_message_id uuid,

    -- Notifications
    is_muted boolean DEFAULT false,

    -- Per-user dismissal: hide the conversation from this user's list without
    -- deleting it or leaving. Cleared (set back to NULL) when the conversation
    -- is reopened or a newer message arrives, so it reappears on new activity.
    hidden_at timestamp with time zone,

    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    
    CONSTRAINT conversation_participants_role_check CHECK (role = ANY (ARRAY['admin'::text, 'member'::text])),
    UNIQUE(conversation_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_conversation_participants_conversation ON public.conversation_participants(conversation_id);
CREATE INDEX IF NOT EXISTS idx_conversation_participants_user ON public.conversation_participants(user_id);
CREATE INDEX IF NOT EXISTS idx_conversation_participants_conv_user ON public.conversation_participants(conversation_id, user_id);

COMMENT ON TABLE public.conversation_participants IS 'DM conversation participants';

-- ---------------------------------------------------------------------------
-- INVITES
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.invites (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    code text NOT NULL UNIQUE,
    server_id uuid NOT NULL REFERENCES public.servers(id) ON DELETE CASCADE,
    channel_id uuid REFERENCES public.channels(id) ON DELETE SET NULL,
    created_by uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    created_at timestamp with time zone DEFAULT now(),
    expires_at timestamp with time zone,
    max_uses integer,
    uses integer DEFAULT 0,
    used boolean DEFAULT false,
    temporary boolean DEFAULT false,

    CONSTRAINT invites_code_format_check CHECK (code ~ '^[A-Za-z0-9_-]{1,64}$')
);

CREATE INDEX IF NOT EXISTS idx_invites_code ON public.invites(code);
CREATE INDEX IF NOT EXISTS idx_invites_server ON public.invites(server_id);

COMMENT ON TABLE public.invites IS 'Server invite links';

-- ---------------------------------------------------------------------------
-- VOICE CHANNEL PARTICIPANTS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.voice_channel_participants (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    channel_id uuid NOT NULL REFERENCES public.channels(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    server_id uuid NOT NULL REFERENCES public.servers(id) ON DELETE CASCADE,
    joined_at timestamp with time zone DEFAULT now() NOT NULL,
    
    -- Federation
    is_federated boolean DEFAULT false NOT NULL,
    federation_status text DEFAULT 'local'::text,
    
    -- State
    is_muted boolean DEFAULT false,
    is_deafened boolean DEFAULT false,
    is_video_enabled boolean DEFAULT false,
    is_screen_sharing boolean DEFAULT false,
    
    -- Metadata
    metadata jsonb DEFAULT '{}'::jsonb,
    
    UNIQUE(channel_id, user_id)
);

ALTER TABLE public.voice_channel_participants REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_voice_participants_channel ON public.voice_channel_participants(channel_id);
CREATE INDEX IF NOT EXISTS idx_voice_participants_user ON public.voice_channel_participants(user_id);

COMMENT ON TABLE public.voice_channel_participants IS 'Active voice channel participants';

-- ---------------------------------------------------------------------------
-- SERVER BANS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.server_bans (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    server_id uuid NOT NULL REFERENCES public.servers(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    -- Nullable: the FK is ON DELETE SET NULL, so NOT NULL here would make
    -- deleting a moderator's profile fail instead of clearing the attribution.
    banned_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    reason text,
    delete_message_seconds integer DEFAULT 0,
    created_at timestamp with time zone DEFAULT now() NOT NULL,

    UNIQUE(server_id, user_id),
    CONSTRAINT server_bans_reason_length_check CHECK (reason IS NULL OR char_length(reason) <= 512)
);

ALTER TABLE public.server_bans REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_server_bans_server ON public.server_bans(server_id);
CREATE INDEX IF NOT EXISTS idx_server_bans_user ON public.server_bans(user_id);

COMMENT ON TABLE public.server_bans IS 'Server-level ban records for moderation';

DO $$
BEGIN
    RAISE NOTICE 'Server tables created successfully';
END $$;


-- ==== 05_tables_federation.sql ====
-- =============================================================================
-- Harmony Database Schema - Federation Tables
-- =============================================================================
-- ActivityPub federation: instances, activities, caches
-- =============================================================================

-- ---------------------------------------------------------------------------
-- FEDERATED INSTANCES
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.federated_instances (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    -- Named to match migrations/20260528_federation_instance_hardening.sql; an
    -- inline CHECK would be auto-named and would not.
    domain text NOT NULL UNIQUE,
    CONSTRAINT federated_instances_domain_lowercase CHECK (domain = lower(domain)),
    
    -- Instance info
    software text,
    version text,
    description text,
    admin_contact text,
    
    -- Status
    is_blocked boolean DEFAULT false,
    is_trusted boolean DEFAULT false,
    last_seen_at timestamp with time zone DEFAULT now(),
    
    -- Stats
    user_count integer DEFAULT 0,
    status_count integer DEFAULT 0,
    connection_count integer DEFAULT 0,
    
    -- Metadata
    metadata jsonb DEFAULT '{}'::jsonb
);

ALTER TABLE public.federated_instances REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_federated_instances_domain ON public.federated_instances(domain);

GRANT SELECT ON public.federated_instances TO authenticated;
GRANT ALL ON public.federated_instances TO service_role;

COMMENT ON TABLE public.federated_instances IS 'Known federated instances';

-- ---------------------------------------------------------------------------
-- BLOCKED INSTANCES
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.blocked_instances (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    domain text NOT NULL UNIQUE,
    reason text,
    severity text DEFAULT 'suspend'::text,
    created_at timestamp with time zone DEFAULT now(),
    created_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    blocked_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,

    CONSTRAINT blocked_instances_severity_check CHECK (severity IN ('silence', 'suspend'))
);

CREATE INDEX IF NOT EXISTS idx_blocked_instances_domain ON public.blocked_instances(domain);

GRANT SELECT ON public.blocked_instances TO authenticated;
GRANT ALL ON public.blocked_instances TO service_role;

COMMENT ON TABLE public.blocked_instances IS 'Blocked/defederated instances';

-- ---------------------------------------------------------------------------
-- AP ACTIVITIES - ActivityPub activity log
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.ap_activities (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),

    ap_id text NOT NULL,
    ap_type text NOT NULL,

    actor_id uuid,
    actor_ap_id text NOT NULL,

    object_id text,
    object_type text,
    target_id uuid,
    target_type text,

    activity_data jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'pending'::text,

    to_addresses text[] DEFAULT '{}'::text[],
    cc_addresses text[] DEFAULT '{}'::text[],
    bto_addresses text[] DEFAULT '{}'::text[],
    bcc_addresses text[] DEFAULT '{}'::text[],

    attempts integer DEFAULT 0,
    last_attempt_at timestamp with time zone,
    next_attempt_at timestamp with time zone,
    error_message text,

    is_local boolean DEFAULT true,
    source_domain text,
    origin_domain text,

    CONSTRAINT ap_activities_status_check CHECK (status IN ('pending', 'processing', 'completed', 'failed', 'received', 'processed')),
    CONSTRAINT ap_activities_valid_type CHECK (ap_type IN (
        'Create', 'Update', 'Delete', 'Follow', 'Accept', 'Reject', 'Undo',
        'Like', 'EmojiReaction', 'Announce', 'Add', 'Remove', 'Invite',
        'Join', 'Leave', 'Block', 'Flag', 'Move', 'Tombstone',
        'VoiceJoin', 'VoiceLeave', 'VoiceUpdate',
        'harmony:VoiceCallInvite', 'harmony:VoiceCallAccept',
        'harmony:VoiceCallReject', 'harmony:VoiceCallEnd',
        'harmony:VoiceChannelJoin', 'harmony:VoiceChannelLeave',
        'harmony:VoiceChannelJoinAccept', 'harmony:VoiceChannelJoinReject'
    ))
);

ALTER TABLE public.ap_activities REPLICA IDENTITY FULL;

CREATE UNIQUE INDEX IF NOT EXISTS idx_ap_activities_ap_id ON public.ap_activities(ap_id);
CREATE INDEX IF NOT EXISTS idx_ap_activities_type ON public.ap_activities(ap_type);
CREATE INDEX IF NOT EXISTS idx_ap_activities_actor ON public.ap_activities(actor_ap_id);
CREATE INDEX IF NOT EXISTS idx_ap_activities_status ON public.ap_activities(status);
CREATE INDEX IF NOT EXISTS idx_ap_activities_created ON public.ap_activities(created_at DESC);

GRANT SELECT ON public.ap_activities TO authenticated;
GRANT ALL ON public.ap_activities TO service_role;

COMMENT ON TABLE public.ap_activities IS 'ActivityPub activity log for federation';

-- ---------------------------------------------------------------------------
-- AP ACTOR CACHE - Cached remote actor data
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.ap_actor_cache (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    ap_id text NOT NULL UNIQUE,
    domain text NOT NULL,
    username text NOT NULL,
    actor_data jsonb NOT NULL,
    last_fetched_at timestamp with time zone DEFAULT now(),
    cache_expires_at timestamp with time zone DEFAULT (now() + interval '1 hour'),
    fetch_attempts integer DEFAULT 0,
    is_reachable boolean DEFAULT true,
    last_error text
);

CREATE INDEX IF NOT EXISTS idx_ap_actor_cache_ap_id ON public.ap_actor_cache(ap_id);
CREATE INDEX IF NOT EXISTS idx_ap_actor_cache_domain ON public.ap_actor_cache(domain);

GRANT SELECT ON public.ap_actor_cache TO authenticated;
GRANT ALL ON public.ap_actor_cache TO service_role;

COMMENT ON TABLE public.ap_actor_cache IS 'Cached remote ActivityPub actors';

-- ---------------------------------------------------------------------------
-- AP OBJECT CACHE - Cached remote objects (posts, etc.)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.ap_object_cache (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    object_url text NOT NULL UNIQUE,
    object_type text NOT NULL,
    object_json jsonb NOT NULL,
    
    -- Cache metadata
    fetched_at timestamp with time zone DEFAULT now(),
    expires_at timestamp with time zone DEFAULT (now() + interval '1 hour')
);

CREATE INDEX IF NOT EXISTS idx_ap_object_cache_url ON public.ap_object_cache(object_url);

GRANT SELECT ON public.ap_object_cache TO authenticated;
GRANT ALL ON public.ap_object_cache TO service_role;

COMMENT ON TABLE public.ap_object_cache IS 'Cached remote ActivityPub objects';

-- ---------------------------------------------------------------------------
-- FEDERATION DELIVERY QUEUE
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.federation_delivery_queue (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),

    -- Target inbox
    target_inbox_url text NOT NULL,
    target_domain text NOT NULL,

    -- Activity to deliver
    activity_data jsonb,

    -- Sender (for HTTP signature)
    sender_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,
    actor_username text,
    actor_domain text,

    -- Status
    status text DEFAULT 'pending'::text,
    attempts integer DEFAULT 0,
    max_attempts integer DEFAULT 5,

    -- Timing
    next_attempt_at timestamp with time zone DEFAULT now(),
    last_attempt_at timestamp with time zone,
    delivered_at timestamp with time zone,

    -- Error tracking
    error_message text,
    http_status_code integer,
    response_body text,
    delivery_duration_ms integer,

    -- Priority (1=highest, 10=lowest)
    priority integer DEFAULT 5,

    CONSTRAINT federation_delivery_queue_status_check CHECK (status IN ('pending', 'processing', 'completed', 'failed', 'dead', 'delivered', 'cancelled')),
    CONSTRAINT federation_delivery_queue_priority_check CHECK (priority >= 1 AND priority <= 10)
);

CREATE INDEX IF NOT EXISTS idx_federation_delivery_queue_status ON public.federation_delivery_queue(status);
CREATE INDEX IF NOT EXISTS idx_fdq_next_attempt ON public.federation_delivery_queue(next_attempt_at) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS idx_fdq_target_domain ON public.federation_delivery_queue(target_domain);

COMMENT ON TABLE public.federation_delivery_queue IS 'Queue for outgoing federation deliveries';

GRANT SELECT, DELETE ON public.federation_delivery_queue TO authenticated;
GRANT ALL ON public.federation_delivery_queue TO service_role;

-- ---------------------------------------------------------------------------
-- FEDERATION ENDPOINT HEALTH
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.federation_endpoint_health (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    endpoint_url text NOT NULL UNIQUE,
    domain text NOT NULL,
    is_dead boolean DEFAULT false,
    first_failure_at timestamp with time zone,
    last_success_at timestamp with time zone,
    last_failure_at timestamp with time zone,
    consecutive_failures integer DEFAULT 0,
    total_failures integer DEFAULT 0,
    total_successes integer DEFAULT 0,
    last_http_status integer,
    last_error_message text
);

CREATE INDEX IF NOT EXISTS idx_federation_endpoint_health_url ON public.federation_endpoint_health(endpoint_url);
CREATE INDEX IF NOT EXISTS idx_federation_endpoint_health_domain ON public.federation_endpoint_health(domain);
CREATE INDEX IF NOT EXISTS idx_federation_endpoint_health_dead ON public.federation_endpoint_health(is_dead) WHERE is_dead = true;

COMMENT ON TABLE public.federation_endpoint_health IS 'Tracks health of federation endpoints. Dead after 24-48h of consistent failures.';

GRANT SELECT, DELETE ON public.federation_endpoint_health TO authenticated;
GRANT ALL ON public.federation_endpoint_health TO service_role;

-- ---------------------------------------------------------------------------
-- SERVER FEDERATION EVENTS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.server_federation_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    server_id uuid NOT NULL REFERENCES public.servers(id) ON DELETE CASCADE,
    ap_activity_id uuid REFERENCES public.ap_activities(id) ON DELETE SET NULL,
    event_type text NOT NULL,
    payload jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now()
);

ALTER TABLE public.server_federation_events REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_server_federation_events_server ON public.server_federation_events(server_id);

GRANT SELECT ON public.server_federation_events TO authenticated;
GRANT ALL ON public.server_federation_events TO service_role;

COMMENT ON TABLE public.server_federation_events IS 'Federation events for servers';

-- ---------------------------------------------------------------------------
-- SERVER MEMBERSHIP EVENTS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.server_membership_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    server_id uuid NOT NULL REFERENCES public.servers(id) ON DELETE CASCADE,
    user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    initiated_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    event_type text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now()
);

ALTER TABLE public.server_membership_events REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_server_membership_events_server ON public.server_membership_events(server_id);

GRANT SELECT ON public.server_membership_events TO authenticated;
GRANT ALL ON public.server_membership_events TO service_role;

COMMENT ON TABLE public.server_membership_events IS 'Server membership change events';

-- ---------------------------------------------------------------------------
-- VOICE FEDERATION EVENTS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.voice_federation_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    channel_id uuid NOT NULL REFERENCES public.channels(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    ap_activity_id uuid REFERENCES public.ap_activities(id) ON DELETE SET NULL,
    event_type text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now()
);

ALTER TABLE public.voice_federation_events REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_voice_federation_events_channel ON public.voice_federation_events(channel_id);

GRANT SELECT ON public.voice_federation_events TO authenticated;
GRANT ALL ON public.voice_federation_events TO service_role;

COMMENT ON TABLE public.voice_federation_events IS 'Voice channel federation events';

-- ---------------------------------------------------------------------------
-- FEDERATED VOICE CALLS
-- ---------------------------------------------------------------------------
-- One row per federated DM call invite, keyed by the ActivityPub activity id.
-- ap_id carries a UNIQUE constraint because federation-backend upserts with
-- onConflict: 'ap_id'.
CREATE TABLE IF NOT EXISTS public.federated_voice_calls (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    ap_id text NOT NULL UNIQUE,

    -- caller_id is the mirrored local profile of the remote caller and is NULL
    -- when no mirror exists; caller_federated_id is the authoritative actor URL.
    caller_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,
    caller_federated_id text NOT NULL,
    recipient_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,

    call_type text NOT NULL,
    -- text, not uuid: the id is minted by the calling instance.
    conversation_id text,

    livekit_url text NOT NULL,
    room_name text NOT NULL,

    status text DEFAULT 'pending'::text NOT NULL,

    created_at timestamp with time zone DEFAULT now() NOT NULL,
    accepted_at timestamp with time zone,
    ended_at timestamp with time zone,
    -- 60s ring timeout, matching VoiceActivityHandler.handleVoiceCallInvite.
    expires_at timestamp with time zone DEFAULT (now() + '00:01:00'::interval) NOT NULL,

    CONSTRAINT federated_voice_calls_call_type_check
        CHECK (call_type = ANY (ARRAY['voice'::text, 'video'::text])),
    CONSTRAINT federated_voice_calls_status_check
        CHECK (status = ANY (ARRAY['pending'::text, 'accepted'::text, 'rejected'::text,
                                   'ended'::text, 'expired'::text, 'missed'::text])),
    -- A CHECK, not a foreign key; the name matches production.
    CONSTRAINT fk_recipient_local CHECK (recipient_id IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS idx_federated_voice_calls_caller ON public.federated_voice_calls(caller_id);
CREATE INDEX IF NOT EXISTS idx_federated_voice_calls_status ON public.federated_voice_calls(status);
-- Partial: cleanup_expired_voice_calls and the incoming-call lookup both scan
-- only pending rows.
CREATE INDEX IF NOT EXISTS idx_federated_voice_calls_expires ON public.federated_voice_calls(expires_at)
    WHERE status = 'pending'::text;
CREATE INDEX IF NOT EXISTS idx_federated_voice_calls_recipient ON public.federated_voice_calls(recipient_id)
    WHERE status = 'pending'::text;

-- The image's schema-wide default privileges hand anon and authenticated
-- arwdDxt on every new table in public, so a GRANT alone leaves the write bits
-- set. Rows here are an authorization input: LiveKitService.validateFederatedRoomAccess
-- admits a remote actor to a LiveKit room on the strength of one. Every writer
-- is federation-backend, which connects as service_role.
REVOKE ALL ON public.federated_voice_calls FROM anon;
REVOKE ALL ON public.federated_voice_calls FROM authenticated;
GRANT SELECT ON public.federated_voice_calls TO authenticated;
GRANT ALL ON public.federated_voice_calls TO service_role;

COMMENT ON TABLE public.federated_voice_calls IS 'Federated DM voice/video call invites';

-- ---------------------------------------------------------------------------
-- ACTIVITY PROCESSING LOGS - Track ActivityPub activity processing
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.activity_processing_logs (
    id serial PRIMARY KEY,
    activity_id uuid NOT NULL,
    ap_id text NOT NULL,
    ap_type text NOT NULL,
    status text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    processed_at timestamp with time zone
);

CREATE INDEX IF NOT EXISTS idx_activity_processing_logs_activity ON public.activity_processing_logs(activity_id);
CREATE INDEX IF NOT EXISTS idx_activity_processing_logs_status ON public.activity_processing_logs(status);

GRANT SELECT ON public.activity_processing_logs TO authenticated;
GRANT ALL ON public.activity_processing_logs TO service_role;

COMMENT ON TABLE public.activity_processing_logs IS 'Tracks processing of ActivityPub activities';

-- ---------------------------------------------------------------------------
-- ACTIVITYPUB PROCESSING STATS - Daily statistics
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.activitypub_processing_stats (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    date date NOT NULL UNIQUE,
    total_activities integer DEFAULT 0,
    processed_activities integer DEFAULT 0,
    failed_activities integer DEFAULT 0,
    permanently_failed_activities integer DEFAULT 0,
    avg_processing_time_ms numeric DEFAULT 0,
    created_at timestamp with time zone DEFAULT now()
);

GRANT SELECT ON public.activitypub_processing_stats TO authenticated;
GRANT ALL ON public.activitypub_processing_stats TO service_role;

COMMENT ON TABLE public.activitypub_processing_stats IS 'Daily ActivityPub processing statistics';

-- ---------------------------------------------------------------------------
-- FEDERATION DELIVERY STATS - Delivery statistics per period
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.federation_delivery_stats (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    period_start timestamp with time zone NOT NULL,
    period_end timestamp with time zone NOT NULL,
    total_deliveries integer DEFAULT 0,
    successful_deliveries integer DEFAULT 0,
    failed_deliveries integer DEFAULT 0,
    avg_delivery_time_ms numeric,
    created_at timestamp with time zone DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_federation_delivery_stats_period ON public.federation_delivery_stats(period_start, period_end);

GRANT SELECT ON public.federation_delivery_stats TO authenticated;
GRANT ALL ON public.federation_delivery_stats TO service_role;

COMMENT ON TABLE public.federation_delivery_stats IS 'Statistics on federation delivery success rates';

DO $$
BEGIN
    RAISE NOTICE 'Federation tables created successfully';
END $$;


-- ==== 06_tables_misc.sql ====
-- =============================================================================
-- Harmony Database Schema - Miscellaneous Tables
-- =============================================================================
-- Bots, notifications, emojis, encryption, reports, etc.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- EMOJIS - defined in 04_tables_servers.sql (reactions FK depends on it)
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- EMOJI USAGE - Track emoji usage for analytics and suggestions
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.emoji_usage (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    emoji_id uuid NOT NULL REFERENCES public.emojis(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    server_id uuid NOT NULL REFERENCES public.servers(id) ON DELETE CASCADE,
    context_type text NOT NULL,
    context_id uuid,
    used_at timestamp with time zone DEFAULT now(),
    
    CONSTRAINT emoji_usage_context_type_check CHECK (context_type IN ('message', 'reaction')),
    CONSTRAINT emoji_usage_unique_per_context UNIQUE (emoji_id, user_id, context_type, context_id)
);

CREATE INDEX IF NOT EXISTS idx_emoji_usage_emoji ON public.emoji_usage(emoji_id);
CREATE INDEX IF NOT EXISTS idx_emoji_usage_user ON public.emoji_usage(user_id);
CREATE INDEX IF NOT EXISTS idx_emoji_usage_server ON public.emoji_usage(server_id);

COMMENT ON TABLE public.emoji_usage IS 'Tracks emoji usage for analytics and frequently used suggestions';

-- ---------------------------------------------------------------------------
-- REMOTE EMOJIS CACHE - For emoji importer feature
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.remote_emojis_cache (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    
    -- Emoji info
    shortcode text NOT NULL,
    origin_domain text NOT NULL,
    full_code text NOT NULL,
    url text NOT NULL,
    static_url text,
    
    -- Tracking
    first_seen_at timestamp with time zone DEFAULT now(),
    last_seen_at timestamp with time zone DEFAULT now(),
    usage_count integer DEFAULT 1,
    
    -- Import tracking
    imported_as uuid REFERENCES public.emojis(id) ON DELETE SET NULL,
    imported_at timestamp with time zone,
    
    -- Metadata
    category text,
    is_animated boolean DEFAULT false,
    
    created_at timestamp with time zone DEFAULT now(),
    
    UNIQUE(shortcode, origin_domain)
);

CREATE INDEX IF NOT EXISTS idx_remote_emojis_cache_domain ON public.remote_emojis_cache(origin_domain);
CREATE INDEX IF NOT EXISTS idx_remote_emojis_cache_usage ON public.remote_emojis_cache(usage_count DESC);
CREATE INDEX IF NOT EXISTS idx_remote_emojis_imported ON public.remote_emojis_cache USING btree (imported_as) WHERE (imported_as IS NULL);

COMMENT ON TABLE public.remote_emojis_cache IS 'Cache of custom emojis encountered from remote instances. Used for the emoji importer feature.';

-- ---------------------------------------------------------------------------
-- NOTIFICATIONS
-- Matches production schema: flat table with JSONB data column.
-- All context (sender, post, server, channel, etc.) is stored in `data`.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    type character varying(50) NOT NULL,
    data jsonb DEFAULT '{}'::jsonb,
    is_read boolean DEFAULT false,
    is_clicked boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    expires_at timestamp with time zone DEFAULT (now() + '30 days'::interval),
    read_at timestamp with time zone
);

ALTER TABLE public.notifications REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_notifications_user ON public.notifications(user_id);
CREATE INDEX IF NOT EXISTS idx_notifications_unread ON public.notifications(user_id, is_read) WHERE is_read = false;
CREATE INDEX IF NOT EXISTS idx_notifications_created ON public.notifications(created_at DESC);

COMMENT ON TABLE public.notifications IS 'User notifications';
COMMENT ON COLUMN public.notifications.is_read IS 'Boolean field indicating if notification has been read';
COMMENT ON COLUMN public.notifications.read_at IS 'Timestamp when notification was marked as read';

-- ---------------------------------------------------------------------------
-- NOTIFICATION PREFERENCES
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.notification_preferences (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE,

    -- Desktop/sound notifications
    desktop_notifications boolean DEFAULT true,
    desktop_mentions boolean DEFAULT true,
    desktop_replies boolean DEFAULT true,
    desktop_dms boolean DEFAULT true,
    desktop_reactions boolean DEFAULT true,
    desktop_chat_messages boolean DEFAULT true,
    sound_mentions boolean DEFAULT true,
    sound_dms boolean DEFAULT true,
    sound_reactions boolean DEFAULT true,
    sound_replies boolean DEFAULT true,
    sound_chat_messages boolean DEFAULT true,
    sound_voice_activity boolean DEFAULT true,

    -- Do Not Disturb
    dnd_enabled boolean DEFAULT false,
    dnd_start_time time DEFAULT '22:00'::time,
    dnd_end_time time DEFAULT '08:00'::time,

    -- Email notifications
    email_follows boolean DEFAULT true,
    email_mentions boolean DEFAULT true,
    email_replies boolean DEFAULT true,
    email_reblogs boolean DEFAULT true,
    email_favorites boolean DEFAULT true,

    -- Push notifications
    push_follows boolean DEFAULT true,
    push_mentions boolean DEFAULT true,
    push_replies boolean DEFAULT true,
    push_reblogs boolean DEFAULT true,
    push_favorites boolean DEFAULT true,
    push_dms boolean DEFAULT true,

    -- ActivityPub notifications
    activitypub_notifications boolean DEFAULT true,
    activitypub_desktop_notifications boolean DEFAULT true,
    activitypub_follows boolean DEFAULT true,
    activitypub_follow_requests boolean DEFAULT true,
    activitypub_favorites boolean DEFAULT true,
    activitypub_reblogs boolean DEFAULT true,
    activitypub_mentions boolean DEFAULT true,
    activitypub_replies boolean DEFAULT true,
    activitypub_desktop_follows boolean DEFAULT true,
    activitypub_desktop_favorites boolean DEFAULT true,
    activitypub_desktop_reblogs boolean DEFAULT true,
    activitypub_desktop_mentions boolean DEFAULT true,
    activitypub_desktop_replies boolean DEFAULT true,

    -- ActivityPub sound notifications
    activitypub_sound_notifications boolean DEFAULT true,
    activitypub_sound_follows boolean DEFAULT true,
    activitypub_sound_favorites boolean DEFAULT true,
    activitypub_sound_reblogs boolean DEFAULT true,
    activitypub_sound_mentions boolean DEFAULT true,
    activitypub_sound_replies boolean DEFAULT true,

    -- Sound master toggle
    sound_notifications boolean DEFAULT true,

    -- Push/email master toggles
    push_notifications boolean DEFAULT true,
    push_offline_only boolean DEFAULT true,
    email_notifications boolean DEFAULT false,
    email_digest boolean DEFAULT false,
    email_digest_frequency character varying(20) DEFAULT 'weekly',

    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);

ALTER TABLE public.notification_preferences REPLICA IDENTITY FULL;

COMMENT ON TABLE public.notification_preferences IS 'User notification preferences';

-- ---------------------------------------------------------------------------
-- NOTIFICATION CHANNELS - Per-channel/server muting
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.notification_channels (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    server_id uuid REFERENCES public.servers(id) ON DELETE CASCADE,
    channel_id uuid REFERENCES public.channels(id) ON DELETE CASCADE,
    conversation_id uuid,
    
    muted boolean DEFAULT false,
    muted_until timestamp with time zone,
    -- 'mentions' by default: new channels notify only on @mentions until the
    -- user explicitly chooses 'all' or 'none' in the channel kebab menu.
    -- See db_schema/migrations/20260520_default_notification_level_mentions.sql.
    notification_level varchar(20) DEFAULT 'mentions'::varchar,
    
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_notification_channels_user ON public.notification_channels(user_id);
CREATE INDEX IF NOT EXISTS idx_notification_channels_server ON public.notification_channels(server_id);

CREATE UNIQUE INDEX IF NOT EXISTS idx_notification_channels_user_channel
  ON public.notification_channels (user_id, channel_id)
  WHERE channel_id IS NOT NULL AND conversation_id IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS idx_notification_channels_user_conversation
  ON public.notification_channels (user_id, conversation_id)
  WHERE conversation_id IS NOT NULL AND channel_id IS NULL;

GRANT SELECT, INSERT, UPDATE, DELETE ON public.notification_channels TO authenticated;

COMMENT ON TABLE public.notification_channels IS 'Channel/server/conversation specific notification muting settings';

-- ---------------------------------------------------------------------------
-- PUSH SUBSCRIPTIONS (Web Push)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.push_subscriptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    endpoint text NOT NULL,
    p256dh text NOT NULL,
    auth text NOT NULL,
    
    -- Device info
    user_agent text,
    device_name text,
    
    -- Timestamps
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    
    -- Push delivery tracking
    last_successful_push timestamp with time zone,
    failure_count integer DEFAULT 0,
    last_failure_at timestamp with time zone,
    last_failure_reason text,

    -- Upserted ON CONFLICT (user_id, endpoint); absent, Postgres raises 42P10.
    CONSTRAINT push_subscriptions_user_endpoint_unique UNIQUE (user_id, endpoint)
);

CREATE INDEX IF NOT EXISTS idx_push_subscriptions_user ON public.push_subscriptions(user_id);
CREATE INDEX IF NOT EXISTS idx_push_subscriptions_endpoint ON public.push_subscriptions(endpoint);

COMMENT ON TABLE public.push_subscriptions IS 'Stores Web Push notification subscriptions for each user device. Used for native push notifications on iOS (16.4+) and Android PWAs.';
COMMENT ON COLUMN public.push_subscriptions.endpoint IS 'The unique push service URL for this subscription';

-- ---------------------------------------------------------------------------
-- UNREAD COUNTS (denormalized for performance)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.unread_counts (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    server_id uuid REFERENCES public.servers(id) ON DELETE CASCADE,
    channel_id uuid REFERENCES public.channels(id) ON DELETE CASCADE,
    conversation_id uuid REFERENCES public.conversations(id) ON DELETE CASCADE,
    
    unread_messages integer DEFAULT 0,
    unread_mentions integer DEFAULT 0,
    last_read_message_id uuid,
    last_read_at timestamp with time zone DEFAULT now(),
    
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);

ALTER TABLE public.unread_counts REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_unread_counts_user ON public.unread_counts(user_id);
CREATE INDEX IF NOT EXISTS idx_unread_counts_channel ON public.unread_counts(channel_id);
CREATE INDEX IF NOT EXISTS idx_unread_counts_conversation ON public.unread_counts(conversation_id);

COMMENT ON TABLE public.unread_counts IS 'Per-channel/conversation unread message tracking';

-- ---------------------------------------------------------------------------
-- REPORTS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.reports (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    reporter_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    reported_user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,
    reported_post_id uuid REFERENCES public.posts(id) ON DELETE SET NULL,
    reported_message_id uuid REFERENCES public.messages(id) ON DELETE SET NULL,
    reported_server_id uuid REFERENCES public.servers(id) ON DELETE SET NULL,
    
    reason text NOT NULL,
    comment text,
    report_type text NOT NULL DEFAULT 'user',
    
    -- Status
    status text DEFAULT 'pending'::text,
    resolved_at timestamp with time zone,
    resolved_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    resolution_note text,
    
    -- Source / Federation
    source text DEFAULT 'local'::text,
    source_instance text,
    ap_id text,
    metadata jsonb DEFAULT '{}'::jsonb,
    federation_status text DEFAULT 'pending'::text,
    
    CONSTRAINT reports_status_check CHECK (status IN ('pending', 'investigating', 'resolved', 'dismissed')),
    CONSTRAINT reports_report_type_check CHECK (report_type IN ('user', 'post', 'message', 'server')),
    CONSTRAINT reports_source_check CHECK (source IN ('local', 'federation')),
    CONSTRAINT reports_federation_status_check CHECK (federation_status IN ('pending', 'queued', 'processing', 'completed', 'failed', 'skipped')),
    CONSTRAINT reports_reason_length_check CHECK (char_length(reason) <= 200),
    CONSTRAINT reports_comment_length_check CHECK (comment IS NULL OR char_length(comment) <= 1000)
);

ALTER TABLE public.reports REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_reports_status ON public.reports(status);
CREATE INDEX IF NOT EXISTS idx_reports_reported_user ON public.reports(reported_user_id);
CREATE INDEX IF NOT EXISTS idx_reports_report_type ON public.reports(report_type);
CREATE INDEX IF NOT EXISTS idx_reports_reported_message ON public.reports(reported_message_id);

COMMENT ON TABLE public.reports IS 'User and content reports';

-- ---------------------------------------------------------------------------
-- BOTS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.bots (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    username text NOT NULL,
    discriminator text DEFAULT '0000'::text,
    display_name text,
    avatar_url text DEFAULT '/default_avatar.webp'::text,
    banner_url text,
    bio text,
    
    owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    is_verified boolean DEFAULT false,
    is_public boolean DEFAULT true,
    is_active boolean DEFAULT true,
    
    bot_type text DEFAULT 'bot'::text,
    website_url text,
    support_server_id uuid,
    
    -- Tags for discovery
    tags text[] DEFAULT '{}'::text[],
    
    -- Stats
    server_count integer DEFAULT 0,
    user_count integer DEFAULT 0,
    command_count bigint DEFAULT 0,
    
    last_online_at timestamp with time zone,
    settings jsonb DEFAULT '{}'::jsonb,
    
    CONSTRAINT bots_bot_type_check CHECK (bot_type IN ('bot', 'bridge', 'integration')),
    CONSTRAINT valid_username CHECK (username ~* '^[a-z0-9_-]+$' AND char_length(username) >= 3 AND char_length(username) <= 32),
    CONSTRAINT bots_display_name_length_check CHECK (display_name IS NULL OR char_length(display_name) <= 100),
    CONSTRAINT bots_bio_length_check CHECK (bio IS NULL OR char_length(bio) <= 500),
    CONSTRAINT bots_website_url_length_check CHECK (website_url IS NULL OR char_length(website_url) <= 512)
);

CREATE INDEX IF NOT EXISTS idx_bots_owner ON public.bots(owner_id);
CREATE INDEX IF NOT EXISTS idx_bots_public ON public.bots(is_public) WHERE is_public = true;

COMMENT ON TABLE public.bots IS 'Bot definitions';

-- Owners interactively manage their own bots (RLS narrows to owner-only).
GRANT SELECT, INSERT, UPDATE, DELETE ON public.bots TO authenticated;

-- ---------------------------------------------------------------------------
-- BOT TOKENS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.bot_tokens (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    bot_id uuid NOT NULL REFERENCES public.bots(id) ON DELETE CASCADE,
    
    token_hash text NOT NULL,
    token_prefix text NOT NULL,
    
    name text,
    scopes text[] DEFAULT '{}'::text[],
    
    -- revoked_at records when, is_active decides whether. verify_bot_token filters on
    -- is_active.
    is_active boolean DEFAULT true,
    uses_count bigint DEFAULT 0,

    created_at timestamp with time zone DEFAULT now(),
    last_used_at timestamp with time zone,
    expires_at timestamp with time zone,
    revoked_at timestamp with time zone,

    metadata jsonb DEFAULT '{}'::jsonb
);

CREATE INDEX IF NOT EXISTS idx_bot_tokens_bot ON public.bot_tokens(bot_id);
CREATE INDEX IF NOT EXISTS idx_bot_tokens_prefix ON public.bot_tokens(token_prefix);

COMMENT ON TABLE public.bot_tokens IS 'Bot API tokens';

GRANT SELECT, INSERT, UPDATE, DELETE ON public.bot_tokens TO authenticated;

-- ---------------------------------------------------------------------------
-- BOT SERVER PERMISSIONS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.bot_server_permissions (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    bot_id uuid NOT NULL REFERENCES public.bots(id) ON DELETE CASCADE,
    server_id uuid NOT NULL REFERENCES public.servers(id) ON DELETE CASCADE,
    
    installed_by uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    installed_at timestamp with time zone DEFAULT now(),
    
    is_active boolean DEFAULT true,
    
    -- Permissions
    read_messages boolean DEFAULT true,
    send_messages boolean DEFAULT true,
    manage_messages boolean DEFAULT false,
    embed_links boolean DEFAULT true,
    attach_files boolean DEFAULT true,
    mention_everyone boolean DEFAULT false,
    add_reactions boolean DEFAULT true,
    manage_channels boolean DEFAULT false,
    kick_members boolean DEFAULT false,
    ban_members boolean DEFAULT false,
    
    UNIQUE(bot_id, server_id)
);

CREATE INDEX IF NOT EXISTS idx_bot_server_permissions_bot ON public.bot_server_permissions(bot_id);
CREATE INDEX IF NOT EXISTS idx_bot_server_permissions_server ON public.bot_server_permissions(server_id);

COMMENT ON TABLE public.bot_server_permissions IS 'Bot permissions per server';

-- ---------------------------------------------------------------------------
-- FILES (Attachments)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.files (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    
    owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    filename text NOT NULL,
    content_type text NOT NULL,
    size_bytes bigint NOT NULL,
    
    storage_path text NOT NULL,
    public_url text,
    
    -- For images
    width integer,
    height integer,
    blurhash text,
    
    -- Metadata
    metadata jsonb DEFAULT '{}'::jsonb
);

CREATE INDEX IF NOT EXISTS idx_files_owner ON public.files(owner_id);

COMMENT ON TABLE public.files IS 'Uploaded file metadata';

-- ---------------------------------------------------------------------------
-- GIF FAVORITES
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.gif_favorites (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    gif_url text NOT NULL,
    preview_url text,
    title text,
    -- 'gif' | 'sticker' | 'clip' | 'meme' — keeps the favorite lists separate.
    media_type text NOT NULL DEFAULT 'gif',
    created_at timestamp with time zone DEFAULT now(),
    
    UNIQUE(user_id, gif_url)
);

CREATE INDEX IF NOT EXISTS idx_gif_favorites_user ON public.gif_favorites(user_id);

COMMENT ON TABLE public.gif_favorites IS 'User favorite GIFs and stickers';

-- ---------------------------------------------------------------------------
-- EMOJI FAVORITES
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.emoji_favorites (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    emoji_id text NOT NULL,
    emoji_name text NOT NULL,
    emoji_url text,
    emoji_server_id uuid,
    created_at timestamp with time zone DEFAULT now(),

    UNIQUE(user_id, emoji_id)
);

CREATE INDEX IF NOT EXISTS idx_emoji_favorites_user ON public.emoji_favorites(user_id);

GRANT SELECT, INSERT, DELETE ON public.emoji_favorites TO authenticated;

COMMENT ON TABLE public.emoji_favorites IS 'User favorite emojis (unicode and custom)';

-- ---------------------------------------------------------------------------
-- ADMIN AUDIT LOG
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.admin_audit_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,

    admin_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    action_type text NOT NULL,
    target_type text,
    target_id text,

    action_details jsonb DEFAULT '{}'::jsonb,
    ip_address inet,
    user_agent text
);

CREATE INDEX IF NOT EXISTS idx_admin_audit_log_admin ON public.admin_audit_log(admin_id);
CREATE INDEX IF NOT EXISTS idx_admin_audit_log_created ON public.admin_audit_log(created_at DESC);

COMMENT ON TABLE public.admin_audit_log IS 'Admin action audit log';

-- ---------------------------------------------------------------------------
-- ENCRYPTION - User Key Pairs (Megolm-style E2E encryption)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.user_key_pairs (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    device_id text DEFAULT 'default'::text,
    
    -- ECDH P-256 identity keys (session key exchange)
    identity_public_key text NOT NULL,
    identity_private_key_encrypted text NOT NULL,

    -- ECDSA P-256 signing keys (per-message sender binding, Megolm v2).
    -- Nullable for legacy rows; client mints them lazily on next unlock.
    -- See db_schema/migrations/20260520_user_key_pairs_signing_keys.sql for rationale.
    identity_signing_public_key text,
    identity_signing_private_key_encrypted text,
    
    -- Versioning & status
    key_version integer DEFAULT 1 NOT NULL,
    is_active boolean DEFAULT true,
    
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_used_at timestamp with time zone DEFAULT now(),
    expires_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb,
    
    CONSTRAINT valid_device_id CHECK (char_length(device_id) <= 255)
);

CREATE INDEX IF NOT EXISTS idx_user_key_pairs_user ON public.user_key_pairs(user_id);
CREATE INDEX IF NOT EXISTS idx_user_key_pairs_active ON public.user_key_pairs(user_id, is_active) WHERE is_active = true;

COMMENT ON TABLE public.user_key_pairs IS 'Per-user encryption identity keys. ECDH P-256 for session exchange, ECDSA P-256 for per-message sender signatures (Megolm v2 binding). Supports future per-device migration.';

-- ---------------------------------------------------------------------------
-- PREKEYS (One-time prekeys for Signal protocol)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.prekeys (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    device_id text NOT NULL,
    prekey_id integer NOT NULL,
    public_key text NOT NULL,
    
    is_signed boolean DEFAULT false,
    signature text,
    is_one_time boolean DEFAULT true,

    created_at timestamp with time zone DEFAULT now(),
    is_used boolean DEFAULT false,
    used_at timestamp with time zone,
    -- Holds auth.uid(), so the reference is auth.users and not profiles.
    -- Production declares this FK with NO ACTION; SET NULL here, otherwise a
    -- consumed prekey belonging to another user blocks DELETE FROM auth.users
    -- in delete_my_account.
    used_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
    expires_at timestamp with time zone,

    UNIQUE(user_id, device_id, prekey_id)
);

CREATE INDEX IF NOT EXISTS idx_prekeys_user_device ON public.prekeys(user_id, device_id);
CREATE INDEX IF NOT EXISTS idx_prekeys_available ON public.prekeys(user_id, device_id) WHERE used_at IS NULL;

COMMENT ON TABLE public.prekeys IS 'One-time prekeys for E2E encryption key exchange';

-- ---------------------------------------------------------------------------
-- INSTANCE WEBRTC SETTINGS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.instance_webrtc_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    
    webrtc_mode text DEFAULT 'hybrid'::text,
    
    -- LiveKit configuration
    livekit_url text,                -- WebSocket URL (wss://...)
    livekit_public_url text,         -- Public URL if different
    livekit_api_key text,            -- API Key (APIxxxx)
    livekit_api_secret text,         -- API Secret (SENSITIVE - never expose!)
    
    -- TURN servers (for P2P fallback)
    turn_servers jsonb DEFAULT '[]'::jsonb,
    
    -- Federation
    allow_federated_voice boolean DEFAULT true,
    
    -- Stage/voice limits
    max_stage_listeners integer DEFAULT 100000 NOT NULL,
    
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    
    CONSTRAINT instance_webrtc_settings_mode_check CHECK (webrtc_mode IN ('sfu', 'p2p', 'hybrid'))
);

-- Ensure only one row
CREATE UNIQUE INDEX IF NOT EXISTS idx_instance_webrtc_settings_singleton ON public.instance_webrtc_settings((TRUE));

COMMENT ON TABLE public.instance_webrtc_settings IS 'Instance WebRTC configuration';

-- Insert default settings
INSERT INTO public.instance_webrtc_settings (webrtc_mode, allow_federated_voice)
VALUES ('hybrid', true)
ON CONFLICT DO NOTHING;

-- ---------------------------------------------------------------------------
-- PERFORMANCE METRICS (optional)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.performance_metrics (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    timestamp timestamp with time zone DEFAULT now() NOT NULL,
    
    metric_type text NOT NULL,
    metric_name text NOT NULL,
    value double precision NOT NULL,
    -- Unit of `value` (e.g. 'ms', 'count', 'bytes'). Written by the federation
    -- worker and the record_performance_metric() RPC.
    unit text,
    
    labels jsonb DEFAULT '{}'::jsonb,
    source text
);

CREATE INDEX IF NOT EXISTS idx_performance_metrics_timestamp ON public.performance_metrics(timestamp DESC);
CREATE INDEX IF NOT EXISTS idx_performance_metrics_type ON public.performance_metrics(metric_type, metric_name);

-- Partitioning hint: Consider partitioning by timestamp for large deployments
COMMENT ON TABLE public.performance_metrics IS 'Optional performance metrics storage';

-- ---------------------------------------------------------------------------
-- NOTIFICATION RATE LIMITS - For spam prevention
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.notification_rate_limits (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    notification_type text NOT NULL,
    source_user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,
    notification_count integer DEFAULT 1,
    last_notification_at timestamp with time zone DEFAULT now(),
    suppressed_until timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),

    UNIQUE(user_id, notification_type, source_user_id)
);
COMMENT ON TABLE public.notification_rate_limits IS 'Rate limiting for notifications to prevent spam';

CREATE INDEX IF NOT EXISTS idx_notification_rate_limits_user ON public.notification_rate_limits(user_id);

-- ---------------------------------------------------------------------------
-- USER VIEW CONTEXTS - Track where users are viewing
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.user_view_contexts (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE,
    view_type text NOT NULL,
    server_id uuid REFERENCES public.servers(id) ON DELETE SET NULL,
    channel_id uuid REFERENCES public.channels(id) ON DELETE SET NULL,
    conversation_id uuid REFERENCES public.conversations(id) ON DELETE SET NULL,
    last_active_at timestamp with time zone DEFAULT now(),
    created_at timestamp with time zone DEFAULT now()
);
COMMENT ON TABLE public.user_view_contexts IS 'Track where users are currently viewing (for presence)';

CREATE INDEX IF NOT EXISTS idx_user_view_contexts_user ON public.user_view_contexts(user_id);
CREATE INDEX IF NOT EXISTS idx_user_view_contexts_channel ON public.user_view_contexts(channel_id) WHERE channel_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- MESSAGE SEARCH INDEX - Full-text search for messages
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.message_search_index (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    message_id uuid NOT NULL UNIQUE REFERENCES public.messages(id) ON DELETE CASCADE,
    content_text text,
    content_tsvector tsvector,
    channel_id uuid REFERENCES public.channels(id) ON DELETE CASCADE,
    conversation_id uuid REFERENCES public.conversations(id) ON DELETE CASCADE,
    user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,
    server_id uuid REFERENCES public.servers(id) ON DELETE CASCADE,
    has_media boolean DEFAULT false,
    has_url boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);
COMMENT ON TABLE public.message_search_index IS 'Full-text search index for messages';

CREATE INDEX IF NOT EXISTS idx_message_search_tsvector ON public.message_search_index USING gin(content_tsvector);
CREATE INDEX IF NOT EXISTS idx_message_search_channel ON public.message_search_index(channel_id);
CREATE INDEX IF NOT EXISTS idx_message_search_conversation ON public.message_search_index(conversation_id);
CREATE INDEX IF NOT EXISTS idx_message_search_user ON public.message_search_index(user_id);

-- ---------------------------------------------------------------------------
-- INSTANCE FUNDING
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.instance_funding (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    enabled boolean DEFAULT false,
    goal_amount numeric(10,2),
    goal_currency text DEFAULT 'USD',
    current_amount numeric(10,2) DEFAULT 0,
    funding_period text DEFAULT 'monthly',
    goal_description text,
    funding_links jsonb DEFAULT '[]'::jsonb,
    show_progress_bar boolean DEFAULT true,
    show_in_context_bar boolean DEFAULT false,
    context_bar_style text DEFAULT 'mini-progress',
    thank_you_message text,
    -- Ko-fi webhook integration (Gold-tier feature). Verification token comes
    -- from Ko-fi Settings → API → Webhook URL. When set, the federation
    -- backend accepts POSTs at /webhooks/kofi for automated donation tracking.
    kofi_webhook_token text,
    kofi_auto_assign_tier boolean DEFAULT true,
    updated_at timestamptz DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- INSTANCE SUPPORTER TIERS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.instance_supporter_tiers (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    name text NOT NULL,
    min_amount numeric(10,2) NOT NULL,
    badge_icon text,
    badge_color text,
    perks text,
    display_order integer DEFAULT 0,
    -- When true, active supporters on this tier get the ad-free Klipy GIF key.
    removes_ads boolean NOT NULL DEFAULT false,
    created_at timestamptz DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- INSTANCE SUPPORTERS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.instance_supporters (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    tier_id uuid REFERENCES public.instance_supporter_tiers(id) ON DELETE SET NULL,
    amount numeric(10,2),
    started_at timestamptz DEFAULT now(),
    expires_at timestamptz,
    is_active boolean DEFAULT true,
    external_id text,
    platform text,
    CONSTRAINT unique_supporter_user UNIQUE (user_id)
);

CREATE INDEX IF NOT EXISTS idx_supporters_user ON public.instance_supporters(user_id);
CREATE INDEX IF NOT EXISTS idx_supporters_active ON public.instance_supporters(is_active);

-- ---------------------------------------------------------------------------
-- INSTANCE DONATION HISTORY
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.instance_donation_history (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    supporter_id uuid NOT NULL REFERENCES public.instance_supporters(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    amount numeric(10,2) NOT NULL,
    currency text DEFAULT 'USD',
    platform text,
    external_reference text,
    note text,
    donated_at timestamptz DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_donation_history_user ON public.instance_donation_history(user_id);
CREATE INDEX IF NOT EXISTS idx_donation_history_supporter ON public.instance_donation_history(supporter_id);
CREATE INDEX IF NOT EXISTS idx_donation_history_date ON public.instance_donation_history(donated_at);
-- Dedup webhook retries: NULL external_reference (manual entries) always
-- allowed; non-null values must be unique per platform.
CREATE UNIQUE INDEX IF NOT EXISTS idx_donation_history_external_unique
    ON public.instance_donation_history (platform, external_reference)
    WHERE external_reference IS NOT NULL;

-- ---------------------------------------------------------------------------
-- INSTANCE PENDING DONATIONS
-- ---------------------------------------------------------------------------
-- Donations received via webhook that could not be auto-matched to a profile.
-- Admins review these manually and either link to an existing user (which
-- promotes them to instance_donation_history) or dismiss.
CREATE TABLE IF NOT EXISTS public.instance_pending_donations (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    received_at timestamptz DEFAULT now(),
    platform text NOT NULL,
    external_reference text,
    amount numeric(10, 2) NOT NULL,
    currency text DEFAULT 'USD',
    donor_name text,
    donor_email text,
    donor_message text,
    raw_payload jsonb NOT NULL,
    resolved_at timestamptz,
    resolved_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    resolved_user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    CONSTRAINT instance_pending_donations_external_unique
        UNIQUE (platform, external_reference)
);

CREATE INDEX IF NOT EXISTS idx_pending_donations_unresolved
    ON public.instance_pending_donations (received_at DESC)
    WHERE resolved_at IS NULL;

-- ---------------------------------------------------------------------------
-- FUNDING TABLE GRANTS
-- ---------------------------------------------------------------------------
-- authenticated: admin UI + per-user supporter/donation queries (RLS gates access)
GRANT SELECT, INSERT, UPDATE, DELETE ON public.instance_funding TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.instance_supporter_tiers TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.instance_supporters TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.instance_donation_history TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.instance_pending_donations TO authenticated;

-- service_role: federation backend webhook ingestion. Bypasses RLS but still
-- needs explicit table grants.
GRANT SELECT ON public.instance_funding TO service_role;
GRANT SELECT ON public.instance_supporter_tiers TO service_role;
GRANT SELECT, INSERT, UPDATE ON public.instance_supporters TO service_role;
GRANT SELECT, INSERT ON public.instance_donation_history TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.instance_pending_donations TO service_role;
-- profiles read access for handle matching (no writes - webhook never mutates profiles)
GRANT SELECT ON public.profiles TO service_role;

-- ---------------------------------------------------------------------------
-- INSTANCE ANNOUNCEMENTS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.instance_announcements (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    created_at timestamptz DEFAULT now(),
    updated_at timestamptz DEFAULT now(),
    title text NOT NULL,
    content text NOT NULL,
    image_url text,
    icon text DEFAULT 'info',
    is_active boolean DEFAULT true,
    starts_at timestamptz DEFAULT now(),
    ends_at timestamptz,
    is_pinned boolean DEFAULT false,
    show_popup boolean DEFAULT true,
    silence boolean DEFAULT false,
    author_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    display_order integer DEFAULT 0
);

CREATE INDEX IF NOT EXISTS idx_announcements_active
    ON public.instance_announcements(is_active, starts_at, ends_at);

-- ---------------------------------------------------------------------------
-- ANNOUNCEMENT READS
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.announcement_reads (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    announcement_id uuid NOT NULL REFERENCES public.instance_announcements(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    read_at timestamptz DEFAULT now(),
    CONSTRAINT unique_announcement_read UNIQUE (announcement_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_announcement_reads_user
    ON public.announcement_reads(user_id);

GRANT SELECT ON public.instance_announcements TO authenticated;
GRANT INSERT, UPDATE, DELETE ON public.instance_announcements TO authenticated;
GRANT SELECT, INSERT, UPDATE ON public.announcement_reads TO authenticated;

-- ---------------------------------------------------------------------------
-- DISCORD BRIDGE PAIRING (self-hosted bridge onboarding)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.discord_bridge_pairings (
    server_id uuid PRIMARY KEY REFERENCES public.servers(id) ON DELETE CASCADE,
    pairing_code text NOT NULL,
    -- Audit field only; the pairing belongs to the server, not the creator. NULL
    -- when the creator's account is deleted so the bridge keeps working.
    created_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT discord_bridge_pairings_code_format CHECK (pairing_code ~ '^HRM-[A-Z0-9]{4}-[A-Z0-9]{4}$')
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_discord_bridge_pairings_code
    ON public.discord_bridge_pairings (pairing_code);

COMMENT ON TABLE public.discord_bridge_pairings IS 'Pairing codes linking Harmony servers to self-hosted Discord bridges';

-- messages.bot_id is declared in 04_tables_servers.sql, before public.bots exists, so the
-- foreign key is attached here. PostgREST resolves embeds by constraint name.
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conrelid = 'public.messages'::regclass
           AND conname = 'messages_bot_id_fkey'
    ) THEN
        ALTER TABLE public.messages
            ADD CONSTRAINT messages_bot_id_fkey
            FOREIGN KEY (bot_id) REFERENCES public.bots(id) ON DELETE CASCADE;
    END IF;
END $$;

DO $$
BEGIN
    RAISE NOTICE 'Miscellaneous tables created successfully';
END $$;


-- ==== 07_tables_trending.sql ====
-- =============================================================================
-- Harmony Database Schema - Trending & Discovery Tables
-- =============================================================================
-- Tables for trending content, hashtag analytics, and content discovery
-- =============================================================================

-- ---------------------------------------------------------------------------
-- TRENDING POSTS - Cached trending post calculations
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.trending_posts (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    
    post_id uuid NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE,
    
    -- Scores
    trending_score numeric DEFAULT 0.0 NOT NULL,
    engagement_score numeric DEFAULT 0.0 NOT NULL,
    velocity_score numeric DEFAULT 0.0 NOT NULL,
    
    -- Period tracking
    period_type text DEFAULT 'daily'::text NOT NULL,
    period_start timestamp with time zone NOT NULL,
    period_end timestamp with time zone NOT NULL,
    
    -- Engagement metrics
    likes_count integer DEFAULT 0,
    reblogs_count integer DEFAULT 0,
    replies_count integer DEFAULT 0,
    total_engagement integer GENERATED ALWAYS AS ((likes_count + reblogs_count + replies_count)) STORED,
    
    -- Ranking
    trending_rank integer,
    
    CONSTRAINT trending_posts_period_type_check CHECK (period_type IN ('hourly', 'daily', 'weekly'))
);

ALTER TABLE public.trending_posts REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_trending_posts_period ON public.trending_posts(period_type, period_start);
CREATE INDEX IF NOT EXISTS idx_trending_posts_score ON public.trending_posts(trending_score DESC);
CREATE INDEX IF NOT EXISTS idx_trending_posts_post_id ON public.trending_posts(post_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_trending_posts_unique ON public.trending_posts(post_id, period_type, period_start);

COMMENT ON TABLE public.trending_posts IS 'Cached trending posts data for performance';

-- ---------------------------------------------------------------------------
-- TRENDING USERS - Cached trending user calculations
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.trending_users (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    -- Scores
    trending_score numeric DEFAULT 0.0 NOT NULL,
    followers_growth numeric DEFAULT 0.0,
    engagement_rate numeric DEFAULT 0.0,
    
    -- Period tracking
    period_type text DEFAULT 'daily'::text NOT NULL,
    period_start timestamp with time zone NOT NULL,
    period_end timestamp with time zone NOT NULL,
    
    -- Metrics
    new_followers integer DEFAULT 0,
    posts_count integer DEFAULT 0,
    total_engagement integer DEFAULT 0,
    
    -- Ranking
    trending_rank integer,
    
    CONSTRAINT trending_users_period_type_check CHECK (period_type IN ('hourly', 'daily', 'weekly'))
);

ALTER TABLE public.trending_users REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_trending_users_period ON public.trending_users(period_type, period_start);
CREATE INDEX IF NOT EXISTS idx_trending_users_score ON public.trending_users(trending_score DESC);
CREATE INDEX IF NOT EXISTS idx_trending_users_user_id ON public.trending_users(user_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_trending_users_unique ON public.trending_users(user_id, period_type, period_start);

COMMENT ON TABLE public.trending_users IS 'Cached trending users data for performance';

-- ---------------------------------------------------------------------------
-- TRENDING REFRESH QUEUE - Background refresh tracking
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.trending_refresh_queue (
    refresh_type text NOT NULL PRIMARY KEY,
    priority text DEFAULT 'normal'::text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    last_processed_at timestamp with time zone,
    processing_started_at timestamp with time zone,
    is_processing boolean DEFAULT false,
    
    CONSTRAINT trending_refresh_queue_priority_check CHECK (priority IN ('low', 'normal', 'high'))
);

COMMENT ON TABLE public.trending_refresh_queue IS 'Queue for background trending data refresh';

-- ---------------------------------------------------------------------------
-- SERVER FOLDERS - Organize servers into folders (like Discord)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.server_folders (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    name text NOT NULL,
    color text DEFAULT '#5865f2'::text,
    "position" integer DEFAULT 0 NOT NULL,
    is_expanded boolean DEFAULT true,

    CONSTRAINT server_folders_name_length_check CHECK (char_length(name) <= 64)
);

ALTER TABLE public.server_folders REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_server_folders_user ON public.server_folders(user_id);
CREATE INDEX IF NOT EXISTS idx_server_folders_user_position ON public.server_folders(user_id, "position");

COMMENT ON TABLE public.server_folders IS 'User-created folders for organizing servers in the sidebar';
COMMENT ON COLUMN public.server_folders.color IS 'Hex color code for folder display';
COMMENT ON COLUMN public.server_folders."position" IS 'Sort order position for the folder in the sidebar';

-- ---------------------------------------------------------------------------
-- SERVER SETTINGS - Extended server configuration
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.server_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    server_id uuid NOT NULL UNIQUE REFERENCES public.servers(id) ON DELETE CASCADE,

    -- Default role (set by trigger on server creation)
    default_role_id uuid REFERENCES public.server_roles(id) ON DELETE SET NULL,

    -- Invite permissions
    invite_permissions jsonb DEFAULT '{"who_can_create": "everyone", "default_expiration": 1440, "max_expiration": 0, "allow_temporary": true, "max_uses_limit": 0}'::jsonb,

    -- Moderation settings (single source of truth - client reads/writes this JSONB,
    -- not any standalone column). See `src/services/permissionsService.ts`.
    moderation_settings jsonb DEFAULT '{"auto_mod_enabled": false, "spam_filter": false, "link_filter": false}'::jsonb,

    -- Default notification level for channels in this server. 'mentions' so new
    -- servers don't flood members with notifications for every channel message.
    -- Server owners can flip this to 'all' for high-touch servers. Used by
    -- send_notification() in 13_functions_rpc_extended.sql. See migration
    -- 20260520_default_notification_level_mentions.sql for the policy rationale.
    default_message_notifications text DEFAULT 'mentions'::text,

    -- Channel that receives auto-generated system messages (member-join, kick,
    -- ban announcements). Used by handle_member_join_system_message trigger and
    -- handle_kicked_user / handle_banned_user RPCs. NULL → fall back to
    -- get_default_channel(server_id).
    system_channel_id uuid,

    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),

    CONSTRAINT server_settings_notifications_check
        CHECK (default_message_notifications IN ('all', 'mentions', 'none'))
);

CREATE INDEX IF NOT EXISTS idx_server_settings_server ON public.server_settings(server_id);

COMMENT ON TABLE public.server_settings IS 'Extended server configuration: roles, invites, moderation, default notification level, system channel.';

-- NOTE: previous versions of this table also declared `auto_mod_enabled`,
-- `auto_mod_rules`, `explicit_content_filter`, `verification_gate_enabled`,
-- `verification_gate_rules`, `afk_channel_id`, `afk_timeout`, and
-- `rules_channel_id`. None of those were ever read by any code, trigger, or
-- function - they were an aspirational Discord-feature-parity stub. Removed
-- here and dropped from existing databases by
-- db_schema/migrations/20260520_server_settings_drop_unused_columns.sql.

-- ---------------------------------------------------------------------------
-- CHANNEL PERMISSION OVERRIDES - Per-channel role/user permission overrides
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.channel_permission_overrides (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    channel_id uuid NOT NULL REFERENCES public.channels(id) ON DELETE CASCADE,
    
    -- Target can be either a role or a user
    target_type text NOT NULL,
    role_id uuid REFERENCES public.server_roles(id) ON DELETE CASCADE,
    user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    -- Permission bit masks
    allow_permissions bigint DEFAULT 0,
    deny_permissions bigint DEFAULT 0,
    
    CONSTRAINT channel_permission_overrides_type_check CHECK (target_type IN ('role', 'user')),
    CONSTRAINT channel_permission_overrides_target_check CHECK (
        (target_type = 'role' AND role_id IS NOT NULL AND user_id IS NULL) OR
        (target_type = 'user' AND user_id IS NOT NULL AND role_id IS NULL)
    ),
    UNIQUE(channel_id, role_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_channel_permission_overrides_channel ON public.channel_permission_overrides(channel_id);
CREATE INDEX IF NOT EXISTS idx_channel_permission_overrides_role ON public.channel_permission_overrides(role_id);
CREATE INDEX IF NOT EXISTS idx_channel_permission_overrides_user ON public.channel_permission_overrides(user_id);

-- Partial unique indexes needed for PostgREST upserts. The composite UNIQUE
-- above does NOT enforce uniqueness for role-only or user-only rows because
-- Postgres treats NULLs as distinct, so `onConflict=channel_id,role_id,user_id`
-- fails with a 400 when one of role_id/user_id is null. These give us a real
-- index per shape that the upsert can match.
CREATE UNIQUE INDEX IF NOT EXISTS uniq_cpo_channel_role
    ON public.channel_permission_overrides (channel_id, role_id)
    WHERE user_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uniq_cpo_channel_user
    ON public.channel_permission_overrides (channel_id, user_id)
    WHERE role_id IS NULL;

COMMENT ON TABLE public.channel_permission_overrides IS 'Channel-specific permission overrides for roles and users';

-- ---------------------------------------------------------------------------
-- USER MUTES - Muted users (softer than blocks)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.user_mutes (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    muter_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    muted_user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    -- Optional expiration
    expires_at timestamp with time zone,
    
    -- Mute options
    hide_notifications boolean DEFAULT true,
    hide_from_timeline boolean DEFAULT true,
    
    -- Federation
    is_federated boolean DEFAULT false,
    ap_id text,
    federation_status text DEFAULT 'pending'::text,
    
    UNIQUE(muter_id, muted_user_id),
    CONSTRAINT user_mutes_no_self_mute CHECK (muter_id != muted_user_id)
);

ALTER TABLE public.user_mutes REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_user_mutes_muter ON public.user_mutes(muter_id);
CREATE INDEX IF NOT EXISTS idx_user_mutes_muted ON public.user_mutes(muted_user_id);

COMMENT ON TABLE public.user_mutes IS 'User mute relationships (hide without blocking)';

-- ---------------------------------------------------------------------------
-- USER TIMELINE CACHE - Cached timeline data for fast retrieval
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.user_timeline_cache (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,
    timeline_type text NOT NULL,
    posts_data jsonb DEFAULT '[]'::jsonb NOT NULL,
    last_updated timestamp with time zone DEFAULT now(),
    created_at timestamp with time zone DEFAULT now(),
    
    CONSTRAINT user_timeline_cache_timeline_type_check CHECK (timeline_type IN ('home', 'local', 'public'))
);

CREATE INDEX IF NOT EXISTS idx_user_timeline_cache_user ON public.user_timeline_cache(user_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_user_timeline_cache_user_type ON public.user_timeline_cache(user_id, timeline_type);

COMMENT ON TABLE public.user_timeline_cache IS 'Pre-computed timeline cache for instant feed loading';

-- ---------------------------------------------------------------------------
-- ADD FOREIGN KEY for user_servers.folder_id (now that server_folders exists)
-- ---------------------------------------------------------------------------
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.table_constraints 
        WHERE constraint_name = 'user_servers_folder_id_fkey'
        AND table_name = 'user_servers'
    ) THEN
        ALTER TABLE public.user_servers 
            ADD CONSTRAINT user_servers_folder_id_fkey 
            FOREIGN KEY (folder_id) REFERENCES public.server_folders(id) ON DELETE SET NULL;
    END IF;
END $$;

DO $$
BEGIN
    RAISE NOTICE 'Trending & discovery tables created successfully';
END $$;


-- ==== 08_tables_bots_extended.sql ====
-- =============================================================================
-- Harmony Database Schema - Extended Bot Tables
-- =============================================================================
-- Additional bot functionality: commands, webhooks, presence, rate limits
-- =============================================================================

-- ---------------------------------------------------------------------------
-- BOT COMMANDS - Registered bot commands
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.bot_commands (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    bot_id uuid NOT NULL REFERENCES public.bots(id) ON DELETE CASCADE,
    
    -- Command definition
    name text NOT NULL,
    description text,
    usage text,
    
    -- Command type: slash, prefix, context_menu
    command_type text DEFAULT 'prefix'::text,
    
    -- Options/arguments schema
    options jsonb DEFAULT '[]'::jsonb,
    
    -- Permissions required to use
    required_permissions bigint DEFAULT 0,
    
    -- Cooldown in seconds
    cooldown_seconds integer DEFAULT 0,
    
    -- Guild vs global
    is_guild_command boolean DEFAULT true,
    enabled_guild_ids uuid[] DEFAULT '{}'::uuid[],
    
    -- Usage stats
    usage_count integer DEFAULT 0,
    last_used_at timestamp with time zone,
    
    UNIQUE(bot_id, name),
    CONSTRAINT bot_commands_type_check CHECK (command_type IN ('prefix', 'slash', 'context_menu'))
);

ALTER TABLE public.bot_commands REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_bot_commands_bot ON public.bot_commands(bot_id);
CREATE INDEX IF NOT EXISTS idx_bot_commands_name ON public.bot_commands(name);

COMMENT ON TABLE public.bot_commands IS 'Registered bot commands for discovery';

-- ---------------------------------------------------------------------------
-- BOT WEBHOOKS - Webhook endpoints for bots
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.bot_webhooks (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    bot_id uuid NOT NULL REFERENCES public.bots(id) ON DELETE CASCADE,
    
    -- Webhook details
    name text NOT NULL,
    url text NOT NULL,
    secret text,
    
    -- Target channel
    channel_id uuid REFERENCES public.channels(id) ON DELETE SET NULL,
    server_id uuid REFERENCES public.servers(id) ON DELETE CASCADE,
    
    -- Event subscriptions
    events text[] DEFAULT '{}'::text[],
    
    -- State
    is_active boolean DEFAULT true,
    
    -- Stats
    last_triggered_at timestamp with time zone,
    trigger_count integer DEFAULT 0,
    failure_count integer DEFAULT 0,
    last_error text,
    
    UNIQUE(bot_id, channel_id, name)
);

CREATE INDEX IF NOT EXISTS idx_bot_webhooks_bot ON public.bot_webhooks(bot_id);
CREATE INDEX IF NOT EXISTS idx_bot_webhooks_channel ON public.bot_webhooks(channel_id);

COMMENT ON TABLE public.bot_webhooks IS 'Bot webhook configurations';

-- ---------------------------------------------------------------------------
-- BOT PRESENCE - Bot online/offline status tracking
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.bot_presence (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    
    bot_id uuid NOT NULL UNIQUE REFERENCES public.bots(id) ON DELETE CASCADE,
    
    -- Status: online, idle, dnd, offline
    status text DEFAULT 'offline'::text,
    
    -- Custom status message
    activity_type text,  -- playing, listening, watching, streaming, competing
    activity_name text,
    activity_url text,
    
    -- Connection info
    connected_at timestamp with time zone,
    last_heartbeat_at timestamp with time zone,
    
    -- Shard info for distributed bots
    shard_id integer,
    total_shards integer,
    
    -- Version info
    gateway_version text,
    gateway_session_id text,
    latency_ms integer,

    CONSTRAINT bot_presence_status_check CHECK (status IN ('online', 'idle', 'dnd', 'offline'))
);

ALTER TABLE public.bot_presence REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_bot_presence_status ON public.bot_presence(status);

COMMENT ON TABLE public.bot_presence IS 'Bot online presence and status';

-- ---------------------------------------------------------------------------
-- BOT RATE LIMITS - Sliding-window rate-limit tracking for bot API requests.
--
-- BUGS.md B1 (code review of PH1, 2026-05-20):
-- Init previously declared a `limit_max`/`remaining`/`violations`/
-- `last_violation_at` shape, but production (`latest_dev_backup.sql:18834`)
-- and the gateway code (`bot-gateway/src/auth/BotAuthMiddleware.ts:80-119`)
-- have always used `request_count`/`window_start`/`window_duration_seconds`/
-- `max_requests`/`resets_at`/`metadata`. A fresh install from the old init
-- would create a table whose columns the gateway can't read, the catch in
-- `checkRateLimit` would swallow every failure, and rate-limiting would be
-- silently fail-open on every fresh deployment.
--
-- The shape below mirrors prod verbatim. Deployed environments are not
-- affected by this rewrite (they already have the prod shape); the
-- accompanying migration (`db_schema/migrations/20260520_perf_indexes_and_
-- bot_rate_limits_column.sql`) is state-aware enough to reconcile either
-- the new-shape init or any partial drift.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.bot_rate_limits (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    
    bot_id uuid NOT NULL REFERENCES public.bots(id) ON DELETE CASCADE,
    
    -- Rate limit bucket (e.g., 'messages', 'reactions', 'channel:123')
    bucket text NOT NULL,
    
    -- Sliding-window tracking (matches BotAuthMiddleware.checkRateLimit).
    request_count integer DEFAULT 0,
    window_start timestamp with time zone DEFAULT now() NOT NULL,
    window_duration_seconds integer DEFAULT 60,
    max_requests integer DEFAULT 100,
    resets_at timestamp with time zone DEFAULT (now() + '00:01:00'::interval),
    
    metadata jsonb DEFAULT '{}'::jsonb,
    
    UNIQUE(bot_id, bucket)
);

CREATE INDEX IF NOT EXISTS idx_bot_rate_limits_bot ON public.bot_rate_limits(bot_id);
CREATE INDEX IF NOT EXISTS idx_bot_rate_limits_resets_at ON public.bot_rate_limits(resets_at);

COMMENT ON TABLE public.bot_rate_limits IS 'Rate limiting data for bot API requests. Sliding window rate limits per bucket.';

-- ---------------------------------------------------------------------------
-- BOT AUDIT LOG - Bot action audit trail
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.bot_audit_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    
    bot_id uuid NOT NULL REFERENCES public.bots(id) ON DELETE CASCADE,
    
    -- Action details
    action_type text NOT NULL,
    target_type text,
    target_id text,
    
    -- Context
    server_id uuid REFERENCES public.servers(id) ON DELETE SET NULL,
    channel_id uuid REFERENCES public.channels(id) ON DELETE SET NULL,
    user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,

    -- Request details
    request_data jsonb DEFAULT '{}'::jsonb,
    response_data jsonb DEFAULT '{}'::jsonb,
    
    -- Status
    success boolean DEFAULT true,
    error_message text,

    -- Timing
    duration_ms integer,

    metadata jsonb DEFAULT '{}'::jsonb
);

CREATE INDEX IF NOT EXISTS idx_bot_audit_log_bot ON public.bot_audit_log(bot_id);
CREATE INDEX IF NOT EXISTS idx_bot_audit_log_created ON public.bot_audit_log(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_bot_audit_log_server ON public.bot_audit_log(server_id);

COMMENT ON TABLE public.bot_audit_log IS 'Audit log for bot actions';

DO $$
BEGIN
    RAISE NOTICE 'Extended bot tables created successfully';
END $$;


-- ==== 09_tables_encryption.sql ====
-- =============================================================================
-- Harmony Database Schema - Encryption Tables
-- =============================================================================
-- End-to-end encryption: Megolm sessions, key backups, recovery
-- =============================================================================

-- ---------------------------------------------------------------------------
-- USER PRIVATE KEYS - Federation key pairs (service_role access only)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.user_private_keys (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE,
    private_key text NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_user_private_keys_user ON public.user_private_keys(user_id);

COMMENT ON TABLE public.user_private_keys IS 'Federation private keys - accessible only via service_role';

-- ---------------------------------------------------------------------------
-- MEGOLM ROOM SESSIONS - E2E encrypted room sessions
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.megolm_room_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    -- Session identity
    session_id text NOT NULL,
    room_id text NOT NULL,  -- conversation_id or channel_id
    room_type text NOT NULL, -- 'conversation' or 'channel'
    
    -- Creator
    creator_user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    creator_device_id text NOT NULL,
    
    -- Session key (encrypted)
    encrypted_session_key text NOT NULL,
    
    -- Key rotation
    message_index integer DEFAULT 0,
    max_message_index integer DEFAULT 100,
    
    -- Status
    is_active boolean DEFAULT true,
    rotated_at timestamp with time zone,
    
    -- Sharing
    shared_with_count integer DEFAULT 0,
    
    UNIQUE(session_id, room_id),
    CONSTRAINT megolm_room_sessions_type_check CHECK (room_type IN ('conversation', 'channel'))
);

ALTER TABLE public.megolm_room_sessions REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_megolm_room_sessions_room ON public.megolm_room_sessions(room_id, room_type);
CREATE INDEX IF NOT EXISTS idx_megolm_room_sessions_session ON public.megolm_room_sessions(session_id);
CREATE INDEX IF NOT EXISTS idx_megolm_room_sessions_creator ON public.megolm_room_sessions(creator_user_id);

COMMENT ON TABLE public.megolm_room_sessions IS 'Megolm E2E encryption sessions for rooms';

-- ---------------------------------------------------------------------------
-- MEGOLM SESSION SHARES - Track who has which session keys
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.megolm_session_shares (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    
    session_id text NOT NULL,
    room_id text NOT NULL,
    
    -- Sender (who wrapped the key). Needed by the recipient to run ECDH and by
    -- get_unclaimed_session_shares(); the client always populates it.
    sender_user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    -- Recipient. recipient_device_id defaults to 'default' until the per-device
    -- identity model (see user_devices) starts populating it for real.
    recipient_user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    -- Nullable: the client does not supply a per-device id. Made NOT NULL in
    -- the original DDL, dropped by
    -- migrations/20260530_align_megolm_encryption_schema.sql because writes
    -- failed against it.
    recipient_device_id text DEFAULT 'default'::text,
    
    -- Share status. is_claimed mirrors (claimed_at IS NOT NULL) for fast lookup
    -- by get_unclaimed_session_shares() / claim_session_share().
    claimed_at timestamp with time zone,
    is_claimed boolean DEFAULT false,

    -- The encrypted session key for this recipient
    encrypted_session_key text NOT NULL,

    -- What index was shared
    first_known_index integer DEFAULT 0,
    
    -- Conflict target used by the client upsert (one share per recipient/session).
    UNIQUE(room_id, session_id, recipient_user_id)
);

CREATE INDEX IF NOT EXISTS idx_megolm_session_shares_recipient ON public.megolm_session_shares(recipient_user_id, recipient_device_id);
CREATE INDEX IF NOT EXISTS idx_megolm_session_shares_session ON public.megolm_session_shares(session_id, room_id);
CREATE INDEX IF NOT EXISTS idx_megolm_session_shares_unclaimed ON public.megolm_session_shares(recipient_user_id) WHERE is_claimed = false;

COMMENT ON TABLE public.megolm_session_shares IS 'Tracking of shared Megolm session keys';

-- ---------------------------------------------------------------------------
-- MEGOLM KEY REQUESTS - Requests for missing session keys
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.megolm_key_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    -- Legacy mirror of requester_user_id kept for backwards compatibility
    -- (the client still writes it on insert).
    user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    -- Requester
    requester_user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    -- Nullable for the same reason as megolm_session_shares.recipient_device_id.
    requester_device_id text DEFAULT 'default'::text,
    
    -- The user we are asking to fulfill (original sender / session holder).
    -- broadcast_key_request_event() routes the request to user:{sender_user_id}.
    sender_user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    
    -- What key is being requested
    session_id text NOT NULL,
    room_id text NOT NULL,
    
    -- Request status
    status text DEFAULT 'pending'::text,
    
    -- Signed request material (Megolm key-request authorization, see MessageSigner).
    request_signature text,
    request_signing_fingerprint text,
    
    -- Fulfillment payload (ECDH-wrapped session key for the requester).
    encrypted_key text,
    fulfilled_at timestamp with time zone
);

-- Added NOT VALID to match migrations/20260530_align_megolm_encryption_schema.sql,
-- which widened the allowed statuses and deliberately left the constraint
-- unvalidated against pre-existing rows. A fresh table has none, so the two
-- builds enforce the same rule on every write.
ALTER TABLE public.megolm_key_requests
    ADD CONSTRAINT megolm_key_requests_status_check
    CHECK (status IN ('pending', 'sent', 'received', 'cancelled', 'ignored', 'fulfilled', 'expired'))
    NOT VALID;

CREATE INDEX IF NOT EXISTS idx_megolm_key_requests_requester ON public.megolm_key_requests(requester_user_id);
CREATE INDEX IF NOT EXISTS idx_megolm_key_requests_sender ON public.megolm_key_requests(sender_user_id);
CREATE INDEX IF NOT EXISTS idx_megolm_key_requests_session ON public.megolm_key_requests(session_id, room_id);
CREATE INDEX IF NOT EXISTS idx_megolm_key_requests_status ON public.megolm_key_requests(status) WHERE status = 'pending';

COMMENT ON TABLE public.megolm_key_requests IS 'Requests for missing Megolm session keys';

-- ---------------------------------------------------------------------------
-- MEGOLM KEY BACKUPS - Encrypted key backups
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.megolm_key_backups (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    
    -- One backup row per user (client upserts onConflict 'user_id').
    user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    -- Backup payload as written by MegolmKeyBackupService: a recovery-key
    -- encrypted JSON blob plus integrity hash and bookkeeping.
    encrypted_data text,
    version integer DEFAULT 1,
    session_count integer DEFAULT 0,
    backup_hash text,
    last_updated timestamp with time zone DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_megolm_key_backups_user ON public.megolm_key_backups(user_id);

COMMENT ON TABLE public.megolm_key_backups IS 'Encrypted Megolm key backups (one row per user)';

-- ---------------------------------------------------------------------------
-- RECOVERY KEY METADATA - Recovery key info (not the key itself!)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.recovery_key_metadata (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    -- Key version and verification
    key_version integer DEFAULT 1 NOT NULL,
    verification_code text NOT NULL,
    word_count integer DEFAULT 12,
    
    -- Backup status
    has_server_backup boolean DEFAULT false,
    last_backup_at timestamp with time zone,
    
    -- Timestamps
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_verified_at timestamp with time zone,
    
    -- Storage hint for user
    storage_hint text,
    
    CONSTRAINT recovery_key_metadata_word_count_check CHECK (word_count = ANY (ARRAY[12, 24]))
);

CREATE INDEX IF NOT EXISTS idx_recovery_key_metadata_user ON public.recovery_key_metadata(user_id);

COMMENT ON TABLE public.recovery_key_metadata IS 'Recovery key metadata (NOT the key itself)';

-- ---------------------------------------------------------------------------
-- MFA RECOVERY CODES - One-time MFA recovery codes
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.mfa_recovery_codes (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    
    -- Code hash (never store plain codes!)
    code_hash text NOT NULL,
    
    -- Usage tracking
    used_at timestamp with time zone,
    is_used boolean DEFAULT false,
    
    -- Generation batch
    batch_id uuid NOT NULL,
    
    created_at timestamp with time zone DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_mfa_recovery_codes_user ON public.mfa_recovery_codes(user_id);
CREATE INDEX IF NOT EXISTS idx_mfa_recovery_codes_available ON public.mfa_recovery_codes(user_id, is_used) WHERE is_used = false;

COMMENT ON TABLE public.mfa_recovery_codes IS 'One-time MFA recovery codes (hashed)';

-- ---------------------------------------------------------------------------
-- CONVERSATION ENCRYPTION SETTINGS - Per-conversation encryption config
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.conversation_encryption_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    conversation_id uuid NOT NULL UNIQUE REFERENCES public.conversations(id) ON DELETE CASCADE,
    
    -- Encryption enabled?
    encryption_enabled boolean DEFAULT false,
    encryption_algorithm text DEFAULT 'm.megolm.v1.aes-sha2'::text,

    -- Participant device verification state. No writer sets it true; it is
    -- read back as false until device cross-signing lands.
    verified boolean DEFAULT false,

    -- Key rotation policy
    rotation_period_ms bigint DEFAULT 604800000, -- 7 days
    rotation_message_count integer DEFAULT 100,
    
    -- Last rotation
    last_rotation_at timestamp with time zone,
    current_session_id text,
    
    -- History visibility for new members
    history_visibility text DEFAULT 'shared'::text,
    
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    
    CONSTRAINT conversation_encryption_visibility_check CHECK (history_visibility IN ('shared', 'invited', 'joined'))
);

CREATE INDEX IF NOT EXISTS idx_conversation_encryption_conv ON public.conversation_encryption_settings(conversation_id);

COMMENT ON TABLE public.conversation_encryption_settings IS 'Per-conversation encryption settings';

-- ---------------------------------------------------------------------------
-- SERVER ENCRYPTION SETTINGS - Per-server E2EE enforcement policies
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.server_encryption_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    server_id uuid NOT NULL UNIQUE REFERENCES public.servers(id) ON DELETE CASCADE,
    
    -- Encryption mode: disabled, optional, required, required_local_only
    encryption_mode text DEFAULT 'optional'::text,
    
    -- Federation settings
    allow_federation boolean DEFAULT true,
    
    -- Device verification requirements
    require_verified_devices boolean DEFAULT false,
    
    -- Force key setup for new users
    force_key_setup boolean DEFAULT false NOT NULL,
    
    -- Encrypt file attachments
    encrypt_attachments boolean DEFAULT true NOT NULL,
    
    -- Voice/video E2EE mode. Unlike messages there is no per-call "optional":
    -- LiveKit E2EE is room-wide, so a call is either fully encrypted or not.
    --   disabled: voice/video uses transport security only (DTLS-SRTP)
    --   required: media is E2E encrypted; participants who can't do E2EE are refused
    voice_encryption_mode text DEFAULT 'disabled'::text NOT NULL,
    
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    updated_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    
    -- Additional metadata
    metadata jsonb DEFAULT '{}'::jsonb,
    
    CONSTRAINT server_encryption_settings_encryption_mode_check 
        CHECK (encryption_mode = ANY (ARRAY['disabled'::text, 'optional'::text, 'required'::text, 'required_local_only'::text])),
    CONSTRAINT server_encryption_settings_voice_encryption_mode_check 
        CHECK (voice_encryption_mode = ANY (ARRAY['disabled'::text, 'required'::text]))
);

CREATE INDEX IF NOT EXISTS idx_server_encryption_server ON public.server_encryption_settings(server_id);

COMMENT ON TABLE public.server_encryption_settings IS 'Per-server E2EE enforcement policies. Server owners control encryption requirements.';
COMMENT ON COLUMN public.server_encryption_settings.encryption_mode IS 'disabled: No E2EE. optional: User choice. required: All messages encrypted. required_local_only: E2EE required, federation disabled.';
COMMENT ON COLUMN public.server_encryption_settings.voice_encryption_mode IS 'disabled: voice/video transport-secured only (DTLS-SRTP). required: voice/video media is E2E encrypted (server-blind); non-capable participants are refused.';

-- ---------------------------------------------------------------------------
-- ENCRYPTION SESSIONS - Signal Protocol session state
-- DEPRECATED (July 2026): the Signal client stack was removed; the app uses
-- Megolm-style encryption. Kept for existing rows; DROP planned in a future
-- migration once no live instance depends on it.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.encryption_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    local_user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    local_device_id text DEFAULT 'default'::text,
    remote_user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    remote_device_id text DEFAULT 'default'::text,
    session_state text NOT NULL, -- Serialized Signal Protocol session state (encrypted)
    established_at timestamp with time zone DEFAULT now() NOT NULL,
    last_used_at timestamp with time zone DEFAULT now(),
    message_count integer DEFAULT 0, -- For automatic session rotation
    needs_refresh boolean DEFAULT false,
    metadata jsonb DEFAULT '{}'::jsonb,

    UNIQUE(local_user_id, local_device_id, remote_user_id, remote_device_id)
);
COMMENT ON TABLE public.encryption_sessions IS 'DEPRECATED: Signal Protocol session state. Unused since the Signal client stack was removed (July 2026); scheduled for removal.';

CREATE INDEX IF NOT EXISTS idx_encryption_sessions_local ON public.encryption_sessions(local_user_id, local_device_id);
CREATE INDEX IF NOT EXISTS idx_encryption_sessions_remote ON public.encryption_sessions(remote_user_id, remote_device_id);

-- ---------------------------------------------------------------------------
-- ENCRYPTION AUDIT LOG - Security event logging
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.encryption_audit_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    event_type text NOT NULL, -- 'key_generated', 'session_established', 'key_rotation', 'key_verification'
    severity text DEFAULT 'info'::text, -- 'info', 'warning', 'error', 'critical'
    description text,

    -- Entity the event is about, when it is not the acting user.
    related_user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
    related_conversation_id uuid REFERENCES public.conversations(id) ON DELETE SET NULL,
    related_server_id uuid REFERENCES public.servers(id) ON DELETE SET NULL,

    metadata jsonb DEFAULT '{}'::jsonb,
    ip_address inet,
    user_agent text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,

    CONSTRAINT encryption_audit_log_severity_check CHECK (severity IN ('info', 'warning', 'error', 'critical'))
);
COMMENT ON TABLE public.encryption_audit_log IS 'Audit log for encryption-related security events';

CREATE INDEX IF NOT EXISTS idx_encryption_audit_user ON public.encryption_audit_log(user_id);
CREATE INDEX IF NOT EXISTS idx_encryption_audit_type ON public.encryption_audit_log(event_type);
CREATE INDEX IF NOT EXISTS idx_encryption_audit_created ON public.encryption_audit_log(created_at DESC);

-- ---------------------------------------------------------------------------
-- USER DEVICES - Per-device encryption identity (Phase 3 device-aware model)
-- ---------------------------------------------------------------------------
-- Each browser profile / install / app gets its own device row with its own
-- ECDH (session-key exchange) and ECDSA (message signing) PUBLIC keys. Private
-- keys never leave the device (IndexedDB, non-extractable). trust_state maps to
-- the internal trust levels surfaced to users only as "approve this login" and
-- "unlock message history":
--   untrusted (L0) - logged in, gets no keys
--   account   (L1) - receives NEW room keys automatically after login
--   recovery  (L2) - unlocked history via the recovery phrase
--   verified  (L3) - approved from another trusted device (full key sync)
--   revoked        - explicitly removed; must not receive any keys
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.user_devices (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    device_id text NOT NULL,

    -- Public key material (private parts stay on the device).
    device_ecdh_public_key text,
    device_signing_public_key text,

    -- Trust + presentation.
    trust_state text NOT NULL DEFAULT 'account',
    platform text,          -- 'web' | 'desktop' | 'mobile'
    label text,             -- human label e.g. "Chrome on Windows"

    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now(),
    revoked_at timestamp with time zone,

    UNIQUE(user_id, device_id),
    CONSTRAINT user_devices_trust_check
        CHECK (trust_state IN ('untrusted', 'account', 'recovery', 'verified', 'revoked'))
);

CREATE INDEX IF NOT EXISTS idx_user_devices_user ON public.user_devices(user_id);
CREATE INDEX IF NOT EXISTS idx_user_devices_active
    ON public.user_devices(user_id) WHERE revoked_at IS NULL;

COMMENT ON TABLE public.user_devices IS 'Per-device encryption identities and trust state (account-friendly, device-aware E2EE).';

-- ---------------------------------------------------------------------------
-- DEVICE APPROVAL REQUESTS - "New login on X - was this you?"
-- ---------------------------------------------------------------------------
-- A freshly logged-in device asks the user's existing trusted devices to
-- approve it (which pushes encrypted key sync). This is the Discord-style
-- new-login prompt, scoped to a single account (requester == approver user).
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.device_approval_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,

    requesting_device_id text NOT NULL,
    requesting_label text,
    requesting_ecdh_public_key text,

    status text NOT NULL DEFAULT 'pending',  -- pending | approved | denied | expired

    -- When approved, the approver wraps the account key-sync bundle for the
    -- requesting device's ECDH public key.
    approved_by_device_id text,
    encrypted_sync_bundle text,

    created_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    expires_at timestamp with time zone DEFAULT (now() + interval '15 minutes'),

    CONSTRAINT device_approval_requests_status_check
        CHECK (status IN ('pending', 'approved', 'denied', 'expired'))
);

CREATE INDEX IF NOT EXISTS idx_device_approval_user ON public.device_approval_requests(user_id);
CREATE INDEX IF NOT EXISTS idx_device_approval_pending
    ON public.device_approval_requests(user_id) WHERE status = 'pending';

COMMENT ON TABLE public.device_approval_requests IS 'New-device approval requests for cross-device key sync (account-scoped).';

-- ---------------------------------------------------------------------------
-- ROOM EPOCH STATE - Membership epochs for backward/forward secrecy at joins
-- ---------------------------------------------------------------------------
-- Each room (channel or conversation) has a monotonically increasing epoch.
-- Membership changes (join/leave) and explicit rotations bump the epoch, which
-- forces a new Megolm session. Messages and session shares carry the epoch they
-- belong to, so a removed member cannot read messages from later epochs.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.room_epoch_state (
    room_id text NOT NULL PRIMARY KEY,
    current_epoch integer NOT NULL DEFAULT 1,
    member_set_hash text,
    reason text,            -- created | member_join | member_leave | device_change | manual_rotate
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

COMMENT ON TABLE public.room_epoch_state IS 'Current membership epoch per room; bumped on membership changes to rotate Megolm sessions.';

DO $$
BEGIN
    RAISE NOTICE 'Encryption tables created successfully';
END $$;


-- ==== 71_views_performance.sql ====
-- =============================================================================
-- Harmony Database Schema - Performance & Admin Views
-- =============================================================================
-- Views for performance monitoring and admin dashboards
-- =============================================================================

-- ---------------------------------------------------------------------------
-- SLOW QUERIES TABLE - Track slow database queries
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.slow_queries (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    "timestamp" timestamp with time zone DEFAULT now() NOT NULL,
    
    -- Query details
    duration_ms double precision NOT NULL,
    query_text text,
    query_hash text,
    operation_type text,
    table_name text,
    parameters jsonb,
    
    -- Context
    source text DEFAULT 'backend'::text,
    user_id uuid,
    request_id text,
    rows_affected integer,
    recorded_at timestamp with time zone
);

CREATE INDEX IF NOT EXISTS idx_slow_queries_timestamp ON public.slow_queries("timestamp" DESC);
CREATE INDEX IF NOT EXISTS idx_slow_queries_duration ON public.slow_queries(duration_ms DESC);
CREATE INDEX IF NOT EXISTS idx_slow_queries_table ON public.slow_queries(table_name);

COMMENT ON TABLE public.slow_queries IS 'Tracked slow database queries for performance analysis';

-- ---------------------------------------------------------------------------
-- FEDERATION HEALTH TABLE - Instance health status
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.federation_health (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    timestamp timestamp with time zone DEFAULT now() NOT NULL,
    
    -- UNIQUE constraint on domain for upsert operations
    instance_domain text NOT NULL UNIQUE,
    
    -- Status
    status text DEFAULT 'unknown'::text,
    last_success_at timestamp with time zone,
    last_failure_at timestamp with time zone,
    
    -- Counts
    failure_count integer DEFAULT 0,
    success_count integer DEFAULT 0,
    
    -- Performance
    avg_latency_ms double precision,
    
    -- Error tracking
    last_error text,
    
    -- Metadata
    metadata jsonb DEFAULT '{}'::jsonb,
    
    CONSTRAINT federation_health_status_check CHECK (status IN ('healthy', 'degraded', 'unhealthy', 'unknown'))
);

ALTER TABLE public.federation_health REPLICA IDENTITY FULL;

CREATE INDEX IF NOT EXISTS idx_federation_health_timestamp ON public.federation_health(timestamp DESC);

COMMENT ON TABLE public.federation_health IS 'Health status of federated instances (one row per domain)';

-- ---------------------------------------------------------------------------
-- PERFORMANCE METRICS HOURLY - Aggregated hourly metrics
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.performance_metrics_hourly (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    hour timestamp with time zone NOT NULL,
    
    metric_type text NOT NULL,
    metric_name text NOT NULL,
    
    -- Aggregated values
    count bigint DEFAULT 0,
    sum double precision DEFAULT 0,
    min double precision,
    max double precision,
    avg double precision,
    p50 double precision,
    p95 double precision,
    p99 double precision,
    
    -- Labels aggregation
    labels jsonb DEFAULT '{}'::jsonb,
    source text DEFAULT 'aggregation'::text,
    avg_latency double precision,
    
    UNIQUE(hour, metric_type, metric_name, source)
);

CREATE INDEX IF NOT EXISTS idx_perf_metrics_hourly_hour ON public.performance_metrics_hourly(hour DESC);
CREATE INDEX IF NOT EXISTS idx_perf_metrics_hourly_type ON public.performance_metrics_hourly(metric_type, metric_name);

COMMENT ON TABLE public.performance_metrics_hourly IS 'Hourly aggregated performance metrics';

-- ---------------------------------------------------------------------------
-- SLOW QUERIES SUMMARY VIEW
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.slow_queries_summary WITH (security_invoker = true) AS
SELECT 
    table_name,
    operation_type,
    count(*) AS query_count,
    avg(duration_ms) AS avg_duration_ms,
    max(duration_ms) AS max_duration_ms,
    min(duration_ms) AS min_duration_ms,
    percentile_cont(0.95) WITHIN GROUP (ORDER BY duration_ms) AS p95_duration_ms,
    max("timestamp") AS last_seen
FROM public.slow_queries
WHERE "timestamp" > now() - interval '24 hours'
GROUP BY table_name, operation_type
ORDER BY avg(duration_ms) DESC;

COMMENT ON VIEW public.slow_queries_summary IS 'Summary of slow queries in the last 24 hours';

-- ---------------------------------------------------------------------------
-- METRICS SUMMARY VIEW
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.metrics_summary_view WITH (security_invoker = true) AS
SELECT 
    metric_type,
    metric_name,
    count(*) AS sample_count,
    avg(value) AS avg_value,
    max(value) AS max_value,
    min(value) AS min_value,
    source,
    max(timestamp) AS last_recorded
FROM public.performance_metrics
WHERE timestamp > now() - interval '1 hour'
GROUP BY metric_type, metric_name, source
ORDER BY count(*) DESC;

COMMENT ON VIEW public.metrics_summary_view IS 'Summary of performance metrics in the last hour';

-- ---------------------------------------------------------------------------
-- RPC FUNCTIONS FOR PERFORMANCE MONITORING
-- ---------------------------------------------------------------------------

-- Record slow query function
CREATE OR REPLACE FUNCTION public.record_slow_query(
    p_duration_ms numeric,
    p_query_text text DEFAULT NULL,
    p_operation_type text DEFAULT NULL,
    p_table_name text DEFAULT NULL,
    p_parameters jsonb DEFAULT NULL,
    p_source text DEFAULT 'unknown',
    p_user_id uuid DEFAULT NULL,
    p_request_id text DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    INSERT INTO public.slow_queries (
        duration_ms,
        query_text,
        operation_type,
        table_name,
        parameters,
        source,
        user_id,
        request_id
    ) VALUES (
        p_duration_ms,
        p_query_text,
        p_operation_type,
        p_table_name,
        p_parameters,
        p_source,
        p_user_id,
        p_request_id
    );
END;
$$;

-- Update federation health function
CREATE OR REPLACE FUNCTION public.touch_federated_instance(p_domain text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_domain text;
BEGIN
  v_domain := lower(btrim(p_domain));
  IF v_domain IS NULL OR v_domain = '' THEN
    RETURN;
  END IF;

  INSERT INTO public.federated_instances (
    domain,
    last_seen_at,
    updated_at
  )
  VALUES (
    v_domain,
    now(),
    now()
  )
  ON CONFLICT (domain) DO UPDATE
  SET last_seen_at = now(),
      updated_at = now();
END;
$$;

COMMENT ON FUNCTION public.touch_federated_instance(text)
IS 'Bump federated_instances.last_seen_at when federation traffic is observed. Auto-registers unknown domains.';

GRANT EXECUTE ON FUNCTION public.touch_federated_instance(text) TO service_role;

CREATE OR REPLACE FUNCTION public.update_federation_health(
    p_instance_domain text,
    p_success boolean,
    p_latency_ms numeric DEFAULT NULL,
    p_error text DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_domain text;
BEGIN
    v_domain := lower(btrim(p_instance_domain));
    IF v_domain IS NULL OR v_domain = '' THEN
        RETURN;
    END IF;

    -- Upsert federation health by instance_domain (UNIQUE constraint)
    INSERT INTO public.federation_health (
        instance_domain,
        status,
        last_success_at,
        last_failure_at,
        success_count,
        failure_count,
        avg_latency_ms,
        last_error
    ) VALUES (
        v_domain,
        CASE WHEN p_success THEN 'healthy' ELSE 'unhealthy' END,
        CASE WHEN p_success THEN now() ELSE NULL END,
        CASE WHEN NOT p_success THEN now() ELSE NULL END,
        CASE WHEN p_success THEN 1 ELSE 0 END,
        CASE WHEN NOT p_success THEN 1 ELSE 0 END,
        p_latency_ms,
        p_error
    )
    ON CONFLICT (instance_domain) DO UPDATE SET
        timestamp = now(),
        status = CASE
            WHEN p_success THEN 'healthy'
            ELSE 'unhealthy'
        END,
        last_success_at = CASE WHEN p_success THEN now() ELSE federation_health.last_success_at END,
        last_failure_at = CASE WHEN NOT p_success THEN now() ELSE federation_health.last_failure_at END,
        success_count = federation_health.success_count + CASE WHEN p_success THEN 1 ELSE 0 END,
        failure_count = CASE
            WHEN p_success THEN 0
            ELSE federation_health.failure_count + 1
        END,
        avg_latency_ms = CASE
            WHEN p_latency_ms IS NOT NULL AND federation_health.avg_latency_ms IS NOT NULL
            THEN (federation_health.avg_latency_ms + p_latency_ms) / 2
            ELSE COALESCE(p_latency_ms, federation_health.avg_latency_ms)
        END,
        last_error = CASE
            WHEN p_success THEN NULL
            ELSE COALESCE(p_error, federation_health.last_error)
        END;

    IF p_success THEN
        PERFORM public.touch_federated_instance(v_domain);
    END IF;
END;
$$;

-- Aggregate hourly metrics function
CREATE OR REPLACE FUNCTION public.aggregate_hourly_metrics()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_count integer := 0;
BEGIN
    -- Aggregate metrics from the last hour
    INSERT INTO public.performance_metrics_hourly (
        hour,
        metric_type,
        metric_name,
        count,
        sum,
        min,
        max,
        avg,
        source
    )
    SELECT 
        date_trunc('hour', timestamp) AS hour,
        metric_type,
        metric_name,
        count(*),
        sum(value),
        min(value),
        max(value),
        avg(value),
        source
    FROM public.performance_metrics
    WHERE timestamp >= date_trunc('hour', now() - interval '1 hour')
      AND timestamp < date_trunc('hour', now())
    GROUP BY date_trunc('hour', timestamp), metric_type, metric_name, source
    -- Column names are the aggregate names, matching the table. Production's copy of this
    -- function conflicts on (hour, metric_type, metric_name, labels) because its table
    -- carries that constraint; this one keeps the source-based constraint declared above.
    ON CONFLICT (hour, metric_type, metric_name, source) DO UPDATE SET
        count = EXCLUDED.count,
        sum = EXCLUDED.sum,
        min = EXCLUDED.min,
        max = EXCLUDED.max,
        avg = EXCLUDED.avg;
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;

-- Cleanup old metrics function
CREATE OR REPLACE FUNCTION public.cleanup_old_metrics(
    p_raw_retention_days integer DEFAULT 7,
    p_hourly_retention_days integer DEFAULT 90,
    p_slow_query_retention_days integer DEFAULT 30
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_raw_deleted integer;
    v_hourly_deleted integer;
    v_slow_deleted integer;
BEGIN
    -- Delete old raw metrics
    DELETE FROM public.performance_metrics
    WHERE timestamp < now() - (p_raw_retention_days || ' days')::interval;
    GET DIAGNOSTICS v_raw_deleted = ROW_COUNT;
    
    -- Delete old hourly metrics
    DELETE FROM public.performance_metrics_hourly
    WHERE hour < now() - (p_hourly_retention_days || ' days')::interval;
    GET DIAGNOSTICS v_hourly_deleted = ROW_COUNT;
    
    -- Delete old slow queries. The column is "timestamp"; slow_queries has no created_at.
    DELETE FROM public.slow_queries
    WHERE "timestamp" < now() - (p_slow_query_retention_days || ' days')::interval;
    GET DIAGNOSTICS v_slow_deleted = ROW_COUNT;
    
    RETURN jsonb_build_object(
        'raw_metrics_deleted', v_raw_deleted,
        'hourly_metrics_deleted', v_hourly_deleted,
        'slow_queries_deleted', v_slow_deleted
    );
END;
$$;

DO $$
BEGIN
    RAISE NOTICE 'Performance views and functions created successfully';
END $$;


-- ==== 10_functions_core.sql ====
-- =============================================================================
-- Harmony Database Schema - Core Functions
-- =============================================================================
-- Helper functions, utilities, and commonly used operations
-- =============================================================================

-- ---------------------------------------------------------------------------
-- CONTENT LENGTH HELPERS
-- ---------------------------------------------------------------------------

-- Sum the character length of every `text` part in a MessagePart-shape jsonb
-- array (the format used by `messages.content` and `posts.content`). Walks
-- the array with `->`/`->>` (both IMMUTABLE) so the function itself can be
-- marked IMMUTABLE and referenced from CHECK constraints.
--
-- Non-text parts (mentions, emojis, files, urls, embeds) are skipped because
-- their payloads are structurally bounded by separate validation (file
-- count limits, URL parsing, mention resolution, …).
--
-- Returns 0 for NULL / non-array input so the CHECK constraint never raises
-- on malformed content - that case is handled by the
-- `messages_content_is_array` / `posts_content_is_array` constraints which
-- are checked first.
CREATE OR REPLACE FUNCTION public.jsonb_text_content_length(content jsonb)
RETURNS integer
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
AS $$
DECLARE
    total integer := 0;
    n integer;
    i integer;
    part jsonb;
BEGIN
    IF content IS NULL OR jsonb_typeof(content) <> 'array' THEN
        RETURN 0;
    END IF;

    n := jsonb_array_length(content);
    IF n = 0 THEN
        RETURN 0;
    END IF;

    FOR i IN 0..(n - 1) LOOP
        part := content -> i;
        IF jsonb_typeof(part) = 'object' AND (part ->> 'type') = 'text' THEN
            total := total + COALESCE(char_length(part ->> 'text'), 0);
        END IF;
    END LOOP;

    RETURN total;
END;
$$;

COMMENT ON FUNCTION public.jsonb_text_content_length(jsonb) IS
'Total character count across all text parts of a MessagePart[] jsonb. IMMUTABLE so it can be used from CHECK constraints. Keep MAX_MESSAGE_TEXT_LENGTH / MAX_POST_TEXT_LENGTH in src/utils/messageContentUtils.ts in sync with the constraint limits.';

-- ---------------------------------------------------------------------------
-- PROFILE HELPERS
-- ---------------------------------------------------------------------------

-- Get current user's profile ID (used by RLS)
CREATE OR REPLACE FUNCTION public.get_current_profile_id()
RETURNS uuid
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    SELECT id FROM public.profiles WHERE auth_user_id = auth.uid() LIMIT 1;
$$;

COMMENT ON FUNCTION public.get_current_profile_id() IS 
'Returns the profile ID for the currently authenticated user. Used by RLS policies.';

-- Alternative function name for compatibility
CREATE OR REPLACE FUNCTION public.get_current_user_profile_id()
RETURNS uuid
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    profile_uuid uuid;
BEGIN
    SELECT id INTO profile_uuid
    FROM profiles
    WHERE auth_user_id = auth.uid()
    LIMIT 1;
    
    RETURN profile_uuid;
END;
$$;

-- Check if current user is admin
CREATE OR REPLACE FUNCTION public.is_current_user_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    SELECT COALESCE(
        (SELECT is_admin FROM public.profiles WHERE auth_user_id = auth.uid()),
        false
    );
$$;

-- Check if current user is instance moderator
CREATE OR REPLACE FUNCTION public.is_current_user_moderator()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    SELECT COALESCE(
        (SELECT is_moderator FROM public.profiles WHERE auth_user_id = auth.uid()),
        false
    );
$$;

-- Check if current user is admin OR moderator
CREATE OR REPLACE FUNCTION public.is_current_user_admin_or_mod()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    SELECT COALESCE(
        (SELECT (is_admin OR is_moderator) FROM public.profiles WHERE auth_user_id = auth.uid()),
        false
    );
$$;

-- Check if current user can manage messages in a given channel
-- Checks server ownership, server admin role, and MANAGE_MESSAGES (bit 21)
CREATE OR REPLACE FUNCTION public.can_current_user_manage_messages_in_channel(p_channel_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_profile_id uuid;
    v_server_id uuid;
    v_is_owner boolean;
    v_has_perm boolean;
BEGIN
    v_profile_id := public.get_current_profile_id();
    IF v_profile_id IS NULL THEN RETURN false; END IF;

    SELECT server_id INTO v_server_id FROM public.channels WHERE id = p_channel_id;
    IF v_server_id IS NULL THEN RETURN false; END IF;

    SELECT (owner = v_profile_id) INTO v_is_owner FROM public.servers WHERE id = v_server_id;
    IF v_is_owner THEN RETURN true; END IF;

    -- Check if user has a role with ADMINISTRATOR (bit 0) or MANAGE_MESSAGES (bit 21)
    SELECT EXISTS (
        SELECT 1
        FROM public.user_roles ur
        JOIN public.server_roles sr ON sr.id = ur.role_id
        WHERE ur.user_id = v_profile_id
          AND sr.server_id = v_server_id
          AND (
              sr.is_admin = true
              OR (sr.permissions & (1::bigint << 0)) != 0
              OR (sr.permissions & (1::bigint << 21)) != 0
          )
    ) INTO v_has_perm;

    RETURN v_has_perm;
END;
$$;

-- Check if author is suspended (used by RLS)
CREATE OR REPLACE FUNCTION public.is_author_suspended(p_author_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    -- The outer COALESCE covers both a missing row and a NULL is_suspended:
    -- the subquery yields NULL in either case.
    SELECT COALESCE(
        (SELECT is_suspended FROM public.profiles WHERE id = p_author_id),
        false
    );
$$;

COMMENT ON FUNCTION public.is_author_suspended(p_author_id uuid) IS 
'Returns true if the post author is suspended. Returns FALSE for missing profiles.';

