-- MUTING HELPERS
-- ---------------------------------------------------------------------------

-- Check if current user is muted by a specific user (not commonly needed, but for symmetry)
CREATE OR REPLACE FUNCTION public.is_muted_by(target_user_id uuid)
RETURNS boolean
LANGUAGE sql
