GRANT EXECUTE ON FUNCTION public.is_blocked_by(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.has_blocked(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.is_muted_by(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.has_muted(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.current_user_is_member_of_server(uuid) TO authenticated;

CREATE OR REPLACE FUNCTION public.can_subscribe_to_topic(p_topic text)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_profile_id uuid;
  v_id         uuid;
  v_server_id  uuid;
BEGIN
  IF p_topic IS NULL THEN
    RETURN false;
  END IF;

  v_profile_id := public.get_current_profile_id();
  IF v_profile_id IS NULL THEN
    RETURN false;
  END IF;

  IF p_topic LIKE 'dm-conversation-%' THEN
    BEGIN
      v_id := substring(p_topic from 17)::uuid;
    EXCEPTION WHEN others THEN
      RETURN false;
    END;
    RETURN public.is_conversation_participant(v_id, v_profile_id);
  END IF;

  IF p_topic LIKE 'channel-messages-%' THEN
    BEGIN
      v_id := substring(p_topic from 18)::uuid;
    EXCEPTION WHEN others THEN
      RETURN false;
    END;
    SELECT server_id INTO v_server_id FROM public.channels WHERE id = v_id;
    IF v_server_id IS NULL THEN
      RETURN false;
    END IF;
    -- status is checked inline: current_user_is_member_of_server() tests row
    -- existence only, which would admit 'banned'. messages_select_channel_member
    -- requires 'accepted', and this gate replaces it for delivery.
    RETURN EXISTS (
      SELECT 1 FROM public.user_servers
      WHERE server_id = v_server_id
        AND user_id = v_profile_id
        AND status = 'accepted'
    );
  END IF;

  IF p_topic LIKE 'server-presence:%' OR p_topic LIKE 'server-structure:%' THEN
    BEGIN
      v_id := split_part(p_topic, ':', 2)::uuid;
    EXCEPTION WHEN others THEN
      RETURN false;
    END;
    RETURN EXISTS (
      SELECT 1 FROM public.user_servers
      WHERE server_id = v_id
        AND user_id = v_profile_id
        AND status = 'accepted'
    );
  END IF;

  IF p_topic LIKE 'user:%' THEN
    BEGIN
      v_id := substring(p_topic from 6)::uuid;
    EXCEPTION WHEN others THEN
      RETURN false;
    END;
    RETURN v_id = v_profile_id;
  END IF;


  -- Feed topics carry only public, non-deleted posts: broadcast_post_event
  -- gates every send on visibility = 'public'. No per-user check applies.
  IF p_topic IN ('feed:public', 'feed:local')
     OR p_topic LIKE 'feed:user:%'
     OR p_topic LIKE 'feed:hashtag:%' THEN
    RETURN true;
  END IF;

  RETURN false;
END;
$$;

COMMENT ON FUNCTION public.can_subscribe_to_topic(text) IS
'Authorizes a Broadcast topic for the current user. Broadcast carries no row context, so this is the only gate on realtime.messages SELECT.';

GRANT EXECUTE ON FUNCTION public.can_subscribe_to_topic(text) TO authenticated;


-- ---------------------------------------------------------------------------
-- FEDERATION JOB QUEUE
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.queue_federation_job(
    p_job_name text,
    p_job_data jsonb,
    p_priority integer DEFAULT 5,
    p_retry_limit integer DEFAULT 5,
    p_expire_in_seconds integer DEFAULT 3600
)
RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_job_id uuid;
    v_target_domain text;
BEGIN
    v_job_id := gen_random_uuid();

    PERFORM pg_notify('federation_jobs', json_build_object(
        'name', p_job_name,
        'id', v_job_id::text,
        'data', p_job_data
    )::text);

    RETURN v_job_id;
EXCEPTION
    WHEN OTHERS THEN
        v_target_domain := p_job_data->>'target_domain';
        IF v_target_domain IS NOT NULL AND v_target_domain != '' THEN
            RAISE LOG 'pg_notify failed, using delivery queue fallback for job % to %', p_job_name, v_target_domain;
            INSERT INTO public.federation_delivery_queue (
                activity_data, target_inbox_url, target_domain,
                sender_id, status, next_attempt_at
            ) VALUES (
                p_job_data,
                COALESCE(p_job_data->>'target_inbox', 'https://' || v_target_domain || '/inbox'),
                v_target_domain,
                (p_job_data->>'sender_id')::UUID,
                'pending',
                NOW()
            )
            RETURNING id INTO v_job_id;

            PERFORM pg_notify('federation_jobs', json_build_object(
                'name', 'delivery-queue-fallback',
                'id', v_job_id::text
            )::text);

            RETURN v_job_id;
        ELSE
            RAISE LOG 'pg_notify failed, skipping job %', p_job_name;
            RETURN NULL;
        END IF;
END;
$$;

-- ---------------------------------------------------------------------------
-- CONTENT LENGTH ENFORCEMENT (admin config + absolute backstop)
-- ---------------------------------------------------------------------------
-- Length enforcement has TWO layers, both at the storage boundary so a
-- direct PostgREST POST (bypassing the application) can't slip through:
--
--   1. BEFORE INSERT/UPDATE triggers that read the LIVE admin config
--      (`instance_config.max_message_length` / `max_post_length`) and
--      reject if exceeded. This is the actual user-facing limit - the
--      same number the admin sees in the dashboard.
--
--   2. CHECK constraints that enforce a very large absolute ceiling
--      (50000 chars). Pure safety net for two cases:
--        a) the admin sets a wildly unreasonable value;
--        b) the trigger gets disabled by an operator.
--
-- A CHECK constraint cannot reference a config row (CHECKs must use
-- IMMUTABLE expressions), so the trigger is required to enforce the
-- admin-configured limit at the storage layer. The trigger is the
-- canonical limit; the CHECK is the seatbelt.
--
-- Encrypted messages are exempt from the plaintext char-length cap
-- because their `text` parts hold base64 ciphertext. A separate
-- byte-size cap on the whole row is enforced via the trigger so
-- encrypted rows can't grow unboundedly either.

-- Helper: read the admin config value, with a sensible default + clamp.
-- Falls back to `p_default` when the row is missing / unparseable, and
-- clamps to `[1, p_max_ceiling]` so a misconfigured admin value can't
-- silently disable enforcement.
CREATE OR REPLACE FUNCTION public.get_instance_config_int(
    p_key text,
    p_default integer,
    p_max_ceiling integer
)
RETURNS integer
LANGUAGE plpgsql STABLE
SET search_path = public, pg_temp
AS $$
DECLARE
    raw_value jsonb;
    parsed integer;
BEGIN
    SELECT config_value INTO raw_value
    FROM public.instance_config
    WHERE config_key = p_key;

    IF raw_value IS NULL THEN
        RETURN LEAST(p_default, p_max_ceiling);
    END IF;

    -- `config_value` is jsonb; values are stored as a number or string.
    BEGIN
        IF jsonb_typeof(raw_value) = 'number' THEN
            parsed := (raw_value::text)::integer;
        ELSIF jsonb_typeof(raw_value) = 'string' THEN
            parsed := (raw_value #>> '{}')::integer;
        ELSE
            parsed := NULL;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        parsed := NULL;
    END;

    IF parsed IS NULL OR parsed < 1 THEN
        RETURN LEAST(p_default, p_max_ceiling);
    END IF;

    RETURN LEAST(parsed, p_max_ceiling);
END;
$$;

COMMENT ON FUNCTION public.get_instance_config_int(text, integer, integer) IS
'Read a numeric value out of `instance_config`, with a fallback default and a hard ceiling. Used by message/post length triggers to enforce the admin-configured limit at the storage layer.';

-- Trigger: enforce the admin-configured `max_message_length` on
-- `messages.content`. Plaintext char count for non-encrypted messages;
-- byte-size cap on the whole row for encrypted ones (the plaintext is
-- not visible here). System messages are exempt.
CREATE OR REPLACE FUNCTION public.enforce_message_length()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
    soft_limit integer;
    text_len integer;
    encrypted_byte_limit constant integer := 50000;
BEGIN
    -- System messages are server-generated and tightly bounded.
    IF NEW.is_system IS TRUE THEN
        RETURN NEW;
    END IF;

    IF NEW.encrypted IS TRUE THEN
        -- Plaintext char count is invisible here; cap the on-disk
        -- ciphertext bytes so flipping `encrypted=true` from a direct
        -- POST can't be used to store an unbounded payload.
        IF octet_length(NEW.content::text) > encrypted_byte_limit THEN
            RAISE EXCEPTION 'Encrypted message payload exceeds maximum size of % bytes', encrypted_byte_limit
                USING ERRCODE = 'check_violation',
                      HINT = 'Send shorter messages - the plaintext limit is enforced by the client before encryption.';
        END IF;
        RETURN NEW;
    END IF;

    -- Read the admin's `max_message_length`, defaulting to 2000 and
    -- clamping to the absolute ceiling so a misconfigured admin value
    -- still leaves the CHECK constraint as a backstop.
    soft_limit := public.get_instance_config_int('max_message_length', 2000, 50000);

    text_len := public.jsonb_text_content_length(NEW.content);
    IF text_len > soft_limit THEN
        RAISE EXCEPTION 'Message text exceeds the instance limit of % characters (got %)', soft_limit, text_len
            USING ERRCODE = 'check_violation',
                  HINT = 'Trim the message or ask an instance admin to raise max_message_length in Chat Settings.';
    END IF;

    RETURN NEW;
END;
$$;

-- Same idea for posts: enforce `max_post_length` from instance_config.
CREATE OR REPLACE FUNCTION public.enforce_post_length()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
    soft_limit integer;
    text_len integer;
BEGIN
    soft_limit := public.get_instance_config_int('max_post_length', 500, 50000);

    text_len := public.jsonb_text_content_length(NEW.content);
    IF text_len > soft_limit THEN
        RAISE EXCEPTION 'Post text exceeds the instance limit of % characters (got %)', soft_limit, text_len
            USING ERRCODE = 'check_violation',
                  HINT = 'Trim the post or ask an instance admin to raise max_post_length.';
    END IF;

    RETURN NEW;
END;
$$;

-- Apply the triggers + the backstop CHECK constraints.
DO $$
BEGIN
    -- Drop any earlier CHECK constraint that used the (now obsolete)
    -- 5000 / 10000 ceilings so we can re-create with the new 50000
    -- absolute safety net. Stripping whitespace before matching
    -- normalises PostgreSQL's canonical formatting.
    IF EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_class r ON r.oid = c.conrelid
        WHERE c.conname = 'messages_text_length_check'
          AND r.relname = 'messages'
          AND regexp_replace(pg_get_constraintdef(c.oid), '\s+', '', 'g') ~ '<=\s*(?:5000|10000)\)'
    ) THEN
        ALTER TABLE public.messages DROP CONSTRAINT messages_text_length_check;
    END IF;

    IF EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_class r ON r.oid = c.conrelid
        WHERE c.conname = 'posts_text_length_check'
          AND r.relname = 'posts'
          AND regexp_replace(pg_get_constraintdef(c.oid), '\s+', '', 'g') ~ '<=\s*(?:5000|10000)\)'
    ) THEN
        ALTER TABLE public.posts DROP CONSTRAINT posts_text_length_check;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'messages_text_length_check' AND conrelid = 'public.messages'::regclass
    ) THEN
        ALTER TABLE public.messages
            ADD CONSTRAINT messages_text_length_check
            CHECK (
                encrypted IS TRUE
                OR is_system IS TRUE
                OR public.jsonb_text_content_length(content) <= 50000
            );
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'posts_text_length_check' AND conrelid = 'public.posts'::regclass
    ) THEN
        ALTER TABLE public.posts
            ADD CONSTRAINT posts_text_length_check
            CHECK (public.jsonb_text_content_length(content) <= 50000);
    END IF;
END $$;

DROP TRIGGER IF EXISTS trg_enforce_message_length ON public.messages;
CREATE TRIGGER trg_enforce_message_length
    BEFORE INSERT OR UPDATE OF content, encrypted, is_system ON public.messages
    FOR EACH ROW
    EXECUTE FUNCTION public.enforce_message_length();

DROP TRIGGER IF EXISTS trg_enforce_post_length ON public.posts;
CREATE TRIGGER trg_enforce_post_length
    BEFORE INSERT OR UPDATE OF content ON public.posts
    FOR EACH ROW
    EXECUTE FUNCTION public.enforce_post_length();

DO $$
BEGIN
    RAISE NOTICE 'Core functions created successfully';
END $$;


-- ==== 11_functions_triggers.sql ====
-- =============================================================================
-- Harmony Database Schema - Trigger Functions
-- =============================================================================
-- Functions that are called by triggers (RETURNS trigger)
-- =============================================================================

-- ---------------------------------------------------------------------------
-- PROFILE TRIGGERS
-- ---------------------------------------------------------------------------

-- Strips spoofing-vector characters (bidi overrides/isolates, zero-width &
-- invisible format chars, C0/C1 control chars), NFC-normalizes, trims, and
-- clamps to a max length. Shared by the profile sanitize trigger and the
-- hardening migration so local + federated writes are cleaned identically.
CREATE OR REPLACE FUNCTION public.sanitize_profile_string(
    p_input text,
    p_max integer,
    p_allow_newlines boolean DEFAULT false
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
    SELECT CASE
        WHEN p_input IS NULL THEN NULL
        ELSE left(
            btrim(
                regexp_replace(
                    normalize(p_input, NFC),
                    CASE WHEN p_allow_newlines
                        -- keep TAB (U+0009) and LF (U+000A); strip the rest
                        THEN U&'[\0001-\0008\000B-\001F\007F-\009F\200B-\200F\202A-\202E\2060-\206F\FEFF]'
                        ELSE U&'[\0001-\001F\007F-\009F\200B-\200F\202A-\202E\2060-\206F\FEFF]'
                    END,
                    '',
                    'g'
                )
            ),
            p_max
        )
    END;
$$;

-- Sanitize user-controlled profile text on EVERY write. Local signup, profile
-- edits via Supabase REST/RLS, and federated actor upserts all pass through
-- this BEFORE trigger, so it is the authoritative guard regardless of client.
CREATE OR REPLACE FUNCTION public.sanitize_profile_text()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    -- display_name: single line, max 80; emptied -> NULL (keeps the
    -- profiles_display_name_not_blank constraint satisfied).
    IF NEW.display_name IS NOT NULL THEN
        NEW.display_name := NULLIF(public.sanitize_profile_string(NEW.display_name, 80, false), '');
    END IF;

    -- bio: line breaks allowed, max 500.
    IF NEW.bio IS NOT NULL THEN
        NEW.bio := NULLIF(public.sanitize_profile_string(NEW.bio, 500, true), '');
    END IF;

    -- profile_fields: at most 4 entries, name/value clamped to 255 each.
    IF NEW.profile_fields IS NOT NULL AND jsonb_typeof(NEW.profile_fields) = 'array' THEN
        NEW.profile_fields := COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'name',  COALESCE(public.sanitize_profile_string(elem->>'name', 255, false), ''),
                'value', COALESCE(public.sanitize_profile_string(elem->>'value', 255, false), '')
            ))
            FROM (
                SELECT elem
                FROM jsonb_array_elements(NEW.profile_fields) WITH ORDINALITY AS t(elem, ord)
                WHERE ord <= 4
            ) s
        ), '[]'::jsonb);
    END IF;

    -- custom_status: clamp the free-text fields, preserve structural keys.
    IF NEW.custom_status IS NOT NULL AND jsonb_typeof(NEW.custom_status) = 'object' THEN
        NEW.custom_status := NEW.custom_status || jsonb_strip_nulls(jsonb_build_object(
            'text',    public.sanitize_profile_string(NEW.custom_status->>'text', 128, false),
            'emoji',   public.sanitize_profile_string(NEW.custom_status->>'emoji', 64, false),
            'details', public.sanitize_profile_string(NEW.custom_status->>'details', 128, false),
            'state',   public.sanitize_profile_string(NEW.custom_status->>'state', 128, false)
        ));
    END IF;

    RETURN NEW;
END;
$$;

-- ---------------------------------------------------------------------------
-- GENERIC USER-INPUT TEXT SANITIZATION (servers/channels/roles/etc.)
-- ---------------------------------------------------------------------------
-- RLS lets any token-holder INSERT/UPDATE their own rows via the REST API, and
-- SECURITY DEFINER RPCs (create_thread, update_group_name, ban/kick, ...) also
-- write these tables. BEFORE INSERT/UPDATE triggers fire on EVERY write path,
-- so they are the authoritative guard against over-long / blank / spoofing
-- (bidi-override, zero-width, control char) text submitted past the UI.
--
-- All helpers below clamp + strip via public.sanitize_profile_string().

-- Generic single-line `name` column sanitizer.
-- TG_ARGV[0] = max length (default 100); TG_ARGV[1] = 'required' | 'optional'.
-- For required names, a blank value is rejected on INSERT (and on UPDATE when a
-- previously non-blank name is being blanked); pre-existing blank rows stay
-- editable. For optional names, blank collapses to NULL.
CREATE OR REPLACE FUNCTION public.sanitize_entity_name()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    v_max int := COALESCE(NULLIF(TG_ARGV[0], '')::int, 100);
    v_required boolean := (TG_ARGV[1] = 'required');
    v_clean text;
BEGIN
    v_clean := public.sanitize_profile_string(NEW.name, v_max, false);

    IF COALESCE(v_clean, '') = '' THEN
        IF v_required THEN
            IF TG_OP = 'INSERT' OR COALESCE(OLD.name, '') <> '' THEN
                RAISE EXCEPTION '% name must not be blank', TG_TABLE_NAME
                    USING ERRCODE = 'check_violation';
            END IF;
            NEW.name := COALESCE(v_clean, '');
        ELSE
            NEW.name := NULLIF(v_clean, '');
        END IF;
    ELSE
        NEW.name := v_clean;
    END IF;

    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.sanitize_server_text()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    v_name text := public.sanitize_profile_string(NEW.name, 100, false);
BEGIN
    IF COALESCE(v_name, '') = '' THEN
        IF TG_OP = 'INSERT' OR COALESCE(OLD.name, '') <> '' THEN
            RAISE EXCEPTION 'server name must not be blank' USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    NEW.name := COALESCE(v_name, '');

    IF NEW.description IS NOT NULL THEN
        NEW.description := NULLIF(public.sanitize_profile_string(NEW.description, 500, true), '');
    END IF;

    RETURN NEW;
END;
$$;

-- ---------------------------------------------------------------------------
-- SERVER HANDLE (slug) for WebFinger/federation discovery
-- ---------------------------------------------------------------------------
-- Turn a display name into a slug-safe base, or NULL when nothing usable
-- remains (e.g. an all-CJK name) so callers fall back to the id prefix.
CREATE OR REPLACE FUNCTION public.slugify_server_name(p_name text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_temp
AS $$
    SELECT NULLIF(
        regexp_replace(
            regexp_replace(lower(coalesce(p_name, '')), '[^a-z0-9]+', '-', 'g'),
            '(^-+|-+$)', '', 'g'
        ),
    '');
$$;

-- Produce a slug for a local server that is unique AMONG LOCAL SERVERS. Users
-- and servers are separate actor types (Person vs Group): they're allowed to
-- share a handle, and WebFinger disambiguates by AS type (Lemmy-style). So this
-- only needs to dodge other server slugs, not usernames.
CREATE OR REPLACE FUNCTION public.generate_unique_server_slug(p_name text, p_id uuid)
RETURNS text
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
    base text;
    candidate text;
    n integer := 0;
BEGIN
    base := left(coalesce(public.slugify_server_name(p_name), left(p_id::text, 8)), 60);
    candidate := base;
    WHILE EXISTS (
        SELECT 1 FROM public.servers s
        WHERE s.is_local_server = true
          AND lower(s.slug) = lower(candidate)
          AND s.id <> p_id
    ) LOOP
        n := n + 1;
        candidate := base || '-' || n;
    END LOOP;
    RETURN candidate;
END;
$$;

-- BEFORE INSERT: auto-assign a handle to local servers that don't supply one.
CREATE OR REPLACE FUNCTION public.assign_server_slug()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
    IF NEW.is_local_server IS DISTINCT FROM true THEN
        RETURN NEW; -- remote servers keep NULL
    END IF;
    IF NEW.slug IS NOT NULL AND NEW.slug <> '' THEN
        RETURN NEW; -- explicit slug respected (format enforced by constraint)
    END IF;
    NEW.slug := public.generate_unique_server_slug(NEW.name, NEW.id);
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.sanitize_channel_text()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    v_name text := public.sanitize_profile_string(NEW.name, 100, false);
BEGIN
    IF COALESCE(v_name, '') = '' THEN
        IF TG_OP = 'INSERT' OR COALESCE(OLD.name, '') <> '' THEN
            RAISE EXCEPTION 'channel name must not be blank' USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    NEW.name := COALESCE(v_name, '');

    IF NEW.description IS NOT NULL THEN
        NEW.description := NULLIF(public.sanitize_profile_string(NEW.description, 1024, true), '');
    END IF;

    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.sanitize_bot_text()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    -- username keeps its own valid_username CHECK (charset + 3..32); don't touch.
    IF NEW.display_name IS NOT NULL THEN
        NEW.display_name := NULLIF(public.sanitize_profile_string(NEW.display_name, 100, false), '');
    END IF;
    IF NEW.bio IS NOT NULL THEN
        NEW.bio := NULLIF(public.sanitize_profile_string(NEW.bio, 500, true), '');
    END IF;
    IF NEW.website_url IS NOT NULL THEN
        NEW.website_url := NULLIF(public.sanitize_profile_string(NEW.website_url, 512, false), '');
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.sanitize_report_text()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.reason IS NOT NULL THEN
        NEW.reason := public.sanitize_profile_string(NEW.reason, 200, false);
    END IF;
    IF NEW.comment IS NOT NULL THEN
        NEW.comment := NULLIF(public.sanitize_profile_string(NEW.comment, 1000, true), '');
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.sanitize_user_list_text()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    v_title text := public.sanitize_profile_string(NEW.title, 100, false);
BEGIN
    IF COALESCE(v_title, '') = '' THEN
        IF TG_OP = 'INSERT' OR COALESCE(OLD.title, '') <> '' THEN
            RAISE EXCEPTION 'list title must not be blank' USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    NEW.title := COALESCE(v_title, '');

    IF NEW.description IS NOT NULL THEN
        NEW.description := NULLIF(public.sanitize_profile_string(NEW.description, 500, true), '');
    END IF;

    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.sanitize_member_nickname()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.nickname IS NOT NULL THEN
        NEW.nickname := NULLIF(public.sanitize_profile_string(NEW.nickname, 64, false), '');
    END IF;
    RETURN NEW;
END;
$$;

-- posts.content_warning is federated (Mastodon CW/summary). Clamp rather than
-- reject so an over-long remote CW never blocks ingestion of an otherwise-valid
-- post; the CHECK backstop only guarantees the clamp held.
CREATE OR REPLACE FUNCTION public.sanitize_post_text()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.content_warning IS NOT NULL THEN
        NEW.content_warning := NULLIF(public.sanitize_profile_string(NEW.content_warning, 200, false), '');
    END IF;
    RETURN NEW;
END;
$$;

-- Promote first local user to instance admin
CREATE OR REPLACE FUNCTION public.promote_first_user_to_admin()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
BEGIN
    IF NEW.is_local = true OR NEW.is_local IS NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM public.profiles
            WHERE is_local = true AND id != NEW.id
        ) THEN
            NEW.is_admin := true;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.promote_first_user_to_admin() IS 
'Sets is_admin=true on the first local profile created on the instance.';

-- Create notification preferences on new profile
CREATE OR REPLACE FUNCTION public.create_notification_preferences()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    IF NEW.is_local = true OR NEW.is_local IS NULL THEN
        INSERT INTO notification_preferences (user_id)
        VALUES (NEW.id)
        ON CONFLICT (user_id) DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.create_notification_preferences() IS 
'Creates notification preferences only for local users.';

-- ---------------------------------------------------------------------------
-- SERVER LIMIT ENFORCEMENT
-- ---------------------------------------------------------------------------

-- Check channel limit before insert (max 100 channels per server)
CREATE OR REPLACE FUNCTION public.check_channel_limit()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  channel_count INTEGER;
  max_channels CONSTANT INTEGER := 100;
BEGIN
  -- Count existing channels for this server
  SELECT COUNT(*) INTO channel_count
  FROM channels
  WHERE server_id = NEW.server_id;
  
  -- Check if limit would be exceeded
  IF channel_count >= max_channels THEN
    RAISE EXCEPTION 'Channel limit exceeded: Maximum % channels per server', max_channels
      USING ERRCODE = 'check_violation';
  END IF;
  
  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.check_channel_limit() IS 
'Enforces maximum 100 channels per server';

-- Check category limit before insert (max 25 categories per server)
CREATE OR REPLACE FUNCTION public.check_category_limit()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  category_count INTEGER;
  max_categories CONSTANT INTEGER := 25;
BEGIN
  -- Count existing categories for this server
  SELECT COUNT(*) INTO category_count
  FROM channel_categories
  WHERE server_id = NEW.server_id;
  
  -- Check if limit would be exceeded
  IF category_count >= max_categories THEN
    RAISE EXCEPTION 'Category limit exceeded: Maximum % categories per server', max_categories
      USING ERRCODE = 'check_violation';
  END IF;
  
  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.check_category_limit() IS 
'Enforces maximum 25 categories per server';

-- ---------------------------------------------------------------------------
-- SERVER TRIGGERS
-- ---------------------------------------------------------------------------

-- Create default @everyone role for new server
CREATE OR REPLACE FUNCTION public.create_default_server_role()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
    everyone_role_id uuid;
    admin_role_id uuid;
BEGIN
    -- Create @everyone role (default for all members)
    INSERT INTO server_roles (
        server_id,
        name,
        color,
        position,
        is_default,
        is_admin,
        permissions
    ) VALUES (
        NEW.id,
        'everyone',
        '#99AAB5',
        0,
        true,
        false,
        122646786  -- Default permissions: VIEW_CHANNEL, CREATE_INVITE, SEND_MESSAGES, SEND_MESSAGES_IN_THREADS, CREATE_PUBLIC_THREADS, EMBED_LINKS, ATTACH_FILES, ADD_REACTIONS, USE_EXTERNAL_EMOJIS, READ_MESSAGE_HISTORY, CONNECT, SPEAK, STREAM
    ) RETURNING id INTO everyone_role_id;
    
    -- Create Admin role for the owner (highest position, all permissions)
    INSERT INTO server_roles (
        server_id,
        name,
        color,
        position,
        is_default,
        is_admin,
        permissions
    ) VALUES (
        NEW.id,
        'Admin',
        '#e74c3c',  -- Red color for admin
        999,        -- High position (owner is always above)
        false,
        true,       -- Mark as admin role
        2199023255551  -- All permissions (ADMINISTRATOR)
    ) RETURNING id INTO admin_role_id;
    
    -- Assign the Admin role to the server owner
    INSERT INTO user_roles (user_id, role_id, server_id)
    VALUES (NEW.owner, admin_role_id, NEW.id)
    ON CONFLICT (user_id, role_id) DO NOTHING;
    
    RETURN NEW;
END;
$$;

-- Helper: create default server structure (categories, channels)
CREATE OR REPLACE FUNCTION public.create_default_server_structure(p_server_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
    v_text_category_id uuid;
    v_voice_category_id uuid;
BEGIN
    INSERT INTO public.channel_categories (server_id, name, "order")
    VALUES (p_server_id, 'Text Channels', 0)
    RETURNING id INTO v_text_category_id;

    INSERT INTO public.channels (server_id, name, type, category, "order")
    VALUES (p_server_id, 'general', 0, v_text_category_id, 0);

    INSERT INTO public.channel_categories (server_id, name, "order")
    VALUES (p_server_id, 'Voice Channels', 1)
    RETURNING id INTO v_voice_category_id;

    INSERT INTO public.channels (server_id, name, type, category, "order")
    VALUES (p_server_id, 'voice chat', 1, v_voice_category_id, 0);
END;
$$;

-- Create default server structure trigger (only for local servers)
CREATE OR REPLACE FUNCTION public.trigger_create_default_server_structure()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
BEGIN
    IF NEW.is_local_server = true THEN
        PERFORM public.create_default_server_structure(NEW.id);
    END IF;
    RETURN NEW;
END;
$$;

-- Assign default role to new server member
CREATE OR REPLACE FUNCTION public.assign_default_role_to_member()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    default_role_id uuid;
BEGIN
    IF NEW.status = 'accepted' THEN
        SELECT id INTO default_role_id
        FROM server_roles
        WHERE server_id = NEW.server_id AND is_default = true
        LIMIT 1;
        
        IF default_role_id IS NOT NULL THEN
            INSERT INTO user_roles (user_id, role_id, server_id)
            VALUES (NEW.user_id, default_role_id, NEW.server_id)
            ON CONFLICT (user_id, role_id) DO NOTHING;
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$;

-- Set member instance from profile domain
CREATE OR REPLACE FUNCTION public.set_member_instance()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    SELECT domain INTO NEW.member_instance
    FROM profiles
    WHERE id = NEW.user_id;
    
    RETURN NEW;
END;
$$;

-- Prevent deletion of protected roles (allows cascade when server is deleted)
CREATE OR REPLACE FUNCTION public.prevent_protected_role_deletion()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM servers WHERE id = OLD.server_id) THEN
        RETURN OLD;
    END IF;

    IF OLD.is_admin = true THEN
        RAISE EXCEPTION 'Cannot delete the Admin role. This role is protected.';
    END IF;

    IF OLD.is_default = true THEN
        RAISE EXCEPTION 'Cannot delete the @everyone role. This role is protected.';
    END IF;

    RETURN OLD;
END;
$$;

-- ---------------------------------------------------------------------------
-- TIMELINE TRIGGERS
-- ---------------------------------------------------------------------------

-- Add posts to timeline when created (optimized: bulk INSERT ... SELECT instead of loops)
CREATE OR REPLACE FUNCTION public.create_comprehensive_timeline_entries()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
BEGIN
    IF COALESCE(NEW.is_deleted, false) THEN
        RETURN NEW;
    END IF;
    
    -- Add to author's own home timeline (local authors only)
    IF NEW.is_local THEN
        INSERT INTO timeline_entries (user_id, post_id, timeline_type, position)
        VALUES (NEW.author_id, NEW.id, 'home', EXTRACT(epoch FROM NEW.created_at) * 1000000)
        ON CONFLICT (user_id, post_id, timeline_type) DO NOTHING;
    END IF;
    
    -- Add to followers' home timelines based on visibility (bulk)
    IF NEW.visibility = 'public' THEN
        INSERT INTO timeline_entries (user_id, post_id, timeline_type, position)
        SELECT f.follower_id, NEW.id, 'home', EXTRACT(epoch FROM NEW.created_at) * 1000000
        FROM follows f
        JOIN profiles p ON f.follower_id = p.id
        WHERE f.following_id = NEW.author_id
          AND f.status IN ('accepted', 'pending')
          AND p.is_local = true
          AND f.follower_id != NEW.author_id
        ON CONFLICT (user_id, post_id, timeline_type) DO NOTHING;
    ELSIF NEW.visibility IN ('unlisted', 'followers') THEN
        INSERT INTO timeline_entries (user_id, post_id, timeline_type, position)
        SELECT f.follower_id, NEW.id, 'home', EXTRACT(epoch FROM NEW.created_at) * 1000000
        FROM follows f
        JOIN profiles p ON f.follower_id = p.id
        WHERE f.following_id = NEW.author_id
          AND f.status = 'accepted'
          AND p.is_local = true
          AND f.follower_id != NEW.author_id
        ON CONFLICT (user_id, post_id, timeline_type) DO NOTHING;
    END IF;
    
    -- Add public posts to public timeline for all local users (bulk)
    IF NEW.visibility = 'public' THEN
        INSERT INTO timeline_entries (user_id, post_id, timeline_type, position)
        SELECT p.id, NEW.id, 'public', EXTRACT(epoch FROM NEW.created_at) * 1000000
        FROM profiles p
        WHERE p.is_local = true
        ON CONFLICT (user_id, post_id, timeline_type) DO NOTHING;
    END IF;
    
    RETURN NEW;
END;
$$;

-- Add existing posts to new follower's timeline (optimized: bulk INSERT ... SELECT)
CREATE OR REPLACE FUNCTION public.add_existing_posts_to_new_follower_timeline()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
BEGIN
    IF NEW.status = 'pending' THEN
        INSERT INTO timeline_entries (user_id, post_id, timeline_type, position)
        SELECT NEW.follower_id, sub.id, 'home', EXTRACT(epoch FROM sub.created_at) * 1000000
        FROM (
            SELECT p.id, p.created_at
            FROM posts p
            WHERE p.author_id = NEW.following_id
              AND p.visibility = 'public'
              AND NOT COALESCE(p.is_deleted, false)
              AND p.created_at > NOW() - INTERVAL '7 days'
            ORDER BY p.created_at DESC
            LIMIT 50
        ) sub
        ON CONFLICT (user_id, post_id, timeline_type) DO NOTHING;
    ELSIF NEW.status = 'accepted' THEN
        INSERT INTO timeline_entries (user_id, post_id, timeline_type, position)
        SELECT NEW.follower_id, sub.id, 'home', EXTRACT(epoch FROM sub.created_at) * 1000000
        FROM (
            SELECT p.id, p.created_at
            FROM posts p
            WHERE p.author_id = NEW.following_id
              AND p.visibility IN ('public', 'unlisted')
              AND NOT COALESCE(p.is_deleted, false)
              AND p.created_at > NOW() - INTERVAL '7 days'
            ORDER BY p.created_at DESC
            LIMIT 50
        ) sub
        ON CONFLICT (user_id, post_id, timeline_type) DO NOTHING;
    END IF;
    
    RETURN NEW;
END;
$$;

-- Backfill timeline on follow acceptance (optimized: bulk INSERT ... SELECT)
CREATE OR REPLACE FUNCTION public.backfill_timeline_on_follow()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
BEGIN
    -- Only for local followers
    IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = NEW.follower_id AND is_local = true) THEN
        RETURN NEW;
    END IF;
    
    -- When follow becomes accepted, add unlisted posts
    IF TG_OP = 'UPDATE' AND OLD.status = 'pending' AND NEW.status = 'accepted' THEN
        INSERT INTO timeline_entries (user_id, post_id, timeline_type, position)
        SELECT NEW.follower_id, sub.id, 'home', EXTRACT(epoch FROM sub.created_at) * 1000000
        FROM (
            SELECT p.id, p.created_at
            FROM posts p
            WHERE p.author_id = NEW.following_id
              AND p.visibility = 'unlisted'
              AND NOT COALESCE(p.is_deleted, false)
              AND p.created_at > NOW() - INTERVAL '7 days'
            ORDER BY p.created_at DESC
            LIMIT 50
        ) sub
        ON CONFLICT (user_id, post_id, timeline_type) DO NOTHING;
    END IF;
    
    RETURN NEW;
END;
$$;

-- Remove timeline entries on unfollow
CREATE OR REPLACE FUNCTION public.remove_timeline_on_unfollow()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    DELETE FROM timeline_entries
    WHERE user_id = OLD.follower_id
      AND post_id IN (SELECT id FROM posts WHERE author_id = OLD.following_id)
      AND timeline_type = 'home';
    
    RETURN OLD;
END;
$$;

-- Maintain denormalized followers_count / following_count on profiles.
-- Only follows with status = 'accepted' contribute (Mastodon / Pleroma /
-- GoToSocial all do this).
CREATE OR REPLACE FUNCTION public.update_follow_counts()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_was_accepted boolean := false;
  v_is_accepted  boolean := false;
BEGIN
  -- follows.status is nullable and its CHECK admits NULL, so `status =
  -- 'accepted'` yields NULL rather than false. COALESCE keeps both flags
  -- two-valued. Without it NULL reaches the branch test below: an INSERT
  -- carrying a NULL status decrements both profiles, and an UPDATE from
  -- 'accepted' to NULL leaves the counts untouched.
  IF TG_OP = 'INSERT' THEN
    v_is_accepted  := COALESCE(NEW.status = 'accepted', false);
  ELSIF TG_OP = 'UPDATE' THEN
    v_was_accepted := COALESCE(OLD.status = 'accepted', false);
    v_is_accepted  := COALESCE(NEW.status = 'accepted', false);
  ELSE -- DELETE
    v_was_accepted := COALESCE(OLD.status = 'accepted', false);
  END IF;

  IF v_was_accepted = v_is_accepted THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF v_is_accepted THEN
    UPDATE public.profiles
       SET following_count = COALESCE(following_count, 0) + 1
     WHERE id = NEW.follower_id;
    UPDATE public.profiles
       SET followers_count = COALESCE(followers_count, 0) + 1
     WHERE id = NEW.following_id;
  ELSE
    -- (follower_id, following_id) is the natural key on public.follows and
    -- never moves on UPDATE, so NEW and OLD agree wherever both exist; the
    -- COALESCE covers DELETE, where NEW is NULL.
    UPDATE public.profiles
       SET following_count = GREATEST(COALESCE(following_count, 0) - 1, 0)
     WHERE id = COALESCE(NEW.follower_id, OLD.follower_id);
    UPDATE public.profiles
       SET followers_count = GREATEST(COALESCE(followers_count, 0) - 1, 0)
     WHERE id = COALESCE(NEW.following_id, OLD.following_id);
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;

-- ---------------------------------------------------------------------------
-- POST TRIGGERS
-- ---------------------------------------------------------------------------

-- Handle post soft delete
CREATE OR REPLACE FUNCTION public.handle_post_soft_delete()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    IF NEW.is_deleted = true AND (OLD.is_deleted = false OR OLD.is_deleted IS NULL) THEN
        -- Remove from all timelines
        DELETE FROM timeline_entries WHERE post_id = NEW.id;
    END IF;
    
    RETURN NEW;
END;
$$;

-- Cascade delete reblogs when original is deleted
CREATE OR REPLACE FUNCTION public.cascade_delete_reblogs()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    -- Mark reblogs as deleted too
    UPDATE posts
    SET is_deleted = true, deleted_at = NOW()
    WHERE (reblog->>'id')::uuid = NEW.id
      AND (is_deleted = false OR is_deleted IS NULL);
    
    RETURN NEW;
END;
$$;

-- Extract hashtags from JSONB content - handles both MessagePart format and #text
CREATE OR REPLACE FUNCTION public.extract_hashtags_from_content(p_content jsonb)
RETURNS text[]
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  hashtags TEXT[] := ARRAY[]::TEXT[];
  item JSONB;
  text_content TEXT;
  hashtag_text TEXT;
  match_record RECORD;
  result TEXT[];
BEGIN
  IF p_content IS NULL OR jsonb_typeof(p_content) != 'array' THEN
    RETURN ARRAY[]::TEXT[];
  END IF;

  FOR item IN SELECT * FROM jsonb_array_elements(p_content)
  LOOP
    IF item->>'type' = 'hashtag' THEN
      hashtag_text := COALESCE(
        item->>'name',
        item->>'hashtag',
        item->>'normalized'
      );
      IF hashtag_text IS NOT NULL AND hashtag_text != '' THEN
        hashtag_text := regexp_replace(hashtag_text, '^#', '');
        hashtags := array_append(hashtags, lower(hashtag_text));
      END IF;
    ELSIF item->>'type' = 'text' THEN
      text_content := item->>'text';
      IF text_content IS NOT NULL THEN
        FOR match_record IN SELECT (regexp_matches(text_content, '#([a-zA-Z0-9_]+)', 'g'))[1] as tag
        LOOP
          IF match_record.tag IS NOT NULL THEN
            hashtags := array_append(hashtags, lower(match_record.tag));
          END IF;
        END LOOP;
      END IF;
    END IF;
  END LOOP;

  SELECT COALESCE(array_agg(DISTINCT t), ARRAY[]::TEXT[])
  INTO result
  FROM unnest(hashtags) t
  WHERE t IS NOT NULL;

  RETURN COALESCE(result, ARRAY[]::TEXT[]);
END;
$$;

COMMENT ON FUNCTION public.extract_hashtags_from_content(jsonb) IS
'Extract hashtags from JSONB content array. Handles both hashtag-type MessageParts and #text patterns.';

-- Insert or update hashtag, return ID
CREATE OR REPLACE FUNCTION public.upsert_hashtag(p_tag text)
RETURNS uuid
LANGUAGE plpgsql
AS $$
DECLARE
  v_hashtag_id uuid;
  v_normalized_tag text;
BEGIN
  v_normalized_tag := lower(trim(regexp_replace(p_tag, '^#', '')));

  SELECT id INTO v_hashtag_id
  FROM public.hashtags
  WHERE normalized_tag = v_normalized_tag;

  IF v_hashtag_id IS NULL THEN
    INSERT INTO public.hashtags (tag, normalized_tag, total_uses, daily_uses, first_used_at, last_used_at)
    VALUES (v_normalized_tag, v_normalized_tag, 1, 1, NOW(), NOW())
    ON CONFLICT (normalized_tag) DO UPDATE
    SET
      total_uses = hashtags.total_uses + 1,
      daily_uses = COALESCE(hashtags.daily_uses, 0) + 1,
      last_used_at = NOW()
    RETURNING id INTO v_hashtag_id;
  ELSE
    UPDATE public.hashtags
    SET
      total_uses = total_uses + 1,
      daily_uses = COALESCE(daily_uses, 0) + 1,
      last_used_at = NOW()
    WHERE id = v_hashtag_id;
  END IF;

  RETURN v_hashtag_id;
END;
$$;

COMMENT ON FUNCTION public.upsert_hashtag(text) IS
'Insert or update a hashtag and return its ID. Updates usage counts on conflict.';

-- Process post content to extract and link hashtags
CREATE OR REPLACE FUNCTION public.process_post_hashtags(p_post_id uuid, p_content jsonb)
RETURNS integer
LANGUAGE plpgsql
AS $$
DECLARE
    v_hashtag_array TEXT[];
    v_hashtag_text TEXT;
    v_hashtag_id UUID;
    v_position_counter INTEGER := 0;
    v_processed_count INTEGER := 0;
BEGIN
    v_hashtag_array := public.extract_hashtags_from_content(p_content);

    IF v_hashtag_array IS NULL THEN
        v_hashtag_array := ARRAY[]::TEXT[];
    END IF;

    IF array_length(v_hashtag_array, 1) IS NULL OR array_length(v_hashtag_array, 1) = 0 THEN
        RETURN 0;
    END IF;

    FOREACH v_hashtag_text IN ARRAY v_hashtag_array LOOP
        v_position_counter := v_position_counter + 1;
        v_hashtag_id := public.upsert_hashtag(v_hashtag_text);

        INSERT INTO public.post_hashtags (post_id, hashtag_id, position_in_content)
        VALUES (p_post_id, v_hashtag_id, v_position_counter)
        ON CONFLICT (post_id, hashtag_id) DO NOTHING;

        v_processed_count := v_processed_count + 1;
    END LOOP;

    RETURN v_processed_count;
END;
$$;

COMMENT ON FUNCTION public.process_post_hashtags(uuid, jsonb) IS
'Process post content to extract and link hashtags. Returns count of hashtags processed.';

-- Extract hashtags from post content (trigger - delegates to process_post_hashtags)
CREATE OR REPLACE FUNCTION public.trigger_extract_post_hashtags()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
BEGIN
  IF NEW.content IS NOT NULL AND jsonb_typeof(NEW.content) = 'array' THEN
    PERFORM public.process_post_hashtags(NEW.id, NEW.content);
  END IF;

  RETURN NEW;
END;
$$;

-- ---------------------------------------------------------------------------
-- REACTION TRIGGERS
-- ---------------------------------------------------------------------------

-- Update favorites_count / reblogs_count on post_interactions insert/delete
-- favorites_count only. reblogs_count is maintained by
-- update_post_reblog_count from posts.metadata->>'reblog_of', which is where a
-- reblog actually lives: activityPubService.ts inserts a posts row and writes no
-- post_interactions row, so counting here missed every local reblog. Incoming
-- federated Announces write both, so counting in both places double-counted
-- them.
-- SECURITY DEFINER because the trigger writes a row the caller does not own. Under invoker
-- rights the UPDATE runs as `authenticated`, posts_update_own filters it to
-- author_id = get_current_profile_id(), and favouriting someone else's post matches zero
-- rows and reports success - the interaction commits, the counter does not move. The
-- federation backend connects as service_role and bypasses RLS, which is why remote
-- engagement counted and local engagement did not.
CREATE OR REPLACE FUNCTION public.update_post_reaction_counts()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions', 'pg_temp'
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.interaction_type = 'emoji_reaction' OR NEW.interaction_type = 'favorite' THEN
      UPDATE posts
      SET favorites_count = favorites_count + 1
      WHERE id = NEW.post_id;
    END IF;
    RETURN NEW;

  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.interaction_type = 'emoji_reaction' OR OLD.interaction_type = 'favorite' THEN
      UPDATE posts
      SET favorites_count = GREATEST(favorites_count - 1, 0)
      WHERE id = OLD.post_id;
    END IF;
    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$$;

-- Maintain posts.replies_count: covers reply insert, in_reply_to moving to,
-- away from or between parents, soft-delete flips and hard deletes.
-- LOCAL parents recompute from actual rows (authoritative, drift-proof);
-- REMOTE parents apply +1/-1 on top of the origin-supplied baseline.
-- A re-parent touches two parents at once, which is why the arms below carry a
-- list rather than one id.
-- SECURITY DEFINER for the same reason as update_post_reaction_counts: the parent post
-- belongs to someone else, and posts_update_own would filter the write to nothing.
CREATE OR REPLACE FUNCTION public.update_post_reply_count()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions', 'pg_temp'
AS $$
DECLARE
  affected uuid[] := '{}';
  deltas integer[] := '{}';
  parent record;
  parent_is_local boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.in_reply_to IS NOT NULL AND (NEW.is_deleted IS DISTINCT FROM true) THEN
      affected := ARRAY[NEW.in_reply_to];
      deltas := ARRAY[1];
    END IF;

  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.in_reply_to IS DISTINCT FROM NEW.in_reply_to THEN
      -- Covers NULL -> parent (federation resolving in_reply_to late),
      -- parent -> NULL, and parent -> different parent.
      IF OLD.in_reply_to IS NOT NULL AND (OLD.is_deleted IS DISTINCT FROM true) THEN
        affected := affected || OLD.in_reply_to;
        deltas := deltas || -1;
      END IF;
      IF NEW.in_reply_to IS NOT NULL AND (NEW.is_deleted IS DISTINCT FROM true) THEN
        affected := affected || NEW.in_reply_to;
        deltas := deltas || 1;
      END IF;
    ELSIF NEW.in_reply_to IS NOT NULL AND OLD.is_deleted IS DISTINCT FROM NEW.is_deleted THEN
      affected := ARRAY[NEW.in_reply_to];
      deltas := ARRAY[CASE WHEN NEW.is_deleted IS TRUE THEN -1 ELSE 1 END];
    END IF;

  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.in_reply_to IS NOT NULL AND (OLD.is_deleted IS DISTINCT FROM true) THEN
      affected := ARRAY[OLD.in_reply_to];
      deltas := ARRAY[-1];
    END IF;
  END IF;

  -- Ascending id: a re-parent locks two rows, and two moves in opposite
  -- directions take them in the same order.
  FOR parent IN
    SELECT x.id, x.delta FROM unnest(affected, deltas) AS x(id, delta) ORDER BY x.id
  LOOP
    -- Lock the parent first so the recompute below takes its snapshot AFTER any
    -- concurrent sibling reply commits (READ COMMITTED would otherwise let the
    -- count subquery miss a just-inserted row and undercount).
    SELECT is_local INTO parent_is_local
    FROM public.posts WHERE id = parent.id FOR UPDATE;

    IF parent_is_local IS TRUE THEN
      UPDATE public.posts p
      SET replies_count = (
        SELECT count(*) FROM public.posts c
        WHERE c.in_reply_to = parent.id AND c.is_deleted IS DISTINCT FROM true
      )
      WHERE p.id = parent.id;
    ELSE
      UPDATE public.posts
      SET replies_count = GREATEST(COALESCE(replies_count, 0) + parent.delta, 0)
      WHERE id = parent.id;
    END IF;
  END LOOP;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;

-- Maintain profiles.posts_count for LOCAL authors.
-- Counts every non-deleted row in posts, replies and boosts included: the same
-- population the ActivityPub outbox collection reports as totalItems, which is
-- the number remote instances read back as this profile's posts_count, and the
-- same list the profile posts tab renders.
-- REMOTE authors keep the origin-supplied figure. This instance holds only the
-- fraction of their posts that federated here, so a recompute would replace a
-- true number with a smaller one.
-- SECURITY DEFINER: the row written is the author's profile and
-- profiles_update_own admits only its owner, so under invoker rights the
-- counter would track who wrote the post rather than the rows.
CREATE OR REPLACE FUNCTION public.update_profile_posts_count()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions', 'pg_temp'
AS $$
DECLARE
  author uuid;
BEGIN
  -- Two ids only when a post changes hands, which the trigger sees only if the
  -- same statement also writes is_deleted. Ascending id for the lock order.
  FOR author IN
    SELECT DISTINCT id FROM (VALUES
      (CASE WHEN TG_OP <> 'INSERT' THEN OLD.author_id END),
      (CASE WHEN TG_OP <> 'DELETE' THEN NEW.author_id END)
    ) v(id) WHERE id IS NOT NULL ORDER BY 1
  LOOP
    -- Lock the profile first so the recompute takes its snapshot AFTER any
    -- concurrent post by the same author commits.
    PERFORM 1 FROM public.profiles
     WHERE id = author AND is_local IS TRUE FOR UPDATE;

    IF FOUND THEN
      UPDATE public.profiles
      SET posts_count = (
        SELECT count(*) FROM public.posts p
        WHERE p.author_id = author AND p.is_deleted IS DISTINCT FROM true
      )
      WHERE id = author;
    END IF;
  END LOOP;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;

-- Check emoji reaction limit for posts
CREATE OR REPLACE FUNCTION public.check_emoji_reaction_limit()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    reaction_count integer;
BEGIN
    IF NEW.interaction_type = 'emoji_reaction' THEN
        SELECT COUNT(*) INTO reaction_count
        FROM post_interactions
        WHERE user_id = NEW.user_id
          AND post_id = NEW.post_id
          AND interaction_type = 'emoji_reaction';
        
        IF reaction_count >= 20 THEN
            RAISE EXCEPTION 'Maximum emoji reactions per post reached (20)';
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$;

-- Check emoji reaction limit for messages
CREATE OR REPLACE FUNCTION public.check_message_emoji_reaction_limit()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    reaction_count integer;
BEGIN
    SELECT COUNT(*) INTO reaction_count
    FROM reactions
    WHERE user_id = NEW.user_id AND message_id = NEW.message_id;
    
    IF reaction_count >= 20 THEN
        RAISE EXCEPTION 'Maximum emoji reactions per message reached (20)';
    END IF;
    
    RETURN NEW;
END;
$$;

-- ---------------------------------------------------------------------------
-- FEDERATION QUEUE TRIGGERS
-- ---------------------------------------------------------------------------

-- Queue post for federation
CREATE OR REPLACE FUNCTION public.trigger_queue_post_federation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
BEGIN
    -- Skip remote posts (they came from federation, don't re-federate)
    IF NEW.is_local = false THEN
        NEW.federation_status := 'skipped';
        RETURN NEW;
    END IF;

    IF TG_OP = 'INSERT' THEN
        NEW.federation_status := 'queued';
        PERFORM public.queue_federation_job(
            'federate-post',
            jsonb_build_object(
                'type', 'create',
                'post_id', NEW.id,
                'author_id', NEW.author_id,
                'visibility', NEW.visibility,
                'created_at', NEW.created_at
            ), 5, 5, 3600
        );
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF OLD.federation_status IS DISTINCT FROM NEW.federation_status
           AND OLD.content = NEW.content
           AND OLD.is_deleted = NEW.is_deleted
           AND OLD.is_pinned = NEW.is_pinned THEN
            RETURN NEW;
        END IF;

        IF NEW.is_deleted = true AND OLD.is_deleted = false THEN
            NEW.federation_status := 'queued';
            PERFORM public.queue_federation_job(
                'federate-post',
                jsonb_build_object('type', 'delete', 'post_id', NEW.id, 'author_id', NEW.author_id),
                10, 5, 3600
            );
        ELSIF NEW.is_pinned IS DISTINCT FROM OLD.is_pinned THEN
            NEW.federation_status := 'queued';
            PERFORM public.queue_federation_job(
                'federate-post',
                jsonb_build_object('type', 'pin_change', 'post_id', NEW.id, 'author_id', NEW.author_id, 'is_pinned', NEW.is_pinned),
                5, 5, 3600
            );
        ELSIF NEW.content IS DISTINCT FROM OLD.content THEN
            NEW.federation_status := 'queued';
            PERFORM public.queue_federation_job(
                'federate-post',
                jsonb_build_object('type', 'update', 'post_id', NEW.id, 'author_id', NEW.author_id, 'visibility', NEW.visibility),
                5, 5, 3600
            );
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

-- Queue follow for federation
CREATE OR REPLACE FUNCTION public.trigger_queue_follow_federation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
    v_follower_is_local BOOLEAN;
BEGIN
    SELECT is_local INTO v_follower_is_local FROM public.profiles WHERE id = NEW.follower_id;

    IF v_follower_is_local = true THEN
        IF TG_OP = 'INSERT' THEN
            NEW.federation_status := 'queued';
            PERFORM public.queue_federation_job(
                'federate-follow',
                jsonb_build_object(
                    'type', 'create',
                    'follow_id', NEW.id,
                    'follower_id', NEW.follower_id,
                    'following_id', NEW.following_id,
                    'status', NEW.status
                ), 5, 5, 3600
            );
        ELSIF TG_OP = 'DELETE' THEN
            PERFORM public.queue_federation_job(
                'federate-follow',
                jsonb_build_object(
                    'type', 'delete',
                    'follow_id', OLD.id,
                    'follower_id', OLD.follower_id,
                    'following_id', OLD.following_id
                ), 5, 5, 3600
            );
            RETURN OLD;
        END IF;
    ELSE
        NEW.federation_status := 'skipped';
    END IF;

    RETURN NEW;
END;
$$;

-- Queue follow-request response (Accept/Reject) for federation.
-- Fires when a local user resolves a remote follower's pending request;
-- the worker handles job type 'respond' in queue/handlers/followHandler.ts.
-- BEFORE UPDATE so it can stamp federation_status='pending' - the durable
-- marker the 60s sweep retries from if the pg_notify is lost.
CREATE OR REPLACE FUNCTION public.trigger_queue_follow_response_federation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_follower_is_local BOOLEAN;
    v_following_is_local BOOLEAN;
BEGIN
    IF OLD.status = 'pending' AND NEW.status IN ('accepted', 'rejected') THEN
        SELECT is_local INTO v_follower_is_local FROM public.profiles WHERE id = NEW.follower_id;
        SELECT is_local INTO v_following_is_local FROM public.profiles WHERE id = NEW.following_id;

        IF COALESCE(v_follower_is_local, true) = false AND v_following_is_local = true THEN
            NEW.federation_status := 'pending';
            -- follows has no auto-updated_at trigger; stamp it so the sweep's
            -- 2-second notify-race guard applies to this transition.
            NEW.updated_at := now();
            PERFORM public.queue_federation_job(
                'federate-follow',
                jsonb_build_object(
                    'type', 'respond',
                    'follow_id', NEW.id,
                    'follower_id', NEW.follower_id,
                    'following_id', NEW.following_id,
                    'status', NEW.status,
                    'ap_id', NEW.ap_id
                ), 5, 5, 3600
            );
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

-- Queue interaction for federation
CREATE OR REPLACE FUNCTION public.trigger_queue_interaction_federation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
BEGIN
    -- Bookmarks are private/local-only; never federate them
    IF TG_OP = 'INSERT' AND NEW.interaction_type = 'bookmark' THEN
        NEW.federation_status := 'skipped';
        RETURN NEW;
    END IF;
    IF TG_OP = 'DELETE' AND OLD.interaction_type = 'bookmark' THEN
        RETURN OLD;
    END IF;

    IF TG_OP = 'INSERT' THEN
        NEW.federation_status := 'queued';
        PERFORM public.queue_federation_job(
            'federate-reaction',
            jsonb_build_object(
                'type', 'create',
                'interaction_id', NEW.id,
                'interaction_type', NEW.interaction_type,
                'post_id', NEW.post_id,
                'user_id', NEW.user_id,
                'emoji_id', NEW.emoji_id,
                'custom_emoji_content', NEW.custom_emoji_content
            ), 5, 3, 1800
        );
    ELSIF TG_OP = 'DELETE' THEN
        PERFORM public.queue_federation_job(
            'federate-reaction',
            jsonb_build_object(
                'type', 'delete',
                'interaction_id', OLD.id,
                'interaction_type', OLD.interaction_type,
                'post_id', OLD.post_id,
                'user_id', OLD.user_id
            ), 5, 3, 1800
        );
        RETURN OLD;
    END IF;

    RETURN NEW;
END;
$$;

-- Queue profile update for federation (includes custom_status)
CREATE OR REPLACE FUNCTION public.trigger_queue_profile_federation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    IF NEW.is_local != true THEN
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF (
            OLD.display_name IS NOT DISTINCT FROM NEW.display_name AND
            OLD.bio IS NOT DISTINCT FROM NEW.bio AND
            OLD.avatar_url IS NOT DISTINCT FROM NEW.avatar_url AND
            OLD.banner_url IS NOT DISTINCT FROM NEW.banner_url AND
            OLD.custom_status IS NOT DISTINCT FROM NEW.custom_status
        ) THEN
            RETURN NEW;
        END IF;
    END IF;

    PERFORM public.queue_federation_job(
        'federate-profile',
        jsonb_build_object(
            'type', CASE WHEN TG_OP = 'INSERT' THEN 'create' ELSE 'update' END,
            'profile_id', NEW.id,
            'username', NEW.username,
            'display_name', NEW.display_name,
            'bio', NEW.bio,
            'avatar_url', NEW.avatar_url,
            'banner_url', NEW.banner_url,
            'custom_status', NEW.custom_status
        ),
        3, 5, 3600
    );

    RETURN NEW;
END;
$$;

-- ---------------------------------------------------------------------------
-- Thread message handler: auto-add member, update thread stats
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.thread_message_handler()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    IF NEW.thread_id IS NOT NULL THEN
        INSERT INTO public.thread_members (thread_id, user_id)
        VALUES (NEW.thread_id, NEW.user_id)
        ON CONFLICT (thread_id, user_id) DO NOTHING;

        UPDATE public.threads
        SET
            message_count = message_count + 1,
            last_message_id = NEW.id,
            last_message_at = NEW.created_at,
            updated_at = NOW(),
            archived = CASE WHEN locked THEN archived ELSE false END,
            archived_at = CASE WHEN locked THEN archived_at ELSE NULL END
        WHERE id = NEW.thread_id;

        UPDATE public.threads t
        SET member_count = (
            SELECT COUNT(*) FROM public.thread_members tm WHERE tm.thread_id = t.id
        )
        WHERE t.id = NEW.thread_id;
    END IF;
    RETURN NEW;
END;
$$;

-- ---------------------------------------------------------------------------
-- Thread message delete handler: decrement count, update last message
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.thread_message_delete_handler()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    IF OLD.thread_id IS NOT NULL THEN
        UPDATE public.threads
        SET message_count = GREATEST(0, message_count - 1)
        WHERE id = OLD.thread_id;

        UPDATE public.threads t
        SET
            last_message_id = (
                SELECT id FROM public.messages
                WHERE thread_id = t.id AND NOT is_deleted
                ORDER BY created_at DESC LIMIT 1
            ),
            last_message_at = (
                SELECT created_at FROM public.messages
                WHERE thread_id = t.id AND NOT is_deleted
                ORDER BY created_at DESC LIMIT 1
            )
        WHERE t.id = OLD.thread_id;
    END IF;
    RETURN OLD;
END;
$$;

-- Queue thread creation/updates for federation
CREATE OR REPLACE FUNCTION public.trigger_queue_thread_federation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_server_id UUID;
    v_server_is_local BOOLEAN;
    v_creator_is_local BOOLEAN;
BEGIN
    IF TG_OP = 'INSERT' THEN
        -- Threads with ap_id already set came from federation (stub or ChatThread)
        IF NEW.ap_id IS NOT NULL THEN
            NEW.federation_status := 'synced';
            RETURN NEW;
        END IF;

        SELECT c.server_id, s.is_local_server INTO v_server_id, v_server_is_local
        FROM public.channels c JOIN public.servers s ON c.server_id = s.id
        WHERE c.id = NEW.channel_id;

        SELECT is_local INTO v_creator_is_local FROM public.profiles WHERE id = NEW.created_by;

        IF v_creator_is_local IS NOT TRUE THEN
            NEW.federation_status := 'skipped';
            RETURN NEW;
        END IF;

        NEW.federation_status := 'queued';
        PERFORM public.queue_federation_job(
            'federate-thread',
            jsonb_build_object(
                'type', 'create', 'thread_id', NEW.id, 'channel_id', NEW.channel_id,
                'server_id', v_server_id, 'server_is_local', COALESCE(v_server_is_local, true),
                'created_by', NEW.created_by, 'created_at', NEW.created_at
            ), 5, 5, 900
        );
    ELSIF TG_OP = 'UPDATE' THEN
        IF (OLD.name IS NOT DISTINCT FROM NEW.name AND
            OLD.archived IS NOT DISTINCT FROM NEW.archived AND
            OLD.locked IS NOT DISTINCT FROM NEW.locked) THEN
            RETURN NEW;
        END IF;

        SELECT c.server_id, s.is_local_server INTO v_server_id, v_server_is_local
        FROM public.channels c JOIN public.servers s ON c.server_id = s.id
        WHERE c.id = NEW.channel_id;

        SELECT is_local INTO v_creator_is_local FROM public.profiles WHERE id = NEW.created_by;
        IF v_creator_is_local IS NOT TRUE THEN RETURN NEW; END IF;

        IF NEW.federation_status = 'local' OR NEW.federation_status IS NULL THEN
            NEW.federation_status := 'queued';
        END IF;

        PERFORM public.queue_federation_job(
            'federate-thread',
            jsonb_build_object(
                'type', 'update', 'thread_id', NEW.id, 'channel_id', NEW.channel_id,
                'server_id', v_server_id, 'server_is_local', COALESCE(v_server_is_local, true),
                'created_by', NEW.created_by
            ), 5, 5, 900
        );
    END IF;

    RETURN NEW;
EXCEPTION
    WHEN undefined_table THEN RETURN NEW;
    WHEN OTHERS THEN
        RAISE WARNING 'trigger_queue_thread_federation error: %', SQLERRM;
        RETURN NEW;
END;
$$;

-- Unpin message when it's soft-deleted
CREATE OR REPLACE FUNCTION public.handle_pinned_message_delete()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.is_deleted = true AND OLD.is_deleted = false THEN
        NEW.is_pinned := false;
        NEW.pinned_at := NULL;
        NEW.pinned_by := NULL;
    END IF;
    RETURN NEW;
END;
$$;

-- Queue channel message for federation
CREATE OR REPLACE FUNCTION public.trigger_queue_channel_message_federation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
    v_server_id UUID;
    v_server_is_local BOOLEAN;
    v_author_is_local BOOLEAN;
BEGIN
    IF NEW.channel_id IS NOT NULL AND NEW.conversation_id IS NULL THEN
        IF NEW.metadata ? 'federated' THEN
            NEW.federation_status := 'skipped';
            RETURN NEW;
        END IF;

        SELECT is_local INTO v_author_is_local
        FROM public.profiles
        WHERE id = NEW.user_id;

        IF v_author_is_local IS NOT TRUE THEN
            NEW.federation_status := 'skipped';
            RETURN NEW;
        END IF;

        SELECT c.server_id, s.is_local_server
        INTO v_server_id, v_server_is_local
        FROM public.channels c
        JOIN public.servers s ON c.server_id = s.id
        WHERE c.id = NEW.channel_id;

        NEW.federation_status := 'queued';

        PERFORM public.queue_federation_job(
            'federate-channel-message',
            jsonb_build_object(
                'type', 'create',
                'message_id', NEW.id,
                'channel_id', NEW.channel_id,
                'user_id', NEW.user_id,
                'server_id', v_server_id,
                'server_is_local', COALESCE(v_server_is_local, true),
                'created_at', NEW.created_at
            ),
            5, 5, 900
        );
    END IF;

    RETURN NEW;
END;
$$;

