-- ---------------------------------------------------------------------------
-- CONVERSATION RPC FUNCTIONS
-- ---------------------------------------------------------------------------

-- Create group conversation
CREATE OR REPLACE FUNCTION public.create_group_conversation(
    p_creator_user_id uuid,
    p_participant_ids uuid[] DEFAULT '{}',
    p_conversation_name text DEFAULT NULL,
    p_is_private boolean DEFAULT true
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
    v_conversation_id uuid;
    v_participant_id uuid;
BEGIN
    -- SECURITY: Verify the caller is the creator
    IF NOT EXISTS (
        SELECT 1 FROM profiles WHERE id = p_creator_user_id AND auth_user_id = auth.uid()
    ) THEN
        RAISE EXCEPTION 'Unauthorized: You can only create conversations as yourself';
    END IF;

    INSERT INTO conversations (type, name, created_by, metadata)
    VALUES (
        'group',
        p_conversation_name,
        p_creator_user_id,
        jsonb_build_object('is_private', p_is_private)
    )
    RETURNING id INTO v_conversation_id;

    -- Add creator as admin
    INSERT INTO conversation_participants (conversation_id, user_id, role)
    VALUES (v_conversation_id, p_creator_user_id, 'admin');

    -- Add other participants
    IF p_participant_ids IS NOT NULL THEN
        FOREACH v_participant_id IN ARRAY p_participant_ids
        LOOP
            IF v_participant_id != p_creator_user_id THEN
                INSERT INTO conversation_participants (conversation_id, user_id, role)
                VALUES (v_conversation_id, v_participant_id, 'member')
                ON CONFLICT (conversation_id, user_id) DO NOTHING;
            END IF;
        END LOOP;
    END IF;

    RETURN v_conversation_id;
END;
$$;

-- ---------------------------------------------------------------------------
-- TIMELINE RPC FUNCTIONS
-- ---------------------------------------------------------------------------

-- Get timeline posts (home feed)
-- Note: This returns posts from people the caller follows
-- For security, we verify p_user_id matches the caller
CREATE OR REPLACE FUNCTION public.get_timeline(
    p_user_id uuid,
    p_limit integer DEFAULT 50,
    p_before timestamp DEFAULT NOW()
)
RETURNS SETOF posts
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    -- SECURITY: Verify the caller owns this profile (only view your own timeline)
    IF NOT EXISTS (
        SELECT 1 FROM profiles WHERE id = p_user_id AND auth_user_id = auth.uid()
    ) THEN
        RAISE EXCEPTION 'Unauthorized: Cannot view another user''s home timeline';
    END IF;

    RETURN QUERY
    SELECT p.*
    FROM posts p
    WHERE p.author_id IN (
        SELECT following_id 
        FROM follows 
        WHERE follower_id = p_user_id AND status = 'accepted'
    )
    AND p.created_at < p_before
    AND p.is_deleted = false
    ORDER BY p.created_at DESC
    LIMIT p_limit;
END;
$$;

-- Get trending hashtags
-- Trending hashtags over an arbitrary hours window, with rising/falling trend
-- computed against the immediately-preceding window of equal length. The
-- frontend passes the selected time range (1h/6h/24h/7d/30d) as hours so the
-- "Last X" filter is honored at hashtag granularity.
CREATE OR REPLACE FUNCTION public.get_trending_hashtags(
    p_hours integer DEFAULT 168,
    p_limit integer DEFAULT 20
)
RETURNS TABLE(
    tag text,
    uses_count bigint,
    unique_users bigint,
    change_percent numeric,
    trend text
)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_current_start timestamptz;
    v_previous_start timestamptz;
BEGIN
    v_current_start := NOW() - (p_hours || ' hours')::INTERVAL;
    v_previous_start := NOW() - (p_hours * 2 || ' hours')::INTERVAL;

    RETURN QUERY
    WITH current_period AS (
        SELECT
            h.tag AS htag,
            COUNT(*) AS current_uses,
            COUNT(DISTINCT p.author_id) AS current_unique_users
        FROM post_hashtags ph
        JOIN hashtags h ON ph.hashtag_id = h.id
        JOIN posts p ON ph.post_id = p.id
        WHERE ph.created_at > v_current_start
        GROUP BY h.tag
    ),
    previous_period AS (
        SELECT
            h.tag AS htag,
            COUNT(*) AS previous_uses
        FROM post_hashtags ph
        JOIN hashtags h ON ph.hashtag_id = h.id
        JOIN posts p ON ph.post_id = p.id
        WHERE ph.created_at > v_previous_start
          AND ph.created_at <= v_current_start
        GROUP BY h.tag
    )
    SELECT
        cp.htag AS tag,
        cp.current_uses AS uses_count,
        cp.current_unique_users AS unique_users,
        CASE
            WHEN COALESCE(pp.previous_uses, 0) = 0 THEN
                CASE WHEN cp.current_uses > 0 THEN 100.0 ELSE 0.0 END
            ELSE
                ROUND(((cp.current_uses::numeric - pp.previous_uses::numeric) / pp.previous_uses::numeric) * 100, 1)
        END AS change_percent,
        CASE
            WHEN COALESCE(pp.previous_uses, 0) = 0 AND cp.current_uses > 0 THEN 'rising'
            WHEN cp.current_uses > COALESCE(pp.previous_uses, 0) * 1.05 THEN 'rising'
            WHEN cp.current_uses < COALESCE(pp.previous_uses, 0) * 0.95 THEN 'falling'
            ELSE 'stable'
        END AS trend
    FROM current_period cp
    LEFT JOIN previous_period pp ON cp.htag = pp.htag
    ORDER BY cp.current_uses DESC
    LIMIT p_limit;
END;
$$;

-- Backfill timeline entries (admin)
CREATE OR REPLACE FUNCTION public.backfill_timeline_entries()
RETURNS integer
LANGUAGE plpgsql
AS $$
DECLARE
    processed_count INTEGER := 0;
    post_record RECORD;
    follower_record RECORD;
BEGIN
    FOR post_record IN 
        SELECT id, author_id, created_at
        FROM posts 
        WHERE visibility = 'public' 
          AND NOT COALESCE(is_deleted, false)
          AND created_at > NOW() - INTERVAL '30 days'
        ORDER BY created_at DESC
    LOOP
        FOR follower_record IN 
            SELECT f.follower_id 
            FROM follows f 
            WHERE f.following_id = post_record.author_id 
              AND f.status = 'accepted'
        LOOP
            INSERT INTO timeline_entries (user_id, post_id, timeline_type, position)
            VALUES (follower_record.follower_id, post_record.id, 'home', 
                    EXTRACT(epoch FROM post_record.created_at) * 1000000)
            ON CONFLICT (user_id, post_id, timeline_type) DO NOTHING;
        END LOOP;
        
        processed_count := processed_count + 1;
    END LOOP;
    
    RETURN processed_count;
END;
$$;

-- ---------------------------------------------------------------------------
-- POST INTERACTION RPC FUNCTIONS
-- ---------------------------------------------------------------------------

-- Add emoji reaction to post
CREATE OR REPLACE FUNCTION public.add_post_emoji_reaction(
    p_user_id uuid,
    p_post_id uuid,
    p_emoji_id uuid DEFAULT NULL,
    p_custom_emoji_content text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
    v_interaction_id uuid;
    v_resolved_content text;
BEGIN
    -- SECURITY: Verify the caller owns this profile
    IF NOT EXISTS (
        SELECT 1 FROM profiles WHERE id = p_user_id AND auth_user_id = auth.uid()
    ) THEN
        RAISE EXCEPTION 'Unauthorized: Cannot create reactions as another user';
    END IF;

    IF p_emoji_id IS NULL AND p_custom_emoji_content IS NULL THEN
        RAISE EXCEPTION 'Must provide either emoji_id or custom_emoji_content';
    END IF;

    -- Auto-populate custom_emoji_content from emoji table when missing
    v_resolved_content := p_custom_emoji_content;
    IF p_emoji_id IS NOT NULL AND v_resolved_content IS NULL THEN
        SELECT CASE
            WHEN e.url IS NOT NULL THEN ':' || e.name || ':'
            ELSE e.name
        END INTO v_resolved_content
        FROM emojis e WHERE e.id = p_emoji_id;
    END IF;

    -- Idempotent: an existing reaction is returned, not duplicated.
    -- update_post_reaction_counts adds 1 to favorites_count per row, and
    -- remove_post_emoji_reaction deletes every matching row in one statement, so a second
    -- row inflates the count on the way in and drops it by two on the way out.
    -- IS NOT DISTINCT FROM matches idx_post_interactions_emoji_unique, which is
    -- NULLS NOT DISTINCT: emoji_id is null on a unicode reaction, custom_emoji_content is
    -- null on a row written without one.
    SELECT id INTO v_interaction_id
    FROM post_interactions
    WHERE user_id = p_user_id
      AND post_id = p_post_id
      AND interaction_type = 'emoji_reaction'
      AND emoji_id IS NOT DISTINCT FROM p_emoji_id
      AND custom_emoji_content IS NOT DISTINCT FROM v_resolved_content
    ORDER BY created_at, id
    LIMIT 1;

    IF v_interaction_id IS NOT NULL THEN
        RETURN v_interaction_id;
    END IF;

    BEGIN
        INSERT INTO post_interactions (
            user_id, post_id, interaction_type,
            emoji_id, custom_emoji_content, is_local
        ) VALUES (
            p_user_id, p_post_id, 'emoji_reaction',
            p_emoji_id, v_resolved_content, true
        ) RETURNING id INTO v_interaction_id;
    EXCEPTION WHEN unique_violation THEN
        -- Concurrent caller committed the same reaction between the check and the insert.
        -- READ COMMITTED gives the re-read a fresh snapshot, so the winning row is visible.
        SELECT id INTO v_interaction_id
        FROM post_interactions
        WHERE user_id = p_user_id
          AND post_id = p_post_id
          AND interaction_type = 'emoji_reaction'
          AND emoji_id IS NOT DISTINCT FROM p_emoji_id
          AND custom_emoji_content IS NOT DISTINCT FROM v_resolved_content
        ORDER BY created_at, id
        LIMIT 1;
    END;

    RETURN v_interaction_id;
END;
$$;

-- Get batch post reactions
CREATE OR REPLACE FUNCTION public.get_batch_post_reactions(post_ids uuid[])
RETURNS TABLE(
    post_id uuid,
    emoji_id uuid,
    emoji_name varchar,
    emoji_url varchar,
    reaction_count bigint,
    users jsonb
)
LANGUAGE plpgsql
AS $$
BEGIN
    RETURN QUERY
    SELECT 
        pi.post_id,
        pi.emoji_id,
        e.name as emoji_name,
        e.url as emoji_url,
        COUNT(*) as reaction_count,
        jsonb_agg(jsonb_build_object(
            'id', p.id,
            'username', p.username,
            'avatar_url', p.avatar_url
        )) as users
    FROM post_interactions pi
    LEFT JOIN emojis e ON pi.emoji_id = e.id
    JOIN profiles p ON pi.user_id = p.id
    WHERE pi.post_id = ANY(post_ids)
      AND pi.interaction_type = 'emoji_reaction'
    GROUP BY pi.post_id, pi.emoji_id, e.name, e.url;
END;
$$;

-- Get batch message reactions (matching production)
CREATE OR REPLACE FUNCTION public.get_batch_message_reactions(message_ids uuid[])
RETURNS TABLE(
    message_id uuid,
    emoji_id uuid,
    emoji_name character varying,
    emoji_url character varying,
    custom_emoji_content text,
    reaction_count bigint,
    current_user_reacted boolean,
    users jsonb
)
LANGUAGE plpgsql
STABLE
AS $$
BEGIN
    RETURN QUERY
    SELECT 
        r.message_id,
        r.emoji_id,
        COALESCE(e.name, r.custom_emoji_content)::varchar as emoji_name,
        COALESCE(e.url::text, MAX(r.metadata->>'remote_emoji_url'))::varchar as emoji_url,
        r.custom_emoji_content,
        COUNT(r.id)::bigint as reaction_count,
        bool_or(r.user_id = public.get_current_profile_id()) as current_user_reacted,
        jsonb_agg(
            jsonb_build_object(
                'user_id', r.user_id,
                'bot_id', r.bot_id,
                'metadata', r.metadata
            )
        ) as users
    FROM reactions r
    LEFT JOIN emojis e ON r.emoji_id = e.id
    WHERE r.message_id = ANY(get_batch_message_reactions.message_ids)
    GROUP BY r.message_id, r.emoji_id, e.name, e.url, r.custom_emoji_content
    ORDER BY r.message_id, MIN(r.created_at) ASC;
END;
$$;

COMMENT ON FUNCTION public.get_batch_message_reactions(message_ids uuid[]) IS 'Batch fetch reactions for multiple messages including current_user_reacted + metadata for bridged users';

-- Single round-trip page load for channel chat and DMs: messages + grouped
-- reactions in one call. Replaces the client's messages-then-reactions
-- waterfall (see migration 20260704_get_message_page.sql for full rationale).
-- SECURITY INVOKER so messages/reactions RLS applies to the caller.
CREATE OR REPLACE FUNCTION public.get_message_page(
    p_channel_id uuid DEFAULT NULL,
    p_conversation_id uuid DEFAULT NULL,
    p_limit integer DEFAULT 20,
    p_before timestamptz DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql
STABLE
SET search_path = public
AS $$
DECLARE
    v_profile_id uuid := public.get_current_profile_id();
    v_messages jsonb;
    v_ids uuid[];
    v_reactions jsonb := '[]'::jsonb;
BEGIN
    IF (p_channel_id IS NULL) = (p_conversation_id IS NULL) THEN
        RAISE EXCEPTION 'get_message_page: provide exactly one of p_channel_id / p_conversation_id';
    END IF;

    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 100 THEN
        p_limit := 20;
    END IF;

    IF p_channel_id IS NOT NULL THEN
        WITH page AS (
            SELECT m.*
            FROM public.messages m
            WHERE m.channel_id = p_channel_id
              AND m.thread_id IS NULL
              AND (m.is_deleted IS NULL OR m.is_deleted = false)
              AND (p_before IS NULL OR m.created_at < p_before)
            ORDER BY m.created_at DESC
            LIMIT p_limit
        )
        SELECT
            COALESCE(jsonb_agg(to_jsonb(page.*) ORDER BY page.created_at ASC), '[]'::jsonb),
            array_agg(page.id)
        INTO v_messages, v_ids
        FROM page;
    ELSE
        WITH page AS (
            SELECT m.*
            FROM public.messages m
            WHERE m.conversation_id = p_conversation_id
              AND (m.is_deleted IS NULL OR m.is_deleted = false)
              AND (p_before IS NULL OR m.created_at < p_before)
            ORDER BY m.created_at DESC
            LIMIT p_limit
        )
        SELECT
            COALESCE(jsonb_agg(to_jsonb(page.*) ORDER BY page.created_at ASC), '[]'::jsonb),
            array_agg(page.id)
        INTO v_messages, v_ids
        FROM page;
    END IF;

    IF v_ids IS NOT NULL AND array_length(v_ids, 1) > 0 THEN
        SELECT COALESCE(
            jsonb_agg(to_jsonb(gr.*) ORDER BY gr.message_id, gr.first_reaction_at ASC),
            '[]'::jsonb
        )
        INTO v_reactions
        FROM (
            SELECT
                r.message_id,
                r.emoji_id,
                COALESCE(e.name, r.custom_emoji_content)::varchar AS emoji_name,
                COALESCE(e.url::text, MAX(r.metadata->>'remote_emoji_url'))::varchar AS emoji_url,
                r.custom_emoji_content,
                COUNT(r.id)::bigint AS reaction_count,
                bool_or(r.user_id = v_profile_id) AS current_user_reacted,
                jsonb_agg(
                    jsonb_build_object(
                        'user_id', r.user_id,
                        'bot_id', r.bot_id,
                        'metadata', r.metadata
                    )
                ) AS users,
                MIN(r.created_at) AS first_reaction_at
            FROM public.reactions r
            LEFT JOIN public.emojis e ON r.emoji_id = e.id
            WHERE r.message_id = ANY(v_ids)
            GROUP BY r.message_id, r.emoji_id, e.name, e.url, r.custom_emoji_content
        ) gr;
    END IF;

    RETURN jsonb_build_object(
        'messages', v_messages,
        'reactions', v_reactions
    );
END;
$$;

COMMENT ON FUNCTION public.get_message_page(uuid, uuid, integer, timestamptz) IS
'Single round-trip page load for chat/DM: messages (oldest-first) + grouped reactions in one call. Exactly one of p_channel_id / p_conversation_id required. SECURITY INVOKER so messages/reactions RLS applies.';

GRANT EXECUTE ON FUNCTION public.get_message_page(uuid, uuid, integer, timestamptz) TO authenticated;

-- Single round-trip DM sidebar load: conversations + other participants (with
-- profiles) + last message + unread counts + mute state, newest activity
-- first. Replaces the client's 4-6 query waterfall (see migration
-- 20260704_get_user_conversations.sql for full rationale). Caller resolved
-- server-side via get_current_profile_id() - no user-id parameter, which also
-- removes the auth-UUID vs profiles.id confusion for this path.
-- SECURITY INVOKER so RLS on every joined table applies.
CREATE OR REPLACE FUNCTION public.get_user_conversations()
RETURNS jsonb
LANGUAGE sql
STABLE
SET search_path = public
AS $$
WITH me AS (
    SELECT public.get_current_profile_id() AS id
),
parts AS (
    SELECT
        cp.conversation_id,
        cp.role,
        cp.joined_at,
        cp.hidden_at,
        c.created_at,
        c.updated_at,
        c.type,
        c.name,
        c.created_by,
        c.is_active,
        c.metadata
    FROM public.conversation_participants cp
    JOIN public.conversations c ON c.id = cp.conversation_id
    WHERE cp.user_id = (SELECT id FROM me)
      AND cp.left_at IS NULL
)
SELECT COALESCE(
    jsonb_agg(
        jsonb_build_object(
            'conversation_id', p.conversation_id,
            'created_at', p.created_at,
            'updated_at', p.updated_at,
            'type', COALESCE(p.type, 'direct'),
            'name', p.name,
            'created_by', p.created_by,
            'is_active', p.is_active,
            'metadata', p.metadata,
            'hidden_at', p.hidden_at,
            'user_role', p.role,
            'user_joined_at', p.joined_at,
            'other_participants', COALESCE(op.others, '[]'::jsonb),
            'last_message', CASE WHEN lm.id IS NULL THEN NULL ELSE
                jsonb_build_object(
                    'id', lm.id,
                    'user_id', lm.user_id,
                    'content', lm.content,
                    'created_at', lm.created_at,
                    'metadata', lm.metadata
                ) END,
            'unread_messages', COALESCE(uc.unread_messages, 0),
            'unread_mentions', COALESCE(uc.unread_mentions, 0),
            'is_muted', COALESCE(nc.muted, false)
        )
        ORDER BY COALESCE(lm.created_at, p.updated_at, p.created_at) DESC
    ),
    '[]'::jsonb
)
FROM parts p
LEFT JOIN LATERAL (
    SELECT m.id, m.user_id, m.content, m.created_at, m.metadata
    FROM public.messages m
    WHERE m.conversation_id = p.conversation_id
    ORDER BY m.created_at DESC
    LIMIT 1
) lm ON true
LEFT JOIN LATERAL (
    SELECT jsonb_agg(
        jsonb_build_object(
            'user_id', cp2.user_id,
            'role', cp2.role,
            'joined_at', cp2.joined_at,
            'profile', jsonb_build_object(
                'id', pr.id,
                'username', pr.username,
                'display_name', pr.display_name,
                'avatar_url', pr.avatar_url,
                'domain', pr.domain,
                'is_local', pr.is_local,
                'federated_id', pr.federated_id
            )
        )
        ORDER BY cp2.joined_at ASC
    ) AS others
    FROM public.conversation_participants cp2
    JOIN public.profiles pr ON pr.id = cp2.user_id
    WHERE cp2.conversation_id = p.conversation_id
      AND cp2.user_id <> (SELECT id FROM me)
      AND cp2.left_at IS NULL
) op ON true
-- LATERAL LIMIT 1 instead of plain joins: neither table has a unique
-- constraint on (user_id, conversation_id), and a duplicate row would
-- otherwise duplicate the conversation in the sidebar.
LEFT JOIN LATERAL (
    SELECT u.unread_messages, u.unread_mentions
    FROM public.unread_counts u
    WHERE u.conversation_id = p.conversation_id
      AND u.user_id = (SELECT id FROM me)
    LIMIT 1
) uc ON true
LEFT JOIN LATERAL (
    SELECT n.muted
    FROM public.notification_channels n
    WHERE n.conversation_id = p.conversation_id
      AND n.user_id = (SELECT id FROM me)
      AND n.channel_id IS NULL
    LIMIT 1
) nc ON true
$$;

COMMENT ON FUNCTION public.get_user_conversations() IS
'Single round-trip DM sidebar load: conversations + other participants (with profiles) + last message + unread counts + mute state, newest activity first. Caller resolved via get_current_profile_id(). SECURITY INVOKER so RLS applies.';

GRANT EXECUTE ON FUNCTION public.get_user_conversations() TO authenticated;

-- Get reactions for a single message (singular version)
CREATE OR REPLACE FUNCTION public.get_message_reactions(message_id uuid) 
RETURNS TABLE(count bigint, emoji jsonb, reactions jsonb, current_user_reacted boolean, message_id_of_reactions uuid)
LANGUAGE plpgsql STABLE
AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COUNT(r.id)::bigint as count,
        CASE 
            WHEN r.emoji_id IS NOT NULL THEN
                -- Custom server emoji - use emoji table data
                jsonb_build_object(
                    'id', e.id,
                    'name', e.name,
                    'url', e.url,
                    'is_native', false
                )
            ELSE
                -- Unicode or URL-only remote emoji (e.g. Discord bridge)
                jsonb_build_object(
                    'id', r.custom_emoji_content,
                    'name', COALESCE(
                        NULLIF(MAX(r.metadata->>'remote_emoji_name'), ''),
                        r.custom_emoji_content
                    ),
                    'url', MAX(r.metadata->>'remote_emoji_url'),
                    'content', r.custom_emoji_content,
                    'is_native', (MAX(r.metadata->>'remote_emoji_url') IS NULL)
                )
        END as emoji,
        (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'user_id', r2.user_id,
                    'bot_id', r2.bot_id,
                    'metadata', r2.metadata,
                    'username', p.username,
                    'display_name', p.display_name,
                    'avatar_url', p.avatar_url
                )
            )
            FROM reactions r2
            LEFT JOIN profiles p ON r2.user_id = p.id
            WHERE r2.message_id = get_message_reactions.message_id
            AND (
                (r2.emoji_id IS NOT DISTINCT FROM r.emoji_id)
                AND (r2.custom_emoji_content IS NOT DISTINCT FROM r.custom_emoji_content)
            )
        ) as reactions,
        bool_or(r.user_id = public.get_current_profile_id()) as current_user_reacted,
        r.message_id as message_id_of_reactions
    FROM reactions r
    LEFT JOIN emojis e ON r.emoji_id = e.id
    WHERE r.message_id = get_message_reactions.message_id
    GROUP BY r.message_id, r.emoji_id, e.id, e.name, e.url, r.custom_emoji_content
    ORDER BY MIN(r.created_at) ASC;
END;
$$;

COMMENT ON FUNCTION public.get_message_reactions(message_id uuid) IS 'Returns reaction groups for a message including metadata for bridged users (Discord, etc.)';

-- ---------------------------------------------------------------------------
-- SERVER RPC FUNCTIONS
-- ---------------------------------------------------------------------------

-- Add bot to server
CREATE OR REPLACE FUNCTION public.add_bot_to_server(
    p_bot_id uuid,
    p_server_id uuid,
    p_installed_by uuid,
    p_permissions jsonb DEFAULT '{}'
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_permission_id uuid;
    v_caller_profile_id uuid;
BEGIN
    -- SECURITY: Get caller's profile ID
    SELECT id INTO v_caller_profile_id FROM profiles WHERE auth_user_id = auth.uid();
    
    IF v_caller_profile_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized: Authentication required';
    END IF;
    
    -- SECURITY: Verify caller is server owner or has manage permissions
    IF NOT EXISTS (
        SELECT 1 FROM servers WHERE id = p_server_id AND owner = v_caller_profile_id
    ) AND NOT EXISTS (
        SELECT 1 FROM profiles WHERE id = v_caller_profile_id AND is_admin = true
    ) THEN
        RAISE EXCEPTION 'Unauthorized: Only server owners can add bots';
    END IF;
    
    -- SECURITY: The installer must be the caller
    IF p_installed_by != v_caller_profile_id THEN
        RAISE EXCEPTION 'Unauthorized: Cannot claim installation by another user';
    END IF;

    -- SECURITY: Only public bots are discoverable; owners may install their own private bots
    IF NOT EXISTS (
        SELECT 1 FROM bots
        WHERE id = p_bot_id
          AND (is_public = true OR owner_id = v_caller_profile_id)
    ) THEN
        RAISE EXCEPTION 'Unauthorized: Bot is not public';
    END IF;

    INSERT INTO bot_server_permissions (
        bot_id, server_id, installed_by, is_active,
        read_messages, send_messages, manage_messages,
        embed_links, attach_files, mention_everyone,
        add_reactions, manage_channels, kick_members, ban_members
    ) VALUES (
        p_bot_id, p_server_id, p_installed_by, true,
        COALESCE((p_permissions->>'read_messages')::boolean, true),
        COALESCE((p_permissions->>'send_messages')::boolean, true),
        COALESCE((p_permissions->>'manage_messages')::boolean, false),
        COALESCE((p_permissions->>'embed_links')::boolean, true),
        COALESCE((p_permissions->>'attach_files')::boolean, true),
        COALESCE((p_permissions->>'mention_everyone')::boolean, false),
        COALESCE((p_permissions->>'add_reactions')::boolean, true),
        COALESCE((p_permissions->>'manage_channels')::boolean, false),
        COALESCE((p_permissions->>'kick_members')::boolean, false),
        COALESCE((p_permissions->>'ban_members')::boolean, false)
    )
    ON CONFLICT (bot_id, server_id) DO UPDATE SET
        is_active = true,
        installed_by = EXCLUDED.installed_by,
        read_messages = EXCLUDED.read_messages,
        send_messages = EXCLUDED.send_messages,
        manage_messages = EXCLUDED.manage_messages,
        embed_links = EXCLUDED.embed_links,
        attach_files = EXCLUDED.attach_files,
        mention_everyone = EXCLUDED.mention_everyone,
        add_reactions = EXCLUDED.add_reactions,
        manage_channels = EXCLUDED.manage_channels,
        kick_members = EXCLUDED.kick_members,
        ban_members = EXCLUDED.ban_members
    RETURNING id INTO v_permission_id;
    
    RETURN v_permission_id;
END;
$$;

-- Delete server with cleanup
CREATE OR REPLACE FUNCTION public.delete_server_with_cleanup(p_server_id uuid, p_owner_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_caller_profile_id uuid;
BEGIN
    -- SECURITY: Get caller's profile ID
    SELECT id INTO v_caller_profile_id FROM profiles WHERE auth_user_id = auth.uid();
    
    IF v_caller_profile_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized: Authentication required';
    END IF;
    
    -- SECURITY: Verify p_owner_id matches the caller
    IF v_caller_profile_id != p_owner_id THEN
        RAISE EXCEPTION 'Unauthorized: Cannot delete server as another user';
    END IF;
    
    -- Verify caller is actually the owner
    IF NOT EXISTS (SELECT 1 FROM servers WHERE id = p_server_id AND owner = v_caller_profile_id) THEN
        RAISE EXCEPTION 'Not authorized to delete this server';
    END IF;
    
    -- Delete all related data (cascades handle most)
    DELETE FROM servers WHERE id = p_server_id;
END;
$$;

-- ---------------------------------------------------------------------------
-- THREAD RPC FUNCTIONS
-- ---------------------------------------------------------------------------

-- Create thread from message
CREATE OR REPLACE FUNCTION public.create_thread(
    p_message_id uuid,
    p_name text,
    p_auto_archive_duration integer DEFAULT 1440
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_thread_id uuid;
    v_channel_id uuid;
    v_server_id uuid;
    v_caller_profile_id uuid;
BEGIN
    -- SECURITY: Get caller's profile ID
    SELECT id INTO v_caller_profile_id FROM profiles WHERE auth_user_id = auth.uid();
    
    IF v_caller_profile_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized: Authentication required';
    END IF;

    SELECT channel_id INTO v_channel_id
    FROM messages WHERE id = p_message_id;
    
    IF v_channel_id IS NULL THEN
        RAISE EXCEPTION 'Message not found or not in a channel';
    END IF;
    
    -- SECURITY: Verify caller is a member of the server containing this channel
    SELECT server_id INTO v_server_id FROM channels WHERE id = v_channel_id;
    
    IF NOT EXISTS (
        SELECT 1 FROM user_servers 
        WHERE server_id = v_server_id 
          AND user_id = v_caller_profile_id 
          AND status = 'accepted'
    ) THEN
        RAISE EXCEPTION 'Unauthorized: You must be a server member to create threads';
    END IF;
    
    INSERT INTO threads (
        channel_id, parent_message_id, name, created_by, auto_archive_duration
    ) VALUES (
        v_channel_id, p_message_id, p_name, v_caller_profile_id, p_auto_archive_duration
    ) RETURNING id INTO v_thread_id;
    
    -- Add caller as thread member
    INSERT INTO thread_members (thread_id, user_id)
    VALUES (v_thread_id, v_caller_profile_id);
    
    RETURN v_thread_id;
END;
$$;

-- Auto-archive inactive threads
CREATE OR REPLACE FUNCTION public.auto_archive_threads()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    UPDATE threads
    SET archived = true, archived_at = NOW()
    WHERE NOT archived
      AND NOT locked
      AND last_message_at < NOW() - (auto_archive_duration || ' minutes')::interval;
END;
$$;

-- ---------------------------------------------------------------------------
-- ENCRYPTION RPC FUNCTIONS
-- ---------------------------------------------------------------------------

-- Initialize user encryption (Megolm-style key pairs)
CREATE OR REPLACE FUNCTION public.initialize_user_encryption(
    p_user_id uuid,
    p_identity_public_key text,
    p_identity_private_key_encrypted text,
    p_device_id text DEFAULT 'default'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
    v_key_pair_id UUID;
BEGIN
    -- SECURITY: Verify the caller owns this profile
    IF NOT EXISTS (
        SELECT 1 FROM profiles WHERE id = p_user_id AND auth_user_id = auth.uid()
    ) THEN
        RAISE EXCEPTION 'Unauthorized: Cannot initialize encryption for another user';
    END IF;
    
    IF EXISTS (SELECT 1 FROM user_key_pairs WHERE user_id = p_user_id AND device_id = p_device_id) THEN
        RAISE EXCEPTION 'Encryption already initialized for this device';
    END IF;
    
    INSERT INTO user_key_pairs (
        user_id, device_id, identity_public_key, identity_private_key_encrypted, key_version, is_active
    ) VALUES (
        p_user_id, p_device_id, p_identity_public_key, p_identity_private_key_encrypted, 1, true
    ) RETURNING id INTO v_key_pair_id;
    
    RETURN jsonb_build_object('success', true, 'key_pair_id', v_key_pair_id, 'device_id', p_device_id);
END;
$$;

-- Add user prekeys
-- DEPRECATED (July 2026): Signal client stack removed; prekeys are unused by
-- the Megolm encryption path. Kept for schema stability; DROP planned.
CREATE OR REPLACE FUNCTION public.add_user_prekeys(
    p_user_id uuid,
    p_device_id text,
    p_prekeys jsonb
)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_prekey JSONB;
    v_inserted_count INTEGER := 0;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM profiles WHERE id = p_user_id AND auth_user_id = auth.uid()
    ) THEN
        RAISE EXCEPTION 'Unauthorized';
    END IF;
    
    FOR v_prekey IN SELECT * FROM jsonb_array_elements(p_prekeys)
    LOOP
        INSERT INTO prekeys (user_id, device_id, prekey_id, public_key, is_signed, signature, is_one_time)
        VALUES (
            p_user_id, p_device_id,
            (v_prekey->>'prekey_id')::integer,
            v_prekey->>'public_key',
            COALESCE((v_prekey->>'is_signed')::boolean, false),
            v_prekey->>'signature',
            COALESCE((v_prekey->>'is_one_time')::boolean, true)
        )
        ON CONFLICT (user_id, device_id, prekey_id) DO UPDATE
        SET public_key = EXCLUDED.public_key, signature = EXCLUDED.signature;
        
        v_inserted_count := v_inserted_count + 1;
    END LOOP;
    
    RETURN v_inserted_count;
END;
$$;

-- Get unused prekey
-- Note: Table uses used_at timestamp instead of is_used boolean
CREATE OR REPLACE FUNCTION public.get_unused_prekey(p_user_id uuid, p_device_id text DEFAULT 'default')
RETURNS prekeys
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_prekey prekeys;
BEGIN
    -- Get an unused one-time prekey (used_at IS NULL means unused)
    SELECT * INTO v_prekey
    FROM prekeys
    WHERE user_id = p_user_id
      AND device_id = p_device_id
      AND is_one_time = true
      AND used_at IS NULL
    ORDER BY created_at ASC
    LIMIT 1
    FOR UPDATE SKIP LOCKED;
    
    -- Mark as used
    IF v_prekey IS NOT NULL THEN
        UPDATE prekeys
        SET used_at = NOW()
        WHERE id = v_prekey.id;
    END IF;
    
    RETURN v_prekey;
END;
$$;

-- Enable conversation encryption
CREATE OR REPLACE FUNCTION public.enable_conversation_encryption(p_conversation_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_caller_profile_id uuid;
BEGIN
    -- SECURITY: Get caller's profile ID
    SELECT id INTO v_caller_profile_id FROM profiles WHERE auth_user_id = auth.uid();
    
    IF v_caller_profile_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized: Authentication required';
    END IF;
    
    -- SECURITY: Verify caller is a participant in the conversation
    IF NOT EXISTS (
        SELECT 1 FROM conversation_participants 
        WHERE conversation_id = p_conversation_id 
          AND user_id = v_caller_profile_id
          AND left_at IS NULL
    ) THEN
        RAISE EXCEPTION 'Unauthorized: You must be a participant to modify encryption settings';
    END IF;

    INSERT INTO conversation_encryption_settings (conversation_id, encryption_enabled)
    VALUES (p_conversation_id, true)
    ON CONFLICT (conversation_id) DO UPDATE SET encryption_enabled = true, updated_at = NOW();
    
    RETURN jsonb_build_object('success', true, 'conversation_id', p_conversation_id);
END;
$$;

-- ---------------------------------------------------------------------------
-- NOTIFICATION RPC FUNCTIONS
-- ---------------------------------------------------------------------------

-- Create notification with spam prevention
-- SECURITY: Validates caller identity - p_source_user_id must match the authenticated user.
-- Uses rate limiting for reaction notifications to avoid spam.
-- Delegates to send_notification_to_user for the actual insert.
CREATE OR REPLACE FUNCTION public.create_notification_with_spam_prevention(
    p_user_id uuid,
    p_type text,
    p_source_user_id uuid,
    p_title text DEFAULT NULL,
    p_message text DEFAULT NULL,
    p_data jsonb DEFAULT '{}'::jsonb,
    p_server_id uuid DEFAULT NULL,
    p_channel_id uuid DEFAULT NULL,
    p_conversation_id uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
    v_notification_id uuid;
    v_caller_profile_id uuid;
    v_rate_limit RECORD;
    v_should_suppress boolean := false;
    v_time_threshold timestamp with time zone := NOW() - INTERVAL '2 minutes';
BEGIN
    -- SECURITY: Verify caller identity
    SELECT id INTO v_caller_profile_id FROM profiles WHERE auth_user_id = auth.uid();

    IF v_caller_profile_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized: Authentication required';
    END IF;

    IF p_source_user_id != v_caller_profile_id THEN
        RAISE EXCEPTION 'Unauthorized: Cannot create notifications from another user';
    END IF;

    IF p_type = 'reaction' AND p_source_user_id IS NOT NULL THEN
        INSERT INTO notification_rate_limits (user_id, notification_type, source_user_id,
                                              notification_count, last_notification_at, suppressed_until)
        VALUES (p_user_id, p_type, p_source_user_id, 1, NOW(), NULL)
        ON CONFLICT (user_id, notification_type, source_user_id)
        DO UPDATE SET
            notification_count = CASE
                WHEN notification_rate_limits.last_notification_at < v_time_threshold
                THEN 1
                ELSE notification_rate_limits.notification_count + 1
            END,
            last_notification_at = NOW(),
            suppressed_until = CASE
                WHEN notification_rate_limits.last_notification_at < v_time_threshold
                THEN NULL
                ELSE notification_rate_limits.suppressed_until
            END
        RETURNING * INTO v_rate_limit;

        SELECT
            notification_count > 3 OR
            (suppressed_until IS NOT NULL AND suppressed_until > NOW())
        INTO v_should_suppress
        FROM notification_rate_limits
        WHERE user_id = p_user_id AND notification_type = p_type AND source_user_id = p_source_user_id;

        IF v_should_suppress THEN
            UPDATE notification_rate_limits
            SET suppressed_until = NOW() + INTERVAL '2 minutes'
            WHERE user_id = p_user_id AND notification_type = p_type AND source_user_id = p_source_user_id;
            RETURN NULL;
        END IF;
    END IF;

    SELECT send_notification_to_user(
        p_type,
        p_user_id,
        p_data,
        p_server_id,
        p_channel_id,
        p_conversation_id,
        p_source_user_id,
        'normal'
    ) INTO v_notification_id;

    RETURN v_notification_id;
END;
$$;

COMMENT ON FUNCTION public.create_notification_with_spam_prevention IS
'Creates notifications with spam prevention. Suppresses repeated notifications from same source within time windows.';

-- Create structured notification
-- SECURITY: Caller must be the target user, an admin, or service_role.
CREATE OR REPLACE FUNCTION public.create_notification_structured(
    p_user_id uuid,
    p_type varchar,
    p_data jsonb DEFAULT '{}'
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    notification_id UUID;
    v_caller_profile_id uuid;
BEGIN
    SELECT id INTO v_caller_profile_id FROM profiles WHERE auth_user_id = auth.uid();

    -- Allow service_role (auth.uid() IS NULL) or self-notification or admin
    IF v_caller_profile_id IS NOT NULL THEN
        IF v_caller_profile_id != p_user_id AND NOT EXISTS (
            SELECT 1 FROM profiles WHERE id = v_caller_profile_id AND is_admin = true
        ) THEN
            RAISE EXCEPTION 'Unauthorized: Cannot create notifications for other users';
        END IF;
    END IF;

    INSERT INTO notifications (user_id, type, data, created_at, is_read)
    VALUES (p_user_id, p_type, p_data, NOW(), false)
    RETURNING id INTO notification_id;

    RETURN notification_id;
END;
$$;

COMMENT ON FUNCTION public.create_notification_structured IS 'Create notification with structured data';

-- ---------------------------------------------------------------------------
-- PINNED MESSAGES RPC
-- ---------------------------------------------------------------------------

-- Count pinned messages
CREATE OR REPLACE FUNCTION public.count_pinned_messages(
    p_channel_id uuid DEFAULT NULL,
    p_conversation_id uuid DEFAULT NULL
)
RETURNS integer
LANGUAGE plpgsql
AS $$
BEGIN
    RETURN (
        SELECT COUNT(*)::integer
        FROM messages
        WHERE is_pinned = true
          AND is_deleted = false
          AND (p_channel_id IS NULL OR channel_id = p_channel_id)
          AND (p_conversation_id IS NULL OR conversation_id = p_conversation_id)
    );
END;
$$;

-- ---------------------------------------------------------------------------
-- PUSH SUBSCRIPTION RPC
-- ---------------------------------------------------------------------------

-- Delete push subscription by endpoint
CREATE OR REPLACE FUNCTION public.delete_push_subscription_by_endpoint(p_endpoint text)
RETURNS void
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
    DELETE FROM push_subscriptions WHERE endpoint = p_endpoint;
$$;

-- ---------------------------------------------------------------------------
-- SESSION RPC FUNCTIONS
-- ---------------------------------------------------------------------------

-- End user session
-- Uses session_token for identification
CREATE OR REPLACE FUNCTION public.end_user_session(p_user_id uuid, p_session_token text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_caller_profile_id uuid;
BEGIN
    -- SECURITY: Get caller's profile ID
    SELECT id INTO v_caller_profile_id FROM profiles WHERE auth_user_id = auth.uid();
    
    -- Only allow ending your own sessions
    IF v_caller_profile_id IS NULL OR v_caller_profile_id != p_user_id THEN
        RAISE EXCEPTION 'Unauthorized: Cannot end another user''s session';
    END IF;

    UPDATE user_sessions 
    SET is_active = false, status = 'offline'
    WHERE user_id = p_user_id AND session_token = p_session_token;
END;
$$;

-- Update session heartbeat (keep session alive)
CREATE OR REPLACE FUNCTION public.update_session_heartbeat(
    p_session_token text,
    p_status text DEFAULT 'online'
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_caller_profile_id uuid;
BEGIN
    SELECT id INTO v_caller_profile_id FROM profiles WHERE auth_user_id = auth.uid();
    
    IF v_caller_profile_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized: Authentication required';
    END IF;

    UPDATE user_sessions 
    SET last_heartbeat = NOW(), 
        status = p_status,
        is_active = true
    WHERE user_id = v_caller_profile_id AND session_token = p_session_token;
END;
$$;

-- Update session context (what user is viewing)
CREATE OR REPLACE FUNCTION public.update_session_context(
    p_session_token text,
    p_server_id uuid DEFAULT NULL,
    p_channel_id uuid DEFAULT NULL,
    p_conversation_id uuid DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_caller_profile_id uuid;
BEGIN
    SELECT id INTO v_caller_profile_id FROM profiles WHERE auth_user_id = auth.uid();
    
    IF v_caller_profile_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized: Authentication required';
    END IF;

    UPDATE user_sessions 
    SET current_server_id = p_server_id,
        current_channel_id = p_channel_id,
        current_conversation_id = p_conversation_id,
        last_activity = NOW()
    WHERE user_id = v_caller_profile_id AND session_token = p_session_token;
END;
$$;

-- Cleanup stale sessions
-- Uses last_activity for determining staleness
CREATE OR REPLACE FUNCTION public.cleanup_stale_user_sessions()
RETURNS integer
LANGUAGE plpgsql
AS $$
DECLARE
    deleted_count integer;
BEGIN
    -- Mark old sessions as inactive first
    UPDATE user_sessions
    SET is_active = false, status = 'offline'
    WHERE is_active = true
      AND last_activity < NOW() - INTERVAL '30 days';
    
    -- Delete very old sessions
    DELETE FROM user_sessions
    WHERE last_activity < NOW() - INTERVAL '90 days';
    
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN COALESCE(deleted_count, 0);
END;
$$;

-- ---------------------------------------------------------------------------
-- CLEANUP RPC FUNCTIONS
-- ---------------------------------------------------------------------------

-- Cleanup old notifications
CREATE OR REPLACE FUNCTION public.cleanup_old_notifications()
RETURNS integer
LANGUAGE plpgsql
AS $$
DECLARE
    deleted_count integer;
BEGIN
    DELETE FROM notifications
    WHERE created_at < NOW() - INTERVAL '90 days'
      AND is_read = true;
    
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;

-- Expire pending invites past their TTL. expires_at defaults to now() + 60s.
CREATE OR REPLACE FUNCTION public.cleanup_expired_voice_calls()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions', 'pg_temp'
AS $$
BEGIN
    UPDATE public.federated_voice_calls
    SET status = 'expired'
    WHERE status = 'pending'
      AND expires_at < NOW();
END;
$$;

-- Cleanup stale voice participants
CREATE OR REPLACE FUNCTION public.cleanup_stale_voice_participants()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    DELETE FROM voice_channel_participants
    WHERE joined_at < NOW() - INTERVAL '24 hours';
END;
$$;

-- Cleanup old trending data
CREATE OR REPLACE FUNCTION public.cleanup_old_trending_data()
RETURNS integer
LANGUAGE plpgsql
AS $$
DECLARE
    deleted_count integer := 0;
BEGIN
    DELETE FROM trending_posts WHERE period_end < NOW() - INTERVAL '30 days';
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    
    DELETE FROM trending_users WHERE period_end < NOW() - INTERVAL '30 days';
    
    RETURN deleted_count;
END;
$$;

-- Cleanup expired statuses
CREATE OR REPLACE FUNCTION public.cleanup_expired_statuses()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    cleared_count integer;
BEGIN
    UPDATE profiles
    SET custom_status = NULL
    WHERE custom_status IS NOT NULL
      AND (custom_status->>'expires_at')::timestamptz < NOW();
    
    GET DIAGNOSTICS cleared_count = ROW_COUNT;
    RETURN cleared_count;
END;
$$;

-- Cleanup stale push subscriptions
CREATE OR REPLACE FUNCTION public.cleanup_stale_push_subscriptions()
RETURNS integer
LANGUAGE plpgsql
AS $$
DECLARE
    deleted_count integer;
BEGIN
    DELETE FROM push_subscriptions
    WHERE updated_at < NOW() - INTERVAL '90 days';
    
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;

-- ---------------------------------------------------------------------------
-- EMOJI RPC FUNCTIONS
-- ---------------------------------------------------------------------------

-- Get emoji metadata bulk
-- Note: emojis table only has created_at, not updated_at
CREATE OR REPLACE FUNCTION public.get_emoji_metadata_bulk(server_ids uuid[])
RETURNS TABLE(server_id uuid, last_modified timestamptz, emoji_count integer)
LANGUAGE plpgsql
AS $$
BEGIN
    RETURN QUERY
    SELECT 
        e.server_id,
        MAX(e.created_at) as last_modified,
        COUNT(e.id)::integer as emoji_count
    FROM emojis e
    WHERE e.server_id = ANY(server_ids)
    GROUP BY e.server_id;
END;
$$;

-- Create federated emoji (instance-scoped; used by bots / Discord bridge / federation)
CREATE OR REPLACE FUNCTION public.create_federated_emoji(
    p_name text,
    p_url text,
    p_created_by uuid,
    p_domain text DEFAULT NULL
)
RETURNS TABLE(id uuid, created_at timestamptz, name text, url text, server_id uuid, uploader uuid, domain text, scope text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    RETURN QUERY
    INSERT INTO emojis (name, url, uploader, domain, scope, server_id)
    VALUES (
        p_name,
        p_url,
        -- Qualified. RETURNS TABLE declares an OUT parameter named id, which otherwise
        -- shadows the table column: 42702, on every call.
        COALESCE(
            (SELECT owner_id FROM bots WHERE bots.id = p_created_by),
            CASE
                WHEN EXISTS (SELECT 1 FROM profiles WHERE profiles.id = p_created_by) THEN p_created_by
                ELSE NULL
            END
        ),
        p_domain,
        'instance',
        NULL
    )
    RETURNING emojis.id, emojis.created_at, emojis.name::text, emojis.url::text, emojis.server_id,
              emojis.uploader, emojis.domain, emojis.scope;
END;
$$;

-- ---------------------------------------------------------------------------
-- DISCORD BRIDGE PAIRING RPCs
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.generate_discord_bridge_pairing_code()
RETURNS text
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
    v_code text;
BEGIN
    LOOP
        v_code := 'HRM-'
            || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 4))
            || '-'
            || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 4));
        EXIT WHEN NOT EXISTS (
            SELECT 1 FROM public.discord_bridge_pairings WHERE pairing_code = v_code
        );
    END LOOP;
    RETURN v_code;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.generate_discord_bridge_pairing_code() FROM PUBLIC;

CREATE OR REPLACE FUNCTION public.get_or_create_discord_bridge_pairing(p_server_id uuid)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_caller uuid;
    v_code text;
BEGIN
    v_caller := public.get_current_profile_id();
    IF v_caller IS NULL THEN
        RAISE EXCEPTION 'Unauthorized: Authentication required';
    END IF;

    IF NOT (
        EXISTS (SELECT 1 FROM public.servers WHERE id = p_server_id AND owner = v_caller)
        OR public.has_permission(v_caller, p_server_id, 'MANAGE_SERVER')
    ) THEN
        RAISE EXCEPTION 'Unauthorized: Only server owners or managers can manage Discord bridge pairing';
    END IF;

    SELECT pairing_code INTO v_code
    FROM public.discord_bridge_pairings
    WHERE server_id = p_server_id;

    IF v_code IS NOT NULL THEN
        RETURN v_code;
    END IF;

    v_code := public.generate_discord_bridge_pairing_code();

    INSERT INTO public.discord_bridge_pairings (server_id, pairing_code, created_by)
    VALUES (p_server_id, v_code, v_caller)
    ON CONFLICT (server_id) DO NOTHING;

    SELECT pairing_code INTO v_code
    FROM public.discord_bridge_pairings
    WHERE server_id = p_server_id;

    RETURN v_code;
END;
$$;

CREATE OR REPLACE FUNCTION public.regenerate_discord_bridge_pairing(p_server_id uuid)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_caller uuid;
    v_code text;
BEGIN
    v_caller := public.get_current_profile_id();
    IF v_caller IS NULL THEN
        RAISE EXCEPTION 'Unauthorized: Authentication required';
    END IF;

    IF NOT (
        EXISTS (SELECT 1 FROM public.servers WHERE id = p_server_id AND owner = v_caller)
        OR public.has_permission(v_caller, p_server_id, 'MANAGE_SERVER')
    ) THEN
        RAISE EXCEPTION 'Unauthorized: Only server owners or managers can manage Discord bridge pairing';
    END IF;

    v_code := public.generate_discord_bridge_pairing_code();

    INSERT INTO public.discord_bridge_pairings (server_id, pairing_code, created_by, updated_at)
    VALUES (p_server_id, v_code, v_caller, now())
    ON CONFLICT (server_id) DO UPDATE
        SET pairing_code = EXCLUDED.pairing_code,
            updated_at = now();

    RETURN v_code;
END;
$$;

CREATE OR REPLACE FUNCTION public.lookup_discord_bridge_pairing_public(p_pairing_code text)
RETURNS TABLE (server_id uuid)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_code text;
BEGIN
    v_code := upper(trim(p_pairing_code));
    IF v_code IS NULL OR v_code = '' OR v_code !~ '^HRM-[A-Z0-9]{4}-[A-Z0-9]{4}$' THEN
        RETURN;
    END IF;

    RETURN QUERY
    SELECT dbp.server_id
    FROM public.discord_bridge_pairings dbp
    WHERE dbp.pairing_code = v_code;
END;
$$;

