END $$;


-- ---------------------------------------------------------------------------
-- check_key_consistency - Check for users with inconsistent key state
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.check_key_consistency() 
RETURNS TABLE(user_id uuid, username text, has_public_key boolean, has_private_key boolean)
LANGUAGE plpgsql 
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    RETURN QUERY
    SELECT 
        p.id as user_id,
        p.username,
        (p.public_key IS NOT NULL) as has_public_key,
        (upk.id IS NOT NULL) as has_private_key
    FROM profiles p
    LEFT JOIN user_private_keys upk ON upk.user_id = p.id
    WHERE p.is_local = true
    AND (
        -- Has public key but no private key (broken)
        (p.public_key IS NOT NULL AND upk.id IS NULL)
        OR
        -- Has private key but no public key (also broken)
        (p.public_key IS NULL AND upk.id IS NOT NULL)
    );
END;
$$;

COMMENT ON FUNCTION public.check_key_consistency() IS 'Check for local users with inconsistent key state (public key without private key or vice versa)';

-- ---------------------------------------------------------------------------
-- get_server_encryption_stats - Aggregated encryption stats for a server
-- Replaces per-user N+1 calls to user_has_encryption
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_server_encryption_stats(p_server_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_total int;
  v_with_keys int;
BEGIN
  SELECT count(*) INTO v_total
  FROM user_servers WHERE server_id = p_server_id;

  SELECT count(DISTINCT us.user_id) INTO v_with_keys
  FROM user_servers us
  JOIN user_key_pairs ukp ON ukp.user_id = us.user_id
  WHERE us.server_id = p_server_id;

  RETURN jsonb_build_object(
    'total', v_total,
    'with_keys', v_with_keys,
    'percentage', CASE WHEN v_total > 0
      THEN round((v_with_keys::numeric / v_total) * 100)
      ELSE 0 END
  );
END;
$$;

COMMENT ON FUNCTION public.get_server_encryption_stats(uuid) IS 'Get aggregated encryption adoption stats for a server in a single query';

-- ---------------------------------------------------------------------------
-- Function: handle_unified_notification_processing
-- Handles notifications for follows, reactions, and ActivityPub emoji reactions.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.handle_unified_notification_processing() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    single_target_id uuid;
    notification_data jsonb;
    msg_channel_id uuid;
    msg_server_id uuid;
    msg_conversation_id uuid;
    msg_channel_name text;
    msg_server_name text;
    post_author_id uuid;
    post_record RECORD;
    emoji_record RECORD;
    emoji_name text;
    emoji_url text;
    reactor_profile RECORD;
    follower_profile RECORD;
    accepter_profile RECORD;
    follow_notification_type text;
BEGIN
    -- Handle follows
    IF TG_TABLE_NAME = 'follows' AND TG_OP = 'INSERT' THEN
        SELECT id, username, display_name, avatar_url, domain, is_local
        INTO follower_profile
        FROM profiles
        WHERE id = NEW.follower_id;

        IF follower_profile.id IS NOT NULL THEN
            follow_notification_type := CASE
                WHEN NEW.status = 'pending' THEN 'activitypub_follow_request'
                ELSE 'activitypub_follow'
            END;

            notification_data := jsonb_build_object(
                'type', follow_notification_type,
                'follower_id', NEW.follower_id,
                'follower', notification_actor_json(
                    follower_profile.id,
                    follower_profile.username,
                    follower_profile.display_name,
                    follower_profile.avatar_url,
                    follower_profile.domain,
                    follower_profile.is_local
                ),
                -- 'sender' alias: push payload builder reads data.sender for actor name/avatar
                'sender', notification_actor_json(
                    follower_profile.id,
                    follower_profile.username,
                    follower_profile.display_name,
                    follower_profile.avatar_url,
                    follower_profile.domain,
                    follower_profile.is_local
                )
            );

            PERFORM send_notification_to_user(
                follow_notification_type,
                NEW.following_id,
                notification_data,
                NULL, NULL, NULL,
                NEW.follower_id,
                'normal'
            );
        END IF;

    -- Follow request approved: notify the requester.
    -- OLD.status must only be referenced inside the follows-only branch: this
    -- function also fires for INSERTs on reactions/post_interactions, whose
    -- row types have no status column, and plpgsql resolves record fields in
    -- the ELSIF condition even when the table check is false (42703).
    ELSIF TG_TABLE_NAME = 'follows' AND TG_OP = 'UPDATE' THEN
      IF OLD.status = 'pending' AND NEW.status = 'accepted' THEN
        SELECT id, username, display_name, avatar_url, domain, is_local
        INTO follower_profile
        FROM profiles
        WHERE id = NEW.follower_id;

        -- Remote followers are notified by their own instance via the federated Accept
        IF follower_profile.id IS NOT NULL AND COALESCE(follower_profile.is_local, true) THEN
            SELECT id, username, display_name, avatar_url, domain, is_local
            INTO accepter_profile
            FROM profiles
            WHERE id = NEW.following_id;

            IF accepter_profile.id IS NOT NULL THEN
                notification_data := jsonb_build_object(
                    'type', 'activitypub_follow_accepted',
                    'followed_id', NEW.following_id,
                    'sender', notification_actor_json(
                        accepter_profile.id,
                        accepter_profile.username,
                        accepter_profile.display_name,
                        accepter_profile.avatar_url,
                        accepter_profile.domain,
                        accepter_profile.is_local
                    )
                );

                PERFORM send_notification_to_user(
                    'activitypub_follow_accepted',
                    NEW.follower_id,
                    notification_data,
                    NULL, NULL, NULL,
                    NEW.following_id,
                    'normal'
                );
            END IF;
        END IF;

      END IF;

    ELSIF TG_TABLE_NAME = 'reactions' AND TG_OP = 'INSERT' THEN
        SELECT user_id INTO single_target_id FROM messages WHERE id = NEW.message_id;
        
        IF single_target_id IS NOT NULL AND single_target_id != NEW.user_id THEN
            SELECT m.channel_id, c.server_id, m.conversation_id, c.name, s.name
            INTO msg_channel_id, msg_server_id, msg_conversation_id, msg_channel_name, msg_server_name
            FROM messages m 
            LEFT JOIN channels c ON m.channel_id = c.id
            LEFT JOIN servers s ON c.server_id = s.id
            WHERE m.id = NEW.message_id;
            
            SELECT id, username, display_name, avatar_url, domain, is_local
            INTO reactor_profile
            FROM profiles
            WHERE id = NEW.user_id;
            
            emoji_name := NULL;
            emoji_url := NULL;
            IF NEW.emoji_id IS NOT NULL THEN
                SELECT name, url INTO emoji_record FROM emojis WHERE id = NEW.emoji_id;
                IF FOUND THEN
                    emoji_name := emoji_record.name;
                    emoji_url := emoji_record.url;
                END IF;
            END IF;
            
            notification_data := jsonb_build_object(
                'type', 'reaction',
                'message_id', NEW.message_id,
                'channel_id', msg_channel_id,
                'server_id', msg_server_id,
                'channel_name', msg_channel_name,
                'server_name', msg_server_name,
                'message_preview', extract_message_text((SELECT content FROM messages WHERE id = NEW.message_id)),
                'reaction', jsonb_build_object(
                    'emoji_id', NEW.emoji_id,
                    'emoji_name', COALESCE(emoji_name, NEW.custom_emoji_content),
                    'emoji_url', emoji_url,
                    'custom_emoji_content', NEW.custom_emoji_content
                ),
                'sender', CASE WHEN reactor_profile.id IS NOT NULL THEN
                    notification_actor_json(
                        reactor_profile.id,
                        reactor_profile.username,
                        reactor_profile.display_name,
                        reactor_profile.avatar_url,
                        reactor_profile.domain,
                        reactor_profile.is_local
                    )
                ELSE NULL END
            );

            IF msg_conversation_id IS NOT NULL THEN
                notification_data := notification_data || jsonb_build_object(
                    'conversation_id', msg_conversation_id
                );
            END IF;
            
            PERFORM send_notification_to_user(
                'reaction',
                single_target_id,
                notification_data,
                msg_server_id, msg_channel_id, msg_conversation_id,
                NEW.user_id,
                'normal'
            );
        END IF;

    ELSIF TG_TABLE_NAME = 'post_interactions' AND TG_OP = 'INSERT' THEN
        IF NEW.interaction_type IN ('emoji_reaction', 'favorite', 'reblog') THEN
            SELECT author_id INTO post_author_id 
            FROM posts 
            WHERE id = NEW.post_id;
            
            IF post_author_id IS NOT NULL AND post_author_id != NEW.user_id THEN
                SELECT * INTO post_record FROM posts WHERE id = NEW.post_id;
                
                SELECT id, username, display_name, avatar_url, domain, is_local
                INTO reactor_profile
                FROM profiles
                WHERE id = NEW.user_id;
                
                emoji_name := NULL;
                emoji_url := NULL;
                IF NEW.emoji_id IS NOT NULL THEN
                    SELECT name, url INTO emoji_record FROM emojis WHERE id = NEW.emoji_id;
                    IF FOUND THEN
                        emoji_name := emoji_record.name;
                        emoji_url := emoji_record.url;
                    END IF;
                END IF;
                
                notification_data := jsonb_build_object(
                    'type', CASE
                        WHEN NEW.interaction_type = 'favorite' THEN 'activitypub_favorite'
                        WHEN NEW.interaction_type = 'reblog' THEN 'activitypub_reblog'
                        ELSE 'activitypub_reaction'
                    END,
                    'post_id', NEW.post_id,
                    'post', jsonb_build_object(
                        'id', post_record.id,
                        'content_preview', extract_message_text(post_record.content)
                    ),
                    'reaction', jsonb_build_object(
                        'emoji_id', NEW.emoji_id,
                        'emoji_name', COALESCE(emoji_name, NEW.custom_emoji_content),
                        'emoji_url', emoji_url,
                        'custom_emoji_content', NEW.custom_emoji_content
                    ),
                    'sender', CASE WHEN reactor_profile.id IS NOT NULL THEN
                        notification_actor_json(
                            reactor_profile.id,
                            reactor_profile.username,
                            reactor_profile.display_name,
                            reactor_profile.avatar_url,
                            reactor_profile.domain,
                            reactor_profile.is_local
                        )
                    ELSE NULL END
                );
                
                PERFORM send_notification_to_user(
                    CASE
                        WHEN NEW.interaction_type = 'favorite' THEN 'activitypub_favorite'
                        WHEN NEW.interaction_type = 'reblog' THEN 'activitypub_reblog'
                        ELSE 'activitypub_reaction'
                    END,
                    post_author_id,
                    notification_data,
                    NULL, NULL, NULL,
                    NEW.user_id,
                    'normal'
                );
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.handle_unified_notification_processing() IS 'Handles notifications for follows (follow vs follow_request based on status, follow_accepted on pending->accepted), reactions, and ActivityPub emoji reactions. Includes full reactor/sender profile in notification data for proper display.';

-- ---------------------------------------------------------------------------
-- clear_orphaned_public_keys - Clear public keys without matching private keys
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.clear_orphaned_public_keys()
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
    cleared_count INTEGER;
BEGIN
    UPDATE profiles p SET public_key = NULL
    WHERE p.is_local = true AND p.public_key IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM user_private_keys upk WHERE upk.user_id = p.id);
    GET DIAGNOSTICS cleared_count = ROW_COUNT;
    RETURN cleared_count;
END;
$$;

COMMENT ON FUNCTION public.clear_orphaned_public_keys() IS 'Clear public keys from local profiles that have no matching private key.';

-- ---------------------------------------------------------------------------
-- get_voice_channel_participants - Voice channel participants with user info
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_voice_channel_participants(p_channel_id UUID)
RETURNS TABLE (
    user_id UUID, username TEXT, display_name TEXT, avatar_url TEXT,
    is_federated BOOLEAN, federated_domain TEXT, joined_at TIMESTAMPTZ,
    is_muted BOOLEAN, is_deafened BOOLEAN, is_video_enabled BOOLEAN,
    is_screen_sharing BOOLEAN
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
BEGIN
    RETURN QUERY
    SELECT vcp.user_id, p.username, p.display_name, p.avatar_url,
        vcp.is_federated, p.domain AS federated_domain, vcp.joined_at,
        vcp.is_muted, vcp.is_deafened, vcp.is_video_enabled, vcp.is_screen_sharing
    FROM public.voice_channel_participants vcp
    JOIN public.profiles p ON p.id = vcp.user_id
    WHERE vcp.channel_id = p_channel_id
    ORDER BY vcp.joined_at ASC;
END;
$$;

-- ---------------------------------------------------------------------------
-- get_next_folder_position - Next available position for a server folder
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_next_folder_position(p_user_id UUID)
RETURNS INTEGER
LANGUAGE plpgsql STABLE
AS $$
DECLARE max_position INTEGER;
BEGIN
    SELECT COALESCE(MAX(position), -1) + 1 INTO max_position
    FROM server_folders WHERE user_id = p_user_id;
    RETURN max_position;
END;
$$;

-- ---------------------------------------------------------------------------
-- get_next_server_position - Next available position for a server in a folder
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_next_server_position(p_user_id UUID, p_folder_id UUID DEFAULT NULL)
RETURNS INTEGER
LANGUAGE plpgsql STABLE
AS $$
DECLARE max_position INTEGER;
BEGIN
    IF p_folder_id IS NULL THEN
        SELECT COALESCE(MAX(position), -1) + 1 INTO max_position
        FROM user_servers WHERE user_id = p_user_id AND folder_id IS NULL;
    ELSE
        SELECT COALESCE(MAX(position), -1) + 1 INTO max_position
        FROM user_servers WHERE user_id = p_user_id AND folder_id = p_folder_id;
    END IF;
    RETURN max_position;
END;
$$;

-- ---------------------------------------------------------------------------
-- record_metric - Record a raw performance metric
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.record_metric(
    p_metric_type text, p_metric_name text, p_value double precision,
    p_unit text DEFAULT 'ms', p_labels jsonb DEFAULT '{}'::jsonb,
    p_source text DEFAULT 'backend'
) RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE v_id uuid;
BEGIN
    INSERT INTO public.performance_metrics (
        metric_type, metric_name, value, unit, labels, source
    ) VALUES (
        p_metric_type, p_metric_name, p_value, p_unit, p_labels, p_source
    ) RETURNING id INTO v_id;
    RETURN v_id;
END;
$$;

-- ---------------------------------------------------------------------------
-- Server Moderation RPCs
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.get_user_highest_role_position(
    p_user_id uuid,
    p_server_id uuid
) RETURNS integer
LANGUAGE plpgsql STABLE SECURITY DEFINER
AS $$
DECLARE
    v_is_owner boolean;
    v_max_position integer;
BEGIN
    SELECT (owner = p_user_id) INTO v_is_owner
    FROM public.servers WHERE id = p_server_id;

    IF v_is_owner THEN
        RETURN 2147483647;
    END IF;

    SELECT COALESCE(MAX(sr.position), 0) INTO v_max_position
    FROM public.user_roles ur
    JOIN public.server_roles sr ON sr.id = ur.role_id
    WHERE ur.user_id = p_user_id
      AND ur.server_id = p_server_id;

    RETURN v_max_position;
END;
$$;

CREATE OR REPLACE FUNCTION public.kick_server_member(
    p_server_id uuid,
    p_user_id uuid,
    p_reason text DEFAULT NULL,
    p_delete_message_seconds integer DEFAULT 0
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_caller_id uuid;
    v_is_owner boolean;
    v_has_permission boolean;
    v_caller_position integer;
    v_target_position integer;
    v_target_is_owner boolean;
    v_deleted_count integer := 0;
    v_system_channel_id uuid;
BEGIN
    v_caller_id := public.get_current_profile_id();
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    IF v_caller_id = p_user_id THEN
        RAISE EXCEPTION 'Cannot kick yourself';
    END IF;

    SELECT (owner = p_user_id) INTO v_target_is_owner
    FROM public.servers WHERE id = p_server_id;
    IF v_target_is_owner THEN
        RAISE EXCEPTION 'Cannot kick the server owner';
    END IF;

    SELECT (owner = v_caller_id) INTO v_is_owner
    FROM public.servers WHERE id = p_server_id;

    IF NOT v_is_owner THEN
        SELECT COALESCE((public.get_user_permissions(v_caller_id, p_server_id)->>'KICK_MEMBERS')::boolean, false)
        INTO v_has_permission;
        IF NOT v_has_permission THEN
            RAISE EXCEPTION 'Missing KICK_MEMBERS permission';
        END IF;
    END IF;

    IF NOT v_is_owner THEN
        v_caller_position := public.get_user_highest_role_position(v_caller_id, p_server_id);
        v_target_position := public.get_user_highest_role_position(p_user_id, p_server_id);
        IF v_caller_position <= v_target_position THEN
            RAISE EXCEPTION 'Cannot kick a member with an equal or higher role';
        END IF;
    END IF;

    IF p_delete_message_seconds > 0 THEN
        UPDATE public.messages
        SET is_deleted = true, content = '[{"type":"text","content":"[message deleted]"}]'::jsonb
        WHERE user_id = p_user_id
          AND channel_id IN (SELECT id FROM public.channels WHERE server_id = p_server_id)
          AND created_at > now() - (p_delete_message_seconds || ' seconds')::interval
          AND is_deleted = false;
        GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    END IF;

    -- Suppress the "has left the server" trigger - we post "was kicked" below.
    PERFORM set_config('harmony.skip_leave_message', '1', true);

    DELETE FROM public.user_servers
    WHERE user_id = p_user_id AND server_id = p_server_id;

    INSERT INTO public.server_membership_events (server_id, user_id, event_type, payload)
    VALUES (p_server_id, p_user_id, 'kick', jsonb_build_object(
        'kicked_by', v_caller_id,
        'reason', COALESCE(p_reason, ''),
        'messages_deleted', v_deleted_count
    ));

    SELECT system_channel_id INTO v_system_channel_id
    FROM public.server_settings WHERE server_id = p_server_id;
    IF v_system_channel_id IS NULL THEN
        v_system_channel_id := public.get_default_channel(p_server_id);
    END IF;
    IF v_system_channel_id IS NOT NULL THEN
        INSERT INTO public.messages (channel_id, user_id, content, is_system, metadata)
        VALUES (
            v_system_channel_id,
            p_user_id,
            jsonb_build_array(jsonb_build_object('type', 'text', 'text', 'was kicked from the server')),
            true,
            jsonb_build_object('type', 'member_kick', 'kicked_by', v_caller_id, 'reason', COALESCE(p_reason, ''))
        );
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'messages_deleted', v_deleted_count
    );
END;
$$;

CREATE OR REPLACE FUNCTION public.ban_server_member(
    p_server_id uuid,
    p_user_id uuid,
    p_reason text DEFAULT NULL,
    p_delete_message_seconds integer DEFAULT 0
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_caller_id uuid;
    v_is_owner boolean;
    v_has_permission boolean;
    v_caller_position integer;
    v_target_position integer;
    v_target_is_owner boolean;
    v_deleted_count integer := 0;
    v_already_banned boolean;
    v_system_channel_id uuid;
BEGIN
    v_caller_id := public.get_current_profile_id();
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    IF v_caller_id = p_user_id THEN
        RAISE EXCEPTION 'Cannot ban yourself';
    END IF;

    SELECT (owner = p_user_id) INTO v_target_is_owner
    FROM public.servers WHERE id = p_server_id;
    IF v_target_is_owner THEN
        RAISE EXCEPTION 'Cannot ban the server owner';
    END IF;

    SELECT (owner = v_caller_id) INTO v_is_owner
    FROM public.servers WHERE id = p_server_id;

    IF NOT v_is_owner THEN
        SELECT COALESCE((public.get_user_permissions(v_caller_id, p_server_id)->>'BAN_MEMBERS')::boolean, false)
        INTO v_has_permission;
        IF NOT v_has_permission THEN
            RAISE EXCEPTION 'Missing BAN_MEMBERS permission';
        END IF;
    END IF;

    IF NOT v_is_owner THEN
        v_caller_position := public.get_user_highest_role_position(v_caller_id, p_server_id);
        v_target_position := public.get_user_highest_role_position(p_user_id, p_server_id);
        IF v_caller_position <= v_target_position THEN
            RAISE EXCEPTION 'Cannot ban a member with an equal or higher role';
        END IF;
    END IF;

    SELECT EXISTS(
        SELECT 1 FROM public.server_bans
        WHERE server_id = p_server_id AND user_id = p_user_id
    ) INTO v_already_banned;

    IF v_already_banned THEN
        RETURN jsonb_build_object('success', true, 'already_banned', true, 'messages_deleted', 0);
    END IF;

    IF p_delete_message_seconds > 0 THEN
        UPDATE public.messages
        SET is_deleted = true, content = '[{"type":"text","content":"[message deleted]"}]'::jsonb
        WHERE user_id = p_user_id
          AND channel_id IN (SELECT id FROM public.channels WHERE server_id = p_server_id)
          AND created_at > now() - (p_delete_message_seconds || ' seconds')::interval
          AND is_deleted = false;
        GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    END IF;

    INSERT INTO public.server_bans (server_id, user_id, banned_by, reason, delete_message_seconds)
    VALUES (p_server_id, p_user_id, v_caller_id, p_reason, p_delete_message_seconds);

    -- Suppress the "has left the server" trigger - we post "was banned" below.
    PERFORM set_config('harmony.skip_leave_message', '1', true);

    DELETE FROM public.user_servers
    WHERE user_id = p_user_id AND server_id = p_server_id;

    DELETE FROM public.user_roles
    WHERE user_id = p_user_id AND server_id = p_server_id;

    INSERT INTO public.server_membership_events (server_id, user_id, event_type, payload)
    VALUES (p_server_id, p_user_id, 'ban', jsonb_build_object(
        'banned_by', v_caller_id,
        'reason', COALESCE(p_reason, ''),
        'messages_deleted', v_deleted_count
    ));

    SELECT system_channel_id INTO v_system_channel_id
    FROM public.server_settings WHERE server_id = p_server_id;
    IF v_system_channel_id IS NULL THEN
        v_system_channel_id := public.get_default_channel(p_server_id);
    END IF;
    IF v_system_channel_id IS NOT NULL THEN
        INSERT INTO public.messages (channel_id, user_id, content, is_system, metadata)
        VALUES (
            v_system_channel_id,
            p_user_id,
            jsonb_build_array(jsonb_build_object('type', 'text', 'text', 'was banned from the server')),
            true,
            jsonb_build_object('type', 'member_ban', 'banned_by', v_caller_id, 'reason', COALESCE(p_reason, ''))
        );
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'messages_deleted', v_deleted_count
    );
END;
$$;

CREATE OR REPLACE FUNCTION public.unban_server_member(
    p_server_id uuid,
    p_user_id uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_caller_id uuid;
    v_is_owner boolean;
    v_has_permission boolean;
    v_ban_exists boolean;
BEGIN
    v_caller_id := public.get_current_profile_id();
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    SELECT (owner = v_caller_id) INTO v_is_owner
    FROM public.servers WHERE id = p_server_id;

    IF NOT v_is_owner THEN
        SELECT COALESCE((public.get_user_permissions(v_caller_id, p_server_id)->>'BAN_MEMBERS')::boolean, false)
        INTO v_has_permission;
        IF NOT v_has_permission THEN
            RAISE EXCEPTION 'Missing BAN_MEMBERS permission';
        END IF;
    END IF;

    SELECT EXISTS(
        SELECT 1 FROM public.server_bans
        WHERE server_id = p_server_id AND user_id = p_user_id
    ) INTO v_ban_exists;

    IF NOT v_ban_exists THEN
        RETURN jsonb_build_object('success', false, 'error', 'User is not banned');
    END IF;

    DELETE FROM public.server_bans
    WHERE server_id = p_server_id AND user_id = p_user_id;

    INSERT INTO public.server_membership_events (server_id, user_id, event_type, payload)
    VALUES (p_server_id, p_user_id, 'unban', jsonb_build_object(
        'unbanned_by', v_caller_id
    ));

    RETURN jsonb_build_object('success', true);
END;
$$;

CREATE OR REPLACE FUNCTION public.get_server_bans(
    p_server_id uuid
) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER
AS $$
DECLARE
    v_caller_id uuid;
    v_is_owner boolean;
    v_has_permission boolean;
    v_result jsonb;
BEGIN
    v_caller_id := public.get_current_profile_id();
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    SELECT (owner = v_caller_id) INTO v_is_owner
    FROM public.servers WHERE id = p_server_id;

    IF NOT v_is_owner THEN
        SELECT COALESCE((public.get_user_permissions(v_caller_id, p_server_id)->>'BAN_MEMBERS')::boolean, false)
        INTO v_has_permission;
        IF NOT v_has_permission THEN
            RAISE EXCEPTION 'Missing BAN_MEMBERS permission';
        END IF;
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', sb.id,
        'user_id', sb.user_id,
        'username', p.username,
        'display_name', p.display_name,
        'avatar_url', p.avatar_url,
        'banned_by', sb.banned_by,
        'banned_by_username', bp.username,
        'reason', sb.reason,
        'created_at', sb.created_at
    ) ORDER BY sb.created_at DESC), '[]'::jsonb) INTO v_result
    FROM public.server_bans sb
    JOIN public.profiles p ON p.id = sb.user_id
    LEFT JOIN public.profiles bp ON bp.id = sb.banned_by
    WHERE sb.server_id = p_server_id;

    RETURN v_result;
END;
$$;

-- ---------------------------------------------------------------------------
-- Featured Communities RPC
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.set_server_featured(
    p_server_id uuid,
    p_is_featured boolean,
    p_order integer DEFAULT 0
)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_caller_id uuid;
    v_is_admin boolean;
BEGIN
    v_caller_id := public.get_current_profile_id();
    IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    SELECT is_admin INTO v_is_admin
    FROM public.profiles WHERE id = v_caller_id;

    IF NOT COALESCE(v_is_admin, false) THEN
        RAISE EXCEPTION 'Only instance admins can manage featured communities';
    END IF;

    UPDATE public.servers
    SET is_featured = p_is_featured, featured_order = p_order
    WHERE id = p_server_id;
END;
$$;

-- ---------------------------------------------------------------------------
-- Admin System Health RPCs
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_db_connection_count()
RETURNS integer
LANGUAGE plpgsql STABLE SECURITY DEFINER
AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND is_admin = true) THEN
        RETURN 0;
    END IF;
    RETURN (SELECT COUNT(*)::integer FROM pg_stat_activity WHERE datname = current_database());
END;
$$;

CREATE OR REPLACE FUNCTION public.get_db_size()
RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER
AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND is_admin = true) THEN
        RETURN '--';
    END IF;
    RETURN (SELECT pg_size_pretty(pg_database_size(current_database())));
END;
$$;

CREATE OR REPLACE FUNCTION public.get_admin_user_counts(p_user_ids uuid[])
RETURNS TABLE(user_id uuid, post_count bigint, server_count bigint)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public
AS $$
  WITH post_counts AS (
    SELECT author_id, COUNT(*)::bigint AS cnt
    FROM public.posts
    WHERE author_id = ANY(p_user_ids) AND is_deleted = false
    GROUP BY author_id
  ),
  server_counts AS (
    SELECT user_id, COUNT(*)::bigint AS cnt
    FROM public.user_servers
    WHERE user_id = ANY(p_user_ids)
    GROUP BY user_id
  )
  SELECT
    id AS user_id,
    COALESCE(pc.cnt, 0) AS post_count,
    COALESCE(sc.cnt, 0) AS server_count
  FROM unnest(p_user_ids) AS id
  LEFT JOIN post_counts pc ON pc.author_id = id
  LEFT JOIN server_counts sc ON sc.user_id = id;
$$;

CREATE OR REPLACE FUNCTION public.get_server_member_counts(p_server_ids uuid[])
RETURNS TABLE(server_id uuid, member_count bigint)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public
AS $$
  WITH counts AS (
    SELECT server_id, COUNT(*)::bigint AS cnt
    FROM public.user_servers
    WHERE server_id = ANY(p_server_ids)
    GROUP BY server_id
  )
  SELECT id AS server_id, COALESCE(c.cnt, 0) AS member_count
  FROM unnest(p_server_ids) AS id
  LEFT JOIN counts c ON c.server_id = id;
$$;

-- ---------------------------------------------------------------------------
-- Announcements RPC
-- ---------------------------------------------------------------------------
-- Two-arg signature: `p_popup_only` lets callers (the AnnouncementPopup)
-- ask for the strictly popup-eligible subset. When true:
--   * `show_popup = true` is required (admin opt-out for popup display)
--   * `starts_at >= profiles.created_at` is required so brand-new users
--     don't get spammed with the entire historical backlog
--   * the result set is capped at 10 rows to protect long-absent users
-- When false (default), behaviour matches the original one-arg shape so
-- the Settings archive unread set and the sidebar unread count are
-- unaffected. See migration 20260526_announcements_popup_filter.sql.
CREATE OR REPLACE FUNCTION public.get_unread_announcements(
    p_user_id uuid,
    p_popup_only boolean DEFAULT false
)
RETURNS TABLE(
    id uuid,
    title text,
    content text,
    image_url text,
    icon text,
    is_pinned boolean,
    show_popup boolean,
    silence boolean,
    created_at timestamptz,
    author_id uuid,
    author_username text,
    author_display_name text,
    author_avatar_url text
)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
    WITH joined AS (
        SELECT COALESCE(
            (SELECT created_at FROM public.profiles WHERE id = p_user_id),
            'epoch'::timestamptz
        ) AS user_created_at
    )
    SELECT
        a.id, a.title, a.content, a.image_url, a.icon,
        a.is_pinned, a.show_popup, a.silence, a.created_at,
        a.author_id, p.username AS author_username,
        p.display_name AS author_display_name,
        p.avatar_url AS author_avatar_url
    FROM public.instance_announcements a
    LEFT JOIN public.profiles p ON p.id = a.author_id
    LEFT JOIN public.announcement_reads ar
        ON ar.announcement_id = a.id AND ar.user_id = p_user_id
    CROSS JOIN joined j
    WHERE a.is_active = true
      AND a.starts_at <= NOW()
      AND (a.ends_at IS NULL OR a.ends_at > NOW())
      AND ar.id IS NULL
      AND (
          NOT p_popup_only
          OR (
              a.show_popup = true
              AND a.starts_at >= j.user_created_at
          )
      )
    ORDER BY a.is_pinned DESC, a.display_order ASC, a.created_at DESC
    LIMIT CASE WHEN p_popup_only THEN 10 ELSE 1000 END;
$$;

-- ---------------------------------------------------------------------------
-- Federation: insert outbound AP activity (bypasses PostgREST schema cache)
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.insert_ap_activity_outbound(
    p_ap_id text,
    p_ap_type text,
    p_actor_id uuid,
    p_actor_ap_id text,
    p_activity_data jsonb,
    p_object_id text DEFAULT NULL,
    p_object_type text DEFAULT NULL,
    p_to_addresses text[] DEFAULT '{}'::text[],
    p_cc_addresses text[] DEFAULT '{}'::text[],
    p_origin_domain text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_activity_id uuid;
    v_caller_profile_id uuid;
BEGIN
    v_caller_profile_id := public.get_current_profile_id();
    IF v_caller_profile_id IS NULL OR v_caller_profile_id != p_actor_id THEN
        RAISE EXCEPTION 'Unauthorized: p_actor_id does not match the authenticated user';
    END IF;

    INSERT INTO ap_activities (
        ap_id, ap_type, actor_id, actor_ap_id, object_id, object_type,
        activity_data, status, is_local, to_addresses, cc_addresses, origin_domain
    ) VALUES (
        p_ap_id, p_ap_type, p_actor_id, p_actor_ap_id, p_object_id, p_object_type,
        p_activity_data, 'pending', true, p_to_addresses, p_cc_addresses, p_origin_domain
    )
    RETURNING id INTO v_activity_id;

    RETURN v_activity_id;
END;
$$;

-- ---------------------------------------------------------------------------
-- Federation: get or create federated group conversation
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_or_create_federated_group_conversation(
  p_actor_id uuid,
  p_local_recipient_ids uuid[],
  p_remote_conversation_id text DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_conversation_id uuid;
  v_participant_id uuid;
  v_all_ids uuid[];
BEGIN
  IF p_local_recipient_ids IS NULL OR array_length(p_local_recipient_ids, 1) < 1 THEN
    RAISE EXCEPTION 'At least 1 local recipient required';
  END IF;

  v_all_ids := ARRAY(SELECT DISTINCT unnest(p_local_recipient_ids || ARRAY[p_actor_id]) ORDER BY 1);

  IF p_remote_conversation_id IS NOT NULL THEN
    SELECT c.id INTO v_conversation_id
    FROM conversations c
    WHERE c.type = 'group'
      AND c.metadata->>'remote_conversation_id' = p_remote_conversation_id
    LIMIT 1;

    IF v_conversation_id IS NOT NULL THEN
      RETURN v_conversation_id;
    END IF;
  END IF;

  SELECT c.id INTO v_conversation_id
  FROM conversations c
  WHERE c.type = 'group'
    AND EXISTS (SELECT 1 FROM conversation_participants cp WHERE cp.conversation_id = c.id AND cp.user_id = p_actor_id AND cp.left_at IS NULL)
    AND (SELECT array_agg(cp.user_id ORDER BY cp.user_id) FROM conversation_participants cp WHERE cp.conversation_id = c.id AND cp.left_at IS NULL)
      = (SELECT array_agg(uid ORDER BY uid) FROM unnest(v_all_ids) uid)
  LIMIT 1;

  IF v_conversation_id IS NOT NULL THEN
    IF p_remote_conversation_id IS NOT NULL THEN
      UPDATE conversations
      SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('remote_conversation_id', p_remote_conversation_id)
      WHERE id = v_conversation_id
        AND (metadata IS NULL OR metadata->>'remote_conversation_id' IS NULL);
    END IF;
    RETURN v_conversation_id;
  END IF;

  INSERT INTO conversations (type, name, created_by, metadata)
  VALUES (
    'group',
    NULL,
    p_actor_id,
    CASE
      WHEN p_remote_conversation_id IS NOT NULL
      THEN jsonb_build_object('federated', true, 'remote_conversation_id', p_remote_conversation_id)
      ELSE '{"federated": true}'::jsonb
    END
  )
  RETURNING id INTO v_conversation_id;

  INSERT INTO conversation_participants (conversation_id, user_id, role)
  VALUES (v_conversation_id, p_actor_id, 'admin')
  ON CONFLICT (conversation_id, user_id) DO UPDATE SET left_at = NULL, role = 'admin';

  FOREACH v_participant_id IN ARRAY p_local_recipient_ids
  LOOP
    IF v_participant_id != p_actor_id THEN
      INSERT INTO conversation_participants (conversation_id, user_id, role)
      VALUES (v_conversation_id, v_participant_id, 'member')
      ON CONFLICT (conversation_id, user_id) DO UPDATE SET left_at = NULL, role = 'member';
    END IF;
  END LOOP;

  RETURN v_conversation_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_db_connection_count() TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_db_size() TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_admin_user_counts(uuid[]) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_server_member_counts(uuid[]) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_unread_announcements(uuid, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.insert_ap_activity_outbound(text, text, uuid, text, jsonb, text, text, text[], text[], text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.insert_ap_activity_outbound(text, text, uuid, text, jsonb, text, text, text[], text[], text) TO service_role;

-- ---------------------------------------------------------------------------
-- Function: check_and_increment_bot_rate_limit
--
-- Atomic per-(bot, bucket) rate-limit check + increment in one statement.
-- Replaces the previous read-modify-write pattern in
-- `bot-gateway/src/auth/BotAuthMiddleware.checkRateLimit()`, which was
-- documented as racy in BUGS.md M37: two concurrent requests could each
-- read `request_count = N`, each pass the `< max_requests` check, then
-- both write `N + 1` - letting through ~2× the allowed burst.
--
-- Behaviour:
--   - First request for a (bot, bucket) pair: INSERT with count=1, return false.
--   - Subsequent request within the window: UPDATE +1 atomically, return
--     true iff the post-increment count > p_limit.
--   - Subsequent request AFTER the window expired: reset count to 1 and
--     extend `resets_at`, return false.
--
-- Returns:
--   `true`  → caller MUST reject the request with HTTP 429.
--   `false` → caller may proceed.
--
-- Concurrency model:
--   INSERT ... ON CONFLICT ... DO UPDATE is atomic at the row level; the
--   UPDATE clause re-reads the conflicting row under an exclusive lock,
--   so the CASE expression sees a consistent snapshot. No race even
--   under thousands of concurrent calls for the same (bot, bucket).
--
-- The signature accepts `p_limit` and `p_window_seconds` so callers can
-- vary per-bucket. These are also persisted on the row (`max_requests`,
-- `window_duration_seconds`) for visibility, but the function uses the
-- parameters as the source of truth on this call - letting callers
-- change a bucket's limit without a separate migration.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.check_and_increment_bot_rate_limit(
    p_bot_id uuid,
    p_bucket text,
    p_limit integer DEFAULT 100,
    p_window_seconds integer DEFAULT 60
) RETURNS boolean
    LANGUAGE plpgsql
    SECURITY DEFINER
    SET search_path = public, pg_temp
AS $$
DECLARE
    v_count integer;
BEGIN
    INSERT INTO public.bot_rate_limits (
        bot_id, bucket,
        request_count, window_start, window_duration_seconds, max_requests, resets_at
    )
    VALUES (
        p_bot_id, p_bucket,
        1, NOW(), p_window_seconds, p_limit,
        NOW() + make_interval(secs => p_window_seconds)
    )
    ON CONFLICT (bot_id, bucket) DO UPDATE
        SET
            request_count = CASE
                WHEN public.bot_rate_limits.resets_at < NOW() THEN 1
                ELSE public.bot_rate_limits.request_count + 1
            END,
            window_start = CASE
                WHEN public.bot_rate_limits.resets_at < NOW() THEN NOW()
                ELSE public.bot_rate_limits.window_start
            END,
            window_duration_seconds = p_window_seconds,
            max_requests = p_limit,
            resets_at = CASE
                WHEN public.bot_rate_limits.resets_at < NOW() THEN NOW() + make_interval(secs => p_window_seconds)
                ELSE public.bot_rate_limits.resets_at
            END
    RETURNING request_count INTO v_count;

    RETURN v_count > p_limit;
END;
$$;

COMMENT ON FUNCTION public.check_and_increment_bot_rate_limit(uuid, text, integer, integer) IS
    'Atomic per-(bot, bucket) rate-limit check + increment. Returns true if the caller is rate-limited (HTTP 429), false otherwise. Fixes BUGS.md M37 race condition.';

-- The bot-gateway connects with the service role key, so only service_role
-- needs EXECUTE in normal operation. `authenticated` is granted as well
-- for any future server-side function that wants to call this from an
-- authenticated context.
GRANT EXECUTE ON FUNCTION public.check_and_increment_bot_rate_limit(uuid, text, integer, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.check_and_increment_bot_rate_limit(uuid, text, integer, integer) TO service_role;

-- ---------------------------------------------------------------------------
-- Function: lookup_invite_by_code (ported from
-- 20260520_invites_restrict_select_to_owner_and_rpc.sql - C10)
--
-- Single-code invite lookup for the accept / preview flows. SELECT on
-- public.invites is restricted to the creator and instance admins, so this
-- SECURITY DEFINER RPC is the only public path - one specific code per call,
-- no enumeration.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.lookup_invite_by_code(p_code text)
RETURNS TABLE (
    id uuid,
    code text,
    server_id uuid,
    created_by uuid,
    uses integer,
    max_uses integer,
    used boolean,
    temporary boolean,
    expires_at timestamptz,
    created_at timestamptz,
    server_name text,
    server_icon text
)
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = public, pg_temp
AS $$
    SELECT
        i.id,
        i.code,
        i.server_id,
        i.created_by,
        i.uses,
        i.max_uses,
        i.used,
        i.temporary,
        i.expires_at,
        i.created_at,
        s.name AS server_name,
        s.icon AS server_icon
    FROM public.invites i
    LEFT JOIN public.servers s ON s.id = i.server_id
    WHERE i.code = p_code
    LIMIT 1;
$$;

COMMENT ON FUNCTION public.lookup_invite_by_code(text) IS
    'Public-facing invite-code → invite-row lookup. Bypasses RLS so the accept-flow can validate an invite before the user joins. Single-row, no enumeration.';

GRANT EXECUTE ON FUNCTION public.lookup_invite_by_code(text) TO anon, authenticated;

-- ---------------------------------------------------------------------------
-- Function: redeem_recovery_code_and_disable_mfa (ported from
-- 20260703_recovery_code_mfa_unenroll_rpc.sql - C11)
--
-- Atomic recovery-code redemption: verifies AND consumes an unused recovery
-- code for the calling user, then removes their MFA factors server-side.
-- Replaces the client-side verify + AAL1 mfa.unenroll flow.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.redeem_recovery_code_and_disable_mfa(p_code text)
RETURNS boolean
    LANGUAGE plpgsql
    SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_user_id uuid;
  v_profile_id uuid;
  v_code_hash text;
  v_code_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: requires an authenticated session'
      USING ERRCODE = '42501';
  END IF;

  IF p_code IS NULL OR length(p_code) < 8 THEN
    RETURN false;
  END IF;

  -- mfa_recovery_codes.user_id FKs to profiles(id); save_recovery_codes
  -- writes rows under the PROFILE id, so the lookup must too (Pattern A).
  v_profile_id := public.get_current_profile_id();
  IF v_profile_id IS NULL THEN
    RETURN false;
  END IF;

  v_code_hash := encode(extensions.digest(p_code::bytea, 'sha256'), 'hex');

  UPDATE public.mfa_recovery_codes
  SET used_at = NOW()
  WHERE id = (
    SELECT id FROM public.mfa_recovery_codes
    WHERE user_id = v_profile_id
      AND code_hash = v_code_hash
      AND used_at IS NULL
    LIMIT 1
    FOR UPDATE SKIP LOCKED
  )
  RETURNING id INTO v_code_id;

  IF v_code_id IS NULL THEN
    RETURN false;
  END IF;

  DELETE FROM auth.mfa_factors WHERE user_id = v_user_id;

  RETURN true;
END;
$$;

REVOKE ALL ON FUNCTION public.redeem_recovery_code_and_disable_mfa(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.redeem_recovery_code_and_disable_mfa(text) TO authenticated;


-- ---------------------------------------------------------------------------
-- Function: delete_my_account (ported from 20260703_account_deletion_rpc.sql)
--
-- Self-service account deletion: MFA step-up enforced server-side, profile
-- anonymized to a tombstone (content keeps rendering as "Deleted User"),
-- personal data purged, auth.users row removed last.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.delete_my_account()
RETURNS jsonb
    LANGUAGE plpgsql
    SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_auth_id uuid;
  v_profile_id uuid;
  v_aal text;
  v_has_verified_mfa boolean;
  v_blocking_servers text[];
BEGIN
  v_auth_id := auth.uid();
  IF v_auth_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: requires an authenticated session'
      USING ERRCODE = '42501';
  END IF;

  -- MFA step-up gate (server-side, cannot be bypassed by a modified client).
  SELECT EXISTS (
    SELECT 1 FROM auth.mfa_factors
    WHERE user_id = v_auth_id AND status = 'verified'
  ) INTO v_has_verified_mfa;

  IF v_has_verified_mfa THEN
    v_aal := current_setting('request.jwt.claims', true)::jsonb ->> 'aal';
    IF v_aal IS DISTINCT FROM 'aal2' THEN
      RETURN jsonb_build_object('error', 'mfa_required');
    END IF;
  END IF;

  SELECT id INTO v_profile_id
  FROM public.profiles
  WHERE auth_user_id = v_auth_id;

  IF v_profile_id IS NOT NULL THEN
    -- Refuse while the caller owns servers that other people are members of.
    SELECT array_agg(s.name) INTO v_blocking_servers
    FROM public.servers s
    WHERE s.owner = v_profile_id
      AND EXISTS (
        SELECT 1 FROM public.user_servers us
        WHERE us.server_id = s.id
          AND us.user_id <> v_profile_id
      );

    IF v_blocking_servers IS NOT NULL AND array_length(v_blocking_servers, 1) > 0 THEN
      RETURN jsonb_build_object(
        'error', 'transfer_ownership_required',
        'servers', to_jsonb(v_blocking_servers)
      );
    END IF;

    -- Solo servers (caller is the only member) go away with the account.
    DELETE FROM public.servers s
    WHERE s.owner = v_profile_id;

    -- Purge personal data. Content tables (messages, posts, channels,
    -- conversations) are intentionally NOT touched - they keep pointing at
    -- the anonymized profile.
    DELETE FROM public.user_key_pairs        WHERE user_id = v_profile_id;
    DELETE FROM public.megolm_session_shares WHERE sender_user_id = v_profile_id OR recipient_user_id = v_profile_id;
    DELETE FROM public.megolm_key_requests   WHERE requester_user_id = v_profile_id OR sender_user_id = v_profile_id;
    DELETE FROM public.megolm_key_backups    WHERE user_id = v_profile_id;
    DELETE FROM public.recovery_key_metadata WHERE user_id = v_profile_id;
    DELETE FROM public.mfa_recovery_codes    WHERE user_id = v_profile_id;
    DELETE FROM public.follows               WHERE follower_id = v_profile_id OR following_id = v_profile_id;
    DELETE FROM public.timeline_entries      WHERE user_id = v_profile_id;
    DELETE FROM public.unread_counts         WHERE user_id = v_profile_id;
    DELETE FROM public.post_interactions     WHERE user_id = v_profile_id;
    DELETE FROM public.invites               WHERE created_by = v_profile_id;
    DELETE FROM public.user_servers          WHERE user_id = v_profile_id;

    -- Optional tables (deployments differ); ignore when absent.
    BEGIN
      DELETE FROM public.user_devices WHERE user_id = v_profile_id;
    EXCEPTION WHEN undefined_table THEN NULL;
    END;
    BEGIN
      DELETE FROM public.push_subscriptions WHERE user_id = v_profile_id;
    EXCEPTION WHEN undefined_table THEN NULL;
    END;
    BEGIN
      DELETE FROM public.notifications WHERE user_id = v_profile_id;
    EXCEPTION WHEN undefined_table THEN NULL;
    END;
    BEGIN
      DELETE FROM public.user_blocks WHERE blocker_id = v_profile_id OR blocked_user_id = v_profile_id;
    EXCEPTION WHEN undefined_table THEN NULL;
    END;
    BEGIN
      DELETE FROM public.user_private_keys WHERE user_id = v_profile_id;
    EXCEPTION WHEN undefined_table THEN NULL;
    END;

    -- Anonymize. auth_user_id = NULL detaches the row from auth.users BEFORE
    -- the auth delete below, so the CASCADE cannot reach it. The generated
    -- username satisfies profiles_username_check and is unique per domain.
    UPDATE public.profiles SET
      username = 'deleted_' || replace(substr(v_profile_id::text, 1, 13), '-', ''),
      display_name = 'Deleted User',
      avatar_url = '/default_avatar.webp',
      banner_url = NULL,
      bio = NULL,
      color = NULL,
      status = 0,
      custom_status = NULL,
      profile_fields = '[]'::jsonb,
      appearance_settings = NULL,
      public_key = NULL,
      federated_id = NULL,
      inbox_url = NULL,
      outbox_url = NULL,
      followers_url = NULL,
      following_url = NULL,
      featured_url = NULL,
      shared_inbox_url = NULL,
      federation_metadata = '{}'::jsonb,
      is_admin = false,
      is_moderator = false,
      federation_enabled = false,
      federation_discoverable = false,
      followers_count = 0,
      following_count = 0,
      auth_user_id = NULL,
      updated_at = now()
    WHERE id = v_profile_id;
  END IF;

  -- Finally remove the auth user. Cascades auth-side rows (sessions,
  -- identities, mfa_factors) via Supabase's own FKs.
  DELETE FROM auth.users WHERE id = v_auth_id;

  RETURN jsonb_build_object('success', true);
END;
$$;

REVOKE ALL ON FUNCTION public.delete_my_account() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.delete_my_account() TO authenticated;


-- ---------------------------------------------------------------------------
-- Added by migrations after init/ was written; mirrored back so a fresh
-- build carries them. Supporter tiers, donation totals, DM call finalisation,
-- conversation context and encryption-identity reset.
-- ---------------------------------------------------------------------------

-- Mirrored from migrations/20260524_cumulative_tier_and_notifications.sql.
CREATE OR REPLACE FUNCTION public.compute_supporter_tier_for_amount(
    p_amount numeric,
    p_currency text DEFAULT 'USD'
)
RETURNS uuid
LANGUAGE sql
STABLE
AS $$
    SELECT id
    FROM public.instance_supporter_tiers
    WHERE min_amount <= p_amount
    ORDER BY min_amount DESC
    LIMIT 1;
$$;

-- Mirrored from migrations/20260704_finalize_dm_call_message.sql.
CREATE OR REPLACE FUNCTION public.finalize_dm_call_message(
    p_message_id uuid,
    p_ended_at timestamptz,
    p_duration_seconds integer,
    p_participants uuid[]
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_msg record;
    v_profile_id uuid;
BEGIN
    SELECT id, conversation_id, metadata
    INTO v_msg
    FROM messages
    WHERE id = p_message_id
      AND is_system = true
      AND conversation_id IS NOT NULL;

    IF NOT FOUND THEN
        RETURN;
    END IF;

    -- Idempotent: first finalizer wins, later calls are no-ops
    IF v_msg.metadata->>'type' = 'call_ended' THEN
        RETURN;
    END IF;

    IF v_msg.metadata->>'type' IS DISTINCT FROM 'call_started' THEN
        RAISE EXCEPTION 'message is not a call system message';
    END IF;

    SELECT id INTO v_profile_id
    FROM profiles
    WHERE auth_user_id = auth.uid();

    IF v_profile_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM conversation_participants cp
        WHERE cp.conversation_id = v_msg.conversation_id
          AND cp.user_id = v_profile_id
          AND cp.left_at IS NULL
    ) THEN
        RAISE EXCEPTION 'not a participant of this conversation';
    END IF;

    UPDATE messages
    SET metadata = jsonb_build_object(
            'type', 'call_ended',
            'call_type', v_msg.metadata->>'call_type',
            'started_at', v_msg.metadata->>'started_at',
            'ended_at', p_ended_at,
            'duration_seconds', p_duration_seconds,
            'participants', to_jsonb(p_participants)
        ),
        updated_at = now()
    WHERE id = p_message_id;
END;
$$;

-- Mirrored from migrations/20260315_fix_favorited_reply_notifications_mentions.sql.
CREATE OR REPLACE FUNCTION public.get_conversation_context(in_post_id uuid, in_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_conversation_root_id uuid;
    result jsonb;
BEGIN
    SELECT COALESCE(p.conversation_root_id, p.id)
    INTO v_conversation_root_id
    FROM posts p
    WHERE p.id = in_post_id
      AND p.deleted_at IS NULL;
    
    IF v_conversation_root_id IS NULL THEN
        RETURN '{}'::jsonb;
    END IF;
    
    WITH conversation_posts AS (
        SELECT 
            p.id,
            p.content,
            p.created_at,
            p.in_reply_to,
            jsonb_build_object(
                'id', pr.id,
                'username', pr.username,
                'display_name', pr.display_name,
                'avatar_url', pr.avatar_url,
                'domain', pr.domain
            ) as author,
            p.visibility,
            p.favorites_count,
            p.reblogs_count,
            p.replies_count,
            p.media_attachments,
            p.content_warning,
            p.is_sensitive,
            p.url,
            CASE 
                WHEN pi_fav.user_id IS NOT NULL THEN true 
                ELSE false 
            END as is_favorited,
            CASE 
                WHEN pi_reb.user_id IS NOT NULL THEN true 
                ELSE false 
            END as is_reblogged,
            CASE 
                WHEN pi_book.user_id IS NOT NULL THEN true 
                ELSE false 
            END as is_bookmarked
        FROM posts p
        JOIN profiles pr ON p.author_id = pr.id
        LEFT JOIN post_interactions pi_fav ON p.id = pi_fav.post_id 
            AND pi_fav.user_id = in_user_id 
            AND pi_fav.interaction_type IN ('favorite', 'emoji_reaction')
        LEFT JOIN post_interactions pi_reb ON p.id = pi_reb.post_id 
            AND pi_reb.user_id = in_user_id 
            AND pi_reb.interaction_type = 'reblog'
        LEFT JOIN post_interactions pi_book ON p.id = pi_book.post_id 
            AND pi_book.user_id = in_user_id 
            AND pi_book.interaction_type = 'bookmark'
        WHERE COALESCE(p.conversation_root_id, p.id) = v_conversation_root_id
          AND p.deleted_at IS NULL
        ORDER BY p.created_at ASC
    )
    SELECT jsonb_build_object(
        'ancestors', COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', cp.id,
                'content', cp.content,
                'created_at', cp.created_at,
                'author', cp.author,
                'visibility', cp.visibility,
                'favorites_count', cp.favorites_count,
                'reblogs_count', cp.reblogs_count,
                'replies_count', cp.replies_count,
                'media_attachments', cp.media_attachments,
                'content_warning', cp.content_warning,
                'is_sensitive', cp.is_sensitive,
                'url', cp.url,
                'is_favorited', cp.is_favorited,
                'is_reblogged', cp.is_reblogged,
                'is_bookmarked', cp.is_bookmarked
            )
        ) FILTER (WHERE cp.created_at < (SELECT created_at FROM posts WHERE id = in_post_id)), '[]'::jsonb),
        'descendants', COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', cp.id,
                'content', cp.content,
                'created_at', cp.created_at,
                'author', cp.author,
                'visibility', cp.visibility,
                'favorites_count', cp.favorites_count,
                'reblogs_count', cp.reblogs_count,
                'replies_count', cp.replies_count,
                'media_attachments', cp.media_attachments,
                'content_warning', cp.content_warning,
                'is_sensitive', cp.is_sensitive,
                'url', cp.url,
                'is_favorited', cp.is_favorited,
                'is_reblogged', cp.is_reblogged,
                'is_bookmarked', cp.is_bookmarked
            )
        ) FILTER (WHERE cp.created_at > (SELECT created_at FROM posts WHERE id = in_post_id)), '[]'::jsonb),
        'conversation_id', v_conversation_root_id
    ) INTO result
    FROM conversation_posts cp;
    
    RETURN COALESCE(result, jsonb_build_object(
        'ancestors', '[]'::jsonb,
        'descendants', '[]'::jsonb,
        'conversation_id', v_conversation_root_id
    ));
END;
$$;

-- Mirrored from migrations/20260705_supporter_badge_rolling_expiry.sql.
CREATE OR REPLACE FUNCTION public.get_user_cycle_donation_total(p_user_id uuid)
RETURNS numeric
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_period text;
    v_total numeric;
BEGIN
    SELECT COALESCE(funding_period, 'monthly') INTO v_period
    FROM public.instance_funding LIMIT 1;

    IF v_period = 'all' THEN
        SELECT COALESCE(SUM(amount), 0) INTO v_total
        FROM public.instance_donation_history
        WHERE user_id = p_user_id;
    ELSE
        SELECT COALESCE(SUM(amount), 0) INTO v_total
        FROM public.instance_donation_history
        WHERE user_id = p_user_id
          AND donated_at >= now() - interval '30 days';
    END IF;

    RETURN v_total;
END;
$$;

-- Mirrored from migrations/20260705_supporter_badge_rolling_expiry.sql.
CREATE OR REPLACE FUNCTION public.recompute_supporter_tier(p_user_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_period text;
    v_total numeric;
    v_tier_id uuid;
    v_currency text;
    v_expires timestamptz;
BEGIN
    -- No supporter row yet -> nothing to recompute (manual or webhook
    -- callers create the row before invoking this).
    IF NOT EXISTS (SELECT 1 FROM public.instance_supporters WHERE user_id = p_user_id) THEN
        RETURN NULL;
    END IF;

    SELECT COALESCE(funding_period, 'monthly'), COALESCE(goal_currency, 'USD')
      INTO v_period, v_currency
    FROM public.instance_funding LIMIT 1;

    v_total := public.get_user_cycle_donation_total(p_user_id);
    v_tier_id := public.compute_supporter_tier_for_amount(v_total, v_currency);

    IF v_period = 'all' THEN
        v_expires := NULL;
    ELSE
        -- Latest donation + 30 days. If the user has no donation history the
        -- window is NULL, which the badge query treats as "no expiry"; that is
        -- only reachable for manually-granted supporters (no donation rows),
        -- which are intentionally left permanent.
        SELECT MAX(donated_at) + interval '30 days'
          INTO v_expires
        FROM public.instance_donation_history
        WHERE user_id = p_user_id;
    END IF;

    UPDATE public.instance_supporters
    SET tier_id = v_tier_id,
        amount = v_total,
        expires_at = v_expires
    WHERE user_id = p_user_id;

    RETURN v_tier_id;
END;
$$;

-- Mirrored from migrations/20260531_reset_encryption_identity_rpc.sql.
CREATE OR REPLACE FUNCTION public.reset_my_encryption_identity()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_profile_id uuid;
BEGIN
    SELECT id INTO v_profile_id
    FROM public.profiles
    WHERE auth_user_id = auth.uid();

    IF v_profile_id IS NULL THEN
        RAISE EXCEPTION 'No profile for current user';
    END IF;

    -- The identity itself. Removing ALL rows (not just is_active) clears any
    -- stale/duplicate rows from earlier setups so the next setup is clean.
    DELETE FROM public.user_key_pairs WHERE user_id = v_profile_id;

    -- Dependent encryption state. Guarded individually so a missing table or
    -- column on a given deploy doesn't abort the whole reset.
    BEGIN
        DELETE FROM public.megolm_session_shares
        WHERE sender_user_id = v_profile_id OR recipient_user_id = v_profile_id;
    EXCEPTION WHEN undefined_table OR undefined_column THEN NULL;
    END;

    BEGIN
        DELETE FROM public.megolm_key_backups WHERE user_id = v_profile_id;
    EXCEPTION WHEN undefined_table OR undefined_column THEN NULL;
    END;

    BEGIN
        DELETE FROM public.megolm_key_requests
        WHERE sender_user_id = v_profile_id OR user_id = v_profile_id;
    EXCEPTION WHEN undefined_table OR undefined_column THEN NULL;
    END;

    BEGIN
        DELETE FROM public.recovery_key_metadata WHERE user_id = v_profile_id;
    EXCEPTION WHEN undefined_table OR undefined_column THEN NULL;
    END;

    BEGIN
        DELETE FROM public.user_devices WHERE user_id = v_profile_id;
    EXCEPTION WHEN undefined_table OR undefined_column THEN NULL;
    END;
END;
$$;


-- ---------------------------------------------------------------------------
-- Called by the application, present only in production
-- ---------------------------------------------------------------------------
-- These seven exist in no migration and in no init file. They were applied to
-- production by hand and never captured, so a fresh install answered "function
-- does not exist" for push delivery, bot authentication, session checks and
-- server-member lookup. Bodies are taken verbatim from a production dump.
--
-- scripts/check-rpc-coverage.sh now fails when the application calls an RPC a
-- fresh init/ build does not define.
-- ---------------------------------------------------------------------------

-- Mirrored from production.
CREATE OR REPLACE FUNCTION public.get_server_members_by_instance(p_server_id uuid) RETURNS TABLE(instance text, member_ids uuid[], member_ap_ids text[], member_count integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT 
    COALESCE(p.domain, 'local') as instance,
    array_agg(p.id) as member_ids,
    array_agg(p.federated_id) as member_ap_ids,
    COUNT(*)::INT as member_count
  FROM user_servers us
  JOIN profiles p ON us.user_id = p.id
  WHERE us.server_id = p_server_id
  GROUP BY COALESCE(p.domain, 'local');
$$;

-- Mirrored from production.
CREATE OR REPLACE FUNCTION public.get_user_push_subscriptions(p_user_id uuid) RETURNS TABLE(subscription_id uuid, endpoint text, p256dh text, auth text, push_enabled boolean, push_offline_only boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        ps.id as subscription_id,
        ps.endpoint,
        ps.p256dh,
        ps.auth,
        COALESCE(np.push_notifications, true) as push_enabled,
        COALESCE(np.push_offline_only, true) as push_offline_only
    FROM public.push_subscriptions ps
    LEFT JOIN public.notification_preferences np ON np.user_id = ps.user_id
    WHERE ps.user_id = p_user_id
    AND ps.failure_count < 5;  -- Skip subscriptions that have failed too many times
END;
$$;

-- Mirrored from production.
CREATE OR REPLACE FUNCTION public.has_active_session(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM public.user_sessions
        WHERE user_id = p_user_id
        AND is_active = true
        AND last_heartbeat > now() - interval '90 seconds'
    );
$$;

-- Mirrored from production.
CREATE OR REPLACE FUNCTION public.is_user_viewing_push_context(p_user_id uuid, p_server_id uuid DEFAULT NULL::uuid, p_channel_id uuid DEFAULT NULL::uuid, p_conversation_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM public.user_sessions
        WHERE user_id = p_user_id
        AND is_active = true
        AND last_heartbeat > now() - interval '90 seconds'
        AND (
            (p_conversation_id IS NOT NULL AND current_conversation_id = p_conversation_id)
            OR (p_channel_id IS NOT NULL AND current_channel_id = p_channel_id)
            OR (p_server_id IS NOT NULL AND current_server_id = p_server_id AND p_channel_id IS NULL)
        )
    );
$$;

-- Mirrored from production.
CREATE OR REPLACE FUNCTION public.record_push_failure(p_subscription_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
    UPDATE public.push_subscriptions
    SET 
        failure_count = failure_count + 1,
        last_failure_at = now(),
        last_failure_reason = p_reason
    WHERE id = p_subscription_id;
$$;

-- Mirrored from production.
CREATE OR REPLACE FUNCTION public.record_push_success(p_subscription_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
    UPDATE public.push_subscriptions
    SET 
        last_successful_push = now(),
        failure_count = 0,
        last_failure_at = NULL,
        last_failure_reason = NULL
    WHERE id = p_subscription_id;
$$;

-- Mirrored from production.
CREATE OR REPLACE FUNCTION public.verify_bot_token(p_token_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_bot_token public.bot_tokens;
    v_bot public.bots;
    v_result JSONB;
BEGIN
    -- Find active token
    SELECT * INTO v_bot_token
    FROM public.bot_tokens
    WHERE token_hash = p_token_hash
        AND is_active = true
        AND (expires_at IS NULL OR expires_at > NOW());
    
    IF v_bot_token IS NULL THEN
        RETURN jsonb_build_object('valid', false, 'error', 'Invalid or expired token');
    END IF;
    
    -- Get bot details
    SELECT * INTO v_bot
    FROM public.bots
    WHERE id = v_bot_token.bot_id
        AND is_active = true;
    
    IF v_bot IS NULL THEN
        RETURN jsonb_build_object('valid', false, 'error', 'Bot not found or inactive');
    END IF;
    
    -- Update last used
    UPDATE public.bot_tokens
    SET last_used_at = NOW(),
        uses_count = uses_count + 1
    WHERE id = v_bot_token.id;
    
    -- Return bot info
    v_result := jsonb_build_object(
        'valid', true,
        'bot_id', v_bot.id,
        'username', v_bot.username,
        'scopes', v_bot_token.scopes
    );
    
    RETURN v_result;
END;
$$;

-- ==== 14_indexes_perf.sql ====
-- ===========================================================================
-- Performance indexes (BUGS.md PH1, addendum 2026-05-20)
-- ===========================================================================
--
-- This file ports indexes that exist in production (per
-- db_schema/latest_dev_backup.sql) but were missing from init/. They were
-- verified against actual query usage in src/, federation-backend/src/,
-- and bot-gateway/src/ before being added - see the investigation in
-- BUGS.md addendum. Indexes that only appear in the prod dump but have no
-- code consumers (mostly legacy pgboss runtime tables and abandoned
-- features) are NOT ported here.
--
-- Each index is wrapped in `IF NOT EXISTS` so this file is idempotent and
-- safe to re-run.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- profiles (federation lookup hot paths)
-- ---------------------------------------------------------------------------

-- NOTE: We do NOT add `idx_profiles_auth_user_id` here. The
-- `auth_user_id uuid UNIQUE` column-level constraint on `profiles`
-- (db_schema/init/02_tables_core.sql:59) already creates an implicit
-- btree index that `.eq('auth_user_id', ...)` queries use. Adding a
-- second non-unique index on the same column would just double WAL
-- writes per profile mutation with no planner benefit. The
-- `idx_profiles_auth_user_id` and `idx_profiles_auth_user_id_unique`
-- present in `latest_dev_backup.sql` are prod-drift artifacts, not
-- something to mirror.

-- "all local profiles" queries during federation outbound delivery.
CREATE INDEX IF NOT EXISTS idx_profiles_federation_enabled
  ON public.profiles (id) WHERE is_local = true;

-- Federation discovery / actor refresh: filter by domain among
-- federation-enabled remote profiles.
CREATE INDEX IF NOT EXISTS idx_profiles_federation_lookup
  ON public.profiles (domain, federation_enabled)
  WHERE federation_enabled = true;

-- ---------------------------------------------------------------------------
-- posts (timeline hot paths)
-- ---------------------------------------------------------------------------

-- Author post counts excluding tombstones.
CREATE INDEX IF NOT EXISTS idx_posts_author_count
  ON public.posts (author_id) WHERE deleted_at IS NULL;

-- Federated timeline: public, non-local, top-level, not deleted, newest first.
-- This is the bread-and-butter timeline query for federated views.
CREATE INDEX IF NOT EXISTS idx_posts_federated_timeline
  ON public.posts (created_at DESC)
  WHERE is_local = false
    AND visibility = 'public'
    AND (is_deleted = false OR is_deleted IS NULL)
    AND deleted_at IS NULL
    AND in_reply_to IS NULL;

-- Local-vs-federated split for "local-only" and "all" timelines.
CREATE INDEX IF NOT EXISTS idx_posts_local_public_created_at
  ON public.posts (is_local, created_at DESC)
  WHERE visibility = 'public' AND NOT COALESCE(is_deleted, false);

-- Legacy timeline indexes used by some RPC paths. Names retained from the
-- prod dump for compatibility with any code that references them by name.
CREATE INDEX IF NOT EXISTS timeline_posts_local_created_idx
  ON public.posts (is_local, created_at DESC)
  WHERE is_deleted = false AND visibility = 'public';

CREATE INDEX IF NOT EXISTS timeline_posts_visibility_created_idx
  ON public.posts (visibility, created_at DESC)
  WHERE is_deleted = false;

-- Orphan-reply relink lookup (federation context fixes, 2026-05-21):
-- ActivityProcessor.relinkPendingChildren queries for orphaned replies
-- whose parent's ap_id we just imported. The set of orphaned replies is
-- always a small fraction of `posts`, so a partial expression index keeps
-- the index tiny and the lookup O(log n). See
-- migrations/20260521_orphan_reply_relink_index.sql for the rollout note.
CREATE INDEX IF NOT EXISTS idx_posts_pending_in_reply_to_ap_url
  ON public.posts ((metadata->>'in_reply_to_ap_url'))
  WHERE in_reply_to IS NULL
    AND (is_deleted = false OR is_deleted IS NULL)
    AND metadata ? 'in_reply_to_ap_url';

-- ---------------------------------------------------------------------------
-- messages (bot/channel/federation hot paths)
-- ---------------------------------------------------------------------------

-- Bot-authored message lookups. The init script had no index on
-- `messages.bot_id`, so every `.eq('bot_id', botId)` in BotRestAPI hit a
-- sequential scan once messages table grew.
CREATE INDEX IF NOT EXISTS idx_messages_bot_id
  ON public.messages (bot_id) WHERE bot_id IS NOT NULL;

-- Composite for "this bot's messages in this channel" lookups.
CREATE INDEX IF NOT EXISTS idx_messages_bot_channel
  ON public.messages (bot_id, channel_id) WHERE bot_id IS NOT NULL;

-- NOTE: We previously ported `idx_messages_encrypted` and
-- `idx_messages_megolm_session` from the prod dump on the assumption
-- that they had code consumers. A second-pass code audit found NO
-- `.eq('encrypted', ...)` or `.eq('megolm_session_id', ...)` filter
-- usage anywhere in `src/`, `federation-backend/src/`, or
-- `bot-gateway/src/` - the `encrypted` column is only ever set/read via
-- `SELECT *`, never as a WHERE-filter predicate. Both indexes were
-- dev-backup-only artifacts and are intentionally NOT ported here.

-- Federation worker scans for pending DM federation.
CREATE INDEX IF NOT EXISTS idx_messages_federation_pending
  ON public.messages (federation_status, created_at)
  WHERE federation_status = 'pending' AND conversation_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- reactions (bot + user lookup hot paths)
-- ---------------------------------------------------------------------------

-- Mirror of messages.bot_id situation: bots react to messages and we
-- look up reactions by bot.
CREATE INDEX IF NOT EXISTS idx_reactions_bot_id
  ON public.reactions (bot_id);

-- Composite partial for bot reactions on a specific message.
CREATE INDEX IF NOT EXISTS idx_reactions_bot_message
  ON public.reactions (bot_id, message_id) WHERE bot_id IS NOT NULL;

-- Has-current-user-reacted lookup (CoreMessageService.ts:636).
CREATE INDEX IF NOT EXISTS idx_reactions_user_message
  ON public.reactions (user_id, message_id);

-- NOTE: `idx_reactions_metadata` (GIN on jsonb) is intentionally NOT
-- ported. The second-pass audit found the only `.contains('metadata', ...)`
-- predicate in the codebase is on the `messages` table, not `reactions`
-- (federation-backend/src/activitypub/ActivityProcessor.ts:3042).
-- The agent's original justification referenced a `reactionHandler.ts:1263`
-- that does not exist in the current tree.

-- ---------------------------------------------------------------------------
-- ap_activities (federation worker hot paths)
-- ---------------------------------------------------------------------------

-- Worker pulls pending/processing activities ordered by time.
CREATE INDEX IF NOT EXISTS idx_ap_activities_federation_status
  ON public.ap_activities (status, is_local, created_at)
  WHERE status IN ('pending', 'processing');

-- Origin-domain filter for per-instance auditing / rate limiting joins.
CREATE INDEX IF NOT EXISTS idx_ap_activities_origin_domain
  ON public.ap_activities (origin_domain);

-- Status+type composite for the worker's "next of kind" scan.
CREATE INDEX IF NOT EXISTS idx_ap_activities_status_type
  ON public.ap_activities (status, ap_type) WHERE status = 'pending';

-- ---------------------------------------------------------------------------
-- notifications (filter + cleanup)
-- ---------------------------------------------------------------------------

-- Cleanup job that drops expired toast/transient notifications.
CREATE INDEX IF NOT EXISTS idx_notifications_expires_at
  ON public.notifications (expires_at);

-- Type filtering (useNotification.ts:326,332,338,344 build per-type
-- badges and tabs). The existing `idx_notifications_unread` is partial
-- on (user_id, is_read) and doesn't help with type filtering.
CREATE INDEX IF NOT EXISTS idx_notifications_type
  ON public.notifications (type);

-- ---------------------------------------------------------------------------
-- messages (slowmode last-message lookup)
-- ---------------------------------------------------------------------------

-- enforce_channel_slowmode() checks the author's most recent message per
-- channel on every insert into a slowmode channel.
CREATE INDEX IF NOT EXISTS idx_messages_channel_user_created
  ON public.messages (channel_id, user_id, created_at DESC)
  WHERE channel_id IS NOT NULL;

DO $$
BEGIN
  RAISE NOTICE 'Performance indexes (PH1) installed';
END $$;

-- Home/profile timeline paging: filter by owner and timeline type, order by
-- position descending. Mirrored from
-- migrations/20260319_add_composite_indexes.sql.
CREATE INDEX IF NOT EXISTS idx_timeline_entries_user_type_position
    ON public.timeline_entries USING btree (user_id, timeline_type, "position" DESC);

-- ==== 30_rls_policies.sql ====
-- =============================================================================
-- Harmony Database Schema - Row Level Security Policies
-- =============================================================================
-- RLS ensures users can only access their own data
-- =============================================================================

-- Helper function to get current user's profile ID
CREATE OR REPLACE FUNCTION public.get_current_profile_id()
RETURNS uuid
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    SELECT id FROM public.profiles WHERE auth_user_id = auth.uid() LIMIT 1;
$$;

-- ---------------------------------------------------------------------------
-- PROFILES RLS
-- ---------------------------------------------------------------------------
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;

CREATE POLICY "profiles_select_all" ON public.profiles
    FOR SELECT USING (true);

CREATE POLICY "profiles_insert_own" ON public.profiles
    FOR INSERT WITH CHECK (auth_user_id = ( SELECT auth.uid() ));

CREATE POLICY "profiles_update_own" ON public.profiles
    FOR UPDATE USING (auth_user_id = ( SELECT auth.uid() ));

CREATE POLICY "profiles_delete_own" ON public.profiles
    FOR DELETE USING (auth_user_id = ( SELECT auth.uid() ));

-- ---------------------------------------------------------------------------
-- POSTS RLS
-- ---------------------------------------------------------------------------
ALTER TABLE public.posts ENABLE ROW LEVEL SECURITY;

-- Public posts are visible to everyone, followers-only to followers
-- Also prevents blocked users from seeing posts from users who blocked them
CREATE POLICY "posts_select_public" ON public.posts
    FOR SELECT USING (
        -- Author can always see their own posts
        author_id = ( SELECT public.get_current_profile_id() )
        OR (
            -- Not blocked by the author AND not blocked by you
            NOT public.is_blocked_by(author_id)
            AND NOT public.has_blocked(author_id)
            AND (
                -- Public/unlisted posts
                visibility IN ('public', 'unlisted')
                -- Followers-only if user follows author
                OR (visibility = 'followers' AND EXISTS (
                    SELECT 1 FROM public.follows 
                    WHERE follower_id = ( SELECT public.get_current_profile_id() ) 
                    AND following_id = posts.author_id 
                    AND status = 'accepted'
                ))
                -- Direct messages (simplified check)
                OR (visibility = 'direct' AND EXISTS (
                    SELECT 1 WHERE author_id = ( SELECT public.get_current_profile_id() )
                ))
            )
        )
    );

CREATE POLICY "posts_insert_own" ON public.posts
    FOR INSERT WITH CHECK (author_id = ( SELECT public.get_current_profile_id() ));

CREATE POLICY "posts_update_own" ON public.posts
    FOR UPDATE USING (author_id = ( SELECT public.get_current_profile_id() ));

CREATE POLICY "posts_delete_own" ON public.posts
    FOR DELETE USING (author_id = ( SELECT public.get_current_profile_id() ));

-- ---------------------------------------------------------------------------
-- FOLLOWS RLS
-- ---------------------------------------------------------------------------
ALTER TABLE public.follows ENABLE ROW LEVEL SECURITY;

CREATE POLICY "follows_select_all" ON public.follows
    FOR SELECT USING (true);

CREATE POLICY "follows_insert_own" ON public.follows
    FOR INSERT WITH CHECK (follower_id = ( SELECT public.get_current_profile_id() ));

CREATE POLICY "follows_update_involved" ON public.follows
    FOR UPDATE USING (
        follower_id = ( SELECT public.get_current_profile_id() )
        OR following_id = ( SELECT public.get_current_profile_id() )
    );

CREATE POLICY "follows_delete_own" ON public.follows
    FOR DELETE USING (follower_id = ( SELECT public.get_current_profile_id() ));

-- ---------------------------------------------------------------------------
-- POST INTERACTIONS RLS
-- ---------------------------------------------------------------------------
ALTER TABLE public.post_interactions ENABLE ROW LEVEL SECURITY;

CREATE POLICY "post_interactions_select_all" ON public.post_interactions
    FOR SELECT USING (true);

-- Prevent reactions on posts from users who blocked you
CREATE POLICY "post_interactions_insert_own" ON public.post_interactions
    FOR INSERT WITH CHECK (
        user_id = ( SELECT public.get_current_profile_id() )
        AND NOT public.is_blocked_by((SELECT author_id FROM public.posts WHERE id = post_interactions.post_id))
    );

CREATE POLICY "post_interactions_delete_own" ON public.post_interactions
    FOR DELETE USING (user_id = ( SELECT public.get_current_profile_id() ));

-- ---------------------------------------------------------------------------
-- SERVERS RLS
-- ---------------------------------------------------------------------------
-- Note: servers.owner references profiles.id, not auth.uid() directly.
-- Update/delete policies must join through profiles to verify ownership.
ALTER TABLE public.servers ENABLE ROW LEVEL SECURITY;

-- Allow all users to read servers (visibility is handled at app level)
CREATE POLICY "Enable read access for all users" ON public.servers
    FOR SELECT USING (true);

-- Allow authenticated users to create servers they own (mirrors the update
-- policy's ownership check; servers.owner FK -> profiles.id).
CREATE POLICY "Enable insert for authenticated users only" ON public.servers
    FOR INSERT TO authenticated
    WITH CHECK (
        EXISTS (
            SELECT 1 FROM public.profiles
            WHERE profiles.id = servers.owner
              AND profiles.auth_user_id = (select ( SELECT auth.uid() ))
        )
    );

-- Allow server owners to update their servers (join through profiles)
CREATE POLICY "Server owners can update their servers" ON public.servers
    FOR UPDATE TO authenticated 
    USING (EXISTS (
        SELECT 1 FROM public.profiles 
        WHERE profiles.id = servers.owner 
        AND profiles.auth_user_id = ( SELECT auth.uid() )
    ))
    WITH CHECK (EXISTS (
        SELECT 1 FROM public.profiles 
        WHERE profiles.id = servers.owner 
        AND profiles.auth_user_id = ( SELECT auth.uid() )
    ));

-- Allow server owners to delete their servers
CREATE POLICY "Server owners can delete their servers" ON public.servers
    FOR DELETE TO authenticated 
    USING (EXISTS (
        SELECT 1 FROM public.profiles 
        WHERE profiles.id = servers.owner 
        AND profiles.auth_user_id = ( SELECT auth.uid() )
    ));

-- ---------------------------------------------------------------------------
-- CHANNEL CATEGORIES RLS
-- ---------------------------------------------------------------------------
-- Note: 98_enable_rls.sql already enables RLS on this table.
-- Categories are not sensitive - allow all authenticated users to read.

DROP POLICY IF EXISTS "channel_categories_select" ON public.channel_categories;
CREATE POLICY "channel_categories_select" ON public.channel_categories
    FOR SELECT USING (true);

DROP POLICY IF EXISTS "channel_categories_insert" ON public.channel_categories;
CREATE POLICY "channel_categories_insert" ON public.channel_categories
    FOR INSERT WITH CHECK (
        EXISTS (
            SELECT 1 FROM public.servers
            WHERE id = channel_categories.server_id
            AND owner = ( SELECT public.get_current_profile_id() )
        )
    );

DROP POLICY IF EXISTS "channel_categories_update" ON public.channel_categories;
CREATE POLICY "channel_categories_update" ON public.channel_categories
    FOR UPDATE USING (
        EXISTS (
            SELECT 1 FROM public.user_servers us
            WHERE us.server_id = channel_categories.server_id
            AND us.user_id = ( SELECT public.get_current_profile_id() )
        )
    );

DROP POLICY IF EXISTS "channel_categories_delete" ON public.channel_categories;
CREATE POLICY "channel_categories_delete" ON public.channel_categories
    FOR DELETE USING (
        EXISTS (
            SELECT 1 FROM public.servers
            WHERE id = channel_categories.server_id
            AND owner = ( SELECT public.get_current_profile_id() )
        )
    );

-- ---------------------------------------------------------------------------
-- CHANNELS RLS
-- ---------------------------------------------------------------------------
ALTER TABLE public.channels ENABLE ROW LEVEL SECURITY;

CREATE POLICY "channels_select_member" ON public.channels
    FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM public.user_servers us
            JOIN public.servers s ON s.id = us.server_id
            WHERE us.server_id = channels.server_id
            AND (us.user_id = ( SELECT public.get_current_profile_id() ) OR s.owner = ( SELECT public.get_current_profile_id() ))
            AND us.status = 'accepted'
        )
        OR EXISTS (
            SELECT 1 FROM public.servers 
            WHERE id = channels.server_id 
            AND owner = ( SELECT public.get_current_profile_id() )
        )
    );

CREATE POLICY "channels_insert_owner" ON public.channels
    FOR INSERT WITH CHECK (
        EXISTS (
            SELECT 1 FROM public.servers 
            WHERE id = channels.server_id 
            AND owner = ( SELECT public.get_current_profile_id() )
        )
    );

CREATE POLICY "channels_update_owner" ON public.channels
    FOR UPDATE USING (
        EXISTS (
            SELECT 1 FROM public.servers 
            WHERE id = channels.server_id 
            AND owner = ( SELECT public.get_current_profile_id() )
        )
    );

CREATE POLICY "channels_delete_owner" ON public.channels
    FOR DELETE USING (
        EXISTS (
            SELECT 1 FROM public.servers 
            WHERE id = channels.server_id 
            AND owner = ( SELECT public.get_current_profile_id() )
        )
    );

-- ---------------------------------------------------------------------------
-- MESSAGES RLS
-- ---------------------------------------------------------------------------
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;

-- Channel messages: members can see
CREATE POLICY "messages_select_channel_member" ON public.messages
    FOR SELECT USING (
        -- Channel messages
        (channel_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM public.channels c
            JOIN public.user_servers us ON us.server_id = c.server_id
            WHERE c.id = messages.channel_id
            AND us.user_id = ( SELECT public.get_current_profile_id() )
            AND us.status = 'accepted'
        ))
        OR
        -- DM messages
        (conversation_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM public.conversation_participants cp
            WHERE cp.conversation_id = messages.conversation_id
            AND cp.user_id = ( SELECT public.get_current_profile_id() )
            AND cp.left_at IS NULL
        ))
    );

-- Prevent blocked users from sending DMs to users who blocked them
CREATE POLICY "messages_insert_member" ON public.messages
    FOR INSERT WITH CHECK (
        user_id = ( SELECT public.get_current_profile_id() )
        AND (
            -- Channel messages: always allowed (server-level moderation handles this)
            (channel_id IS NOT NULL AND EXISTS (
                SELECT 1 FROM public.channels c
                JOIN public.user_servers us ON us.server_id = c.server_id
                WHERE c.id = messages.channel_id
                AND us.user_id = ( SELECT public.get_current_profile_id() )
                AND us.status = 'accepted'
            ))
            OR
            -- DM messages: check if any participant has blocked us
            (conversation_id IS NOT NULL AND EXISTS (
                SELECT 1 FROM public.conversation_participants cp
                WHERE cp.conversation_id = messages.conversation_id
                AND cp.user_id = ( SELECT public.get_current_profile_id() )
                AND cp.left_at IS NULL
            ) AND NOT EXISTS (
                -- Prevent sending if any other participant has blocked us
                SELECT 1 FROM public.conversation_participants cp
                WHERE cp.conversation_id = messages.conversation_id
                AND cp.user_id != ( SELECT public.get_current_profile_id() )
                AND cp.left_at IS NULL
                AND public.is_blocked_by(cp.user_id)
            ))
        )
    );

CREATE POLICY "messages_update_authorized" ON public.messages
    FOR UPDATE USING (
        user_id = ( SELECT public.get_current_profile_id() )
        OR ( SELECT public.is_current_user_admin() )
        OR ( SELECT public.is_current_user_moderator() )
        OR public.can_current_user_manage_messages_in_channel(channel_id)
    );

CREATE POLICY "messages_delete_authorized" ON public.messages
    FOR DELETE USING (
        user_id = ( SELECT public.get_current_profile_id() )
        OR ( SELECT public.is_current_user_admin() )
        OR ( SELECT public.is_current_user_moderator() )
        OR public.can_current_user_manage_messages_in_channel(channel_id)
    );

-- ---------------------------------------------------------------------------
-- USER SERVERS RLS
-- ---------------------------------------------------------------------------
-- Note: Using simple policies to avoid infinite recursion issues.
-- Complex membership checks should be done in application logic.
ALTER TABLE public.user_servers ENABLE ROW LEVEL SECURITY;

-- Users can see memberships for servers they belong to (co-members),
-- their own memberships, or all memberships if admin.
CREATE POLICY "user_servers_select_co_members" ON public.user_servers
    FOR SELECT TO authenticated
    USING (
        user_id = ( SELECT public.get_current_profile_id() )
        OR public.current_user_is_member_of_server(server_id)
        OR ( SELECT public.is_current_user_admin() )
    );

-- Users can join servers (insert themselves)
CREATE POLICY "user_servers_insert_self" ON public.user_servers
    FOR INSERT TO authenticated
    WITH CHECK (user_id = ( SELECT public.get_current_profile_id() ));

-- Users can update their own membership, server owners can update any member
CREATE POLICY "user_servers_update_own_or_owner" ON public.user_servers
    FOR UPDATE TO authenticated
    USING (
        user_id = ( SELECT public.get_current_profile_id() )
        OR EXISTS (
            SELECT 1 FROM public.servers
            WHERE servers.id = user_servers.server_id
            AND owner = ( SELECT public.get_current_profile_id() )
        )
        OR ( SELECT public.is_current_user_admin() )
    );

-- Allow users to leave servers they're in, or owners to remove members
CREATE POLICY "Users can leave servers" ON public.user_servers
    FOR DELETE TO authenticated USING (
        user_id = ( SELECT public.get_current_profile_id() )
        OR EXISTS (
            SELECT 1 FROM public.servers
            WHERE servers.id = user_servers.server_id
            AND owner = ( SELECT public.get_current_profile_id() )
        )
    );

-- ---------------------------------------------------------------------------
-- CONVERSATIONS RLS
-- ---------------------------------------------------------------------------
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;

CREATE POLICY "conversations_select_participant" ON public.conversations
    FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM public.conversation_participants
            WHERE conversation_id = conversations.id
            AND user_id = ( SELECT public.get_current_profile_id() )
        )
    );

-- Direct inserts must set created_by = self. All real conversation creation
-- goes through SECURITY DEFINER RPCs (create_or_get_direct_conversation,
-- create_group_conversation) which bypass RLS, so this strict check is safe.
CREATE POLICY "conversations_insert_authenticated" ON public.conversations
    FOR INSERT WITH CHECK (created_by = (select ( SELECT public.get_current_profile_id() )));

-- ---------------------------------------------------------------------------
-- CONVERSATION PARTICIPANTS RLS
-- ---------------------------------------------------------------------------
-- Note: Using simple policies to avoid infinite recursion issues.
-- Complex membership checks should be done in application logic or via helper functions.
ALTER TABLE public.conversation_participants ENABLE ROW LEVEL SECURITY;

-- Read participant rows only for conversations the caller is in. Uses a
-- SECURITY DEFINER helper to avoid recursive RLS on this table. Previously this
-- was USING (true), which let any authenticated user enumerate every DM's
-- members (and, combined with the old permissive INSERT, self-join any DM).
CREATE POLICY "conversation_participants_select_policy" ON public.conversation_participants
    FOR SELECT USING (
        public.is_conversation_participant(conversation_id, ( SELECT public.get_current_profile_id() ))
    );

-- Direct client INSERTs are limited to adding YOURSELF to a conversation YOU
-- created. All real multi-party flows (1:1, group create, add member) go
-- through SECURITY DEFINER RPCs (create_or_get_direct_conversation,
-- create_group_conversation, add_user_to_conversation) which bypass RLS, so
-- this strict policy does not break any legitimate path. It does block the
-- attack of inserting yourself into a victim's existing conversation.
CREATE POLICY "conversation_participants_insert_self_owned" ON public.conversation_participants
    FOR INSERT WITH CHECK (
        user_id = ( SELECT public.get_current_profile_id() )
        AND EXISTS (
            SELECT 1 FROM public.conversations c
            WHERE c.id = conversation_id
              AND c.created_by = ( SELECT public.get_current_profile_id() )
        )
    );

-- Allow users to update their own participation
CREATE POLICY "conversation_participants_update_policy" ON public.conversation_participants
    FOR UPDATE TO authenticated USING (user_id = ( SELECT public.get_current_profile_id() ));

-- Allow users to leave conversations
CREATE POLICY "conversation_participants_delete_policy" ON public.conversation_participants
    FOR DELETE TO authenticated USING (user_id = ( SELECT public.get_current_profile_id() ));

-- ---------------------------------------------------------------------------
-- NOTIFICATIONS RLS
-- ---------------------------------------------------------------------------
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;

CREATE POLICY "notifications_select_own" ON public.notifications
    FOR SELECT USING (user_id = ( SELECT public.get_current_profile_id() ));

-- Notifications are created exclusively by SECURITY DEFINER functions/triggers
-- (send_notification, create_notification_structured, ...) which run as the
-- table owner and bypass RLS. Restricting the INSERT policy to service_role
-- means authenticated clients can no longer forge arbitrary notifications for
-- other users (fake mentions/DMs/admin prompts) via PostgREST.
CREATE POLICY "notifications_insert_system" ON public.notifications
    FOR INSERT TO service_role WITH CHECK (true);

CREATE POLICY "notifications_update_own" ON public.notifications
    FOR UPDATE USING (user_id = ( SELECT public.get_current_profile_id() ));

CREATE POLICY "notifications_delete_own" ON public.notifications
    FOR DELETE USING (user_id = ( SELECT public.get_current_profile_id() ));

