-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.cleanup_roles_on_member_leave()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    DELETE FROM public.user_roles
    WHERE user_id = OLD.user_id AND server_id = OLD.server_id;
    RETURN OLD;
END;
$$;

