    ON storage.objects FOR SELECT
    USING (bucket_id = 'group-icons');

-- Group icons: conversation participants can upload
-- Upload path is {conversationId}/{filename}, so foldername[1] = conversationId
DROP POLICY IF EXISTS "Group participants can upload group icons" ON storage.objects;
CREATE POLICY "Group participants can upload group icons"
    ON storage.objects FOR INSERT
    WITH CHECK (
        bucket_id = 'group-icons'
        AND auth.role() = 'authenticated'
        AND EXISTS (
            SELECT 1 FROM public.conversation_participants cp
            WHERE cp.conversation_id = (storage.foldername(name))[1]::uuid
              AND cp.user_id = public.get_current_profile_id()
              AND cp.left_at IS NULL
        )
    );

-- Group icons: conversation participants can update
DROP POLICY IF EXISTS "Group participants can update group icons" ON storage.objects;
CREATE POLICY "Group participants can update group icons"
    ON storage.objects FOR UPDATE
    USING (
        bucket_id = 'group-icons'
        AND auth.role() = 'authenticated'
        AND EXISTS (
            SELECT 1 FROM public.conversation_participants cp
            WHERE cp.conversation_id = (storage.foldername(name))[1]::uuid
              AND cp.user_id = public.get_current_profile_id()
              AND cp.left_at IS NULL
        )
    );

-- Group icons: conversation participants can delete
DROP POLICY IF EXISTS "Group participants can delete group icons" ON storage.objects;
CREATE POLICY "Group participants can delete group icons"
    ON storage.objects FOR DELETE
    USING (
        bucket_id = 'group-icons'
        AND auth.role() = 'authenticated'
        AND EXISTS (
            SELECT 1 FROM public.conversation_participants cp
            WHERE cp.conversation_id = (storage.foldername(name))[1]::uuid
              AND cp.user_id = public.get_current_profile_id()
              AND cp.left_at IS NULL
        )
    );

-- ---------------------------------------------------------------------------
-- BUCKET METADATA READ ACCESS
-- ---------------------------------------------------------------------------
-- The `public = true` flag only makes OBJECTS in a bucket downloadable; it does
-- NOT expose the bucket's own row (file_size_limit / allowed_mime_types), which
-- is RLS-gated separately on storage.buckets. Without this, supabase.storage
-- .getBucket() returns nothing for normal clients, so the frontend can't show
-- accurate per-instance size/type limits in upload validation messages.
--
-- We expose metadata for PUBLIC buckets only (id, public, file_size_limit,
-- allowed_mime_types) - all of which are non-sensitive. No custom RPC needed.
ALTER TABLE storage.buckets ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public buckets metadata is readable" ON storage.buckets;
CREATE POLICY "Public buckets metadata is readable"
    ON storage.buckets FOR SELECT
    USING (public = true);

DO $$
BEGIN
    RAISE NOTICE 'Storage buckets and policies created successfully';
END $$;


-- ==== 98_enable_rls.sql ====
-- Enable RLS on Supabase-managed tables (auth, storage, realtime).
-- These tables vary across Supabase versions, so skip any that don't exist.
DO $$
DECLARE
    tbl text;
    tbls text[] := ARRAY[
        'auth.audit_log_entries',
        'auth.flow_state',
        'auth.identities',
        'auth.instances',
        'auth.mfa_amr_claims',
        'auth.mfa_challenges',
        'auth.mfa_factors',
        'auth.one_time_tokens',
        'auth.refresh_tokens',
        'auth.saml_providers',
        'auth.saml_relay_states',
        'auth.schema_migrations',
        'auth.sessions',
        'auth.sso_domains',
        'auth.sso_providers',
        'auth.users',
        'realtime.messages',
        'storage.buckets',
        'storage.buckets_analytics',
        'storage.buckets_vectors',
        'storage.iceberg_namespaces',
        'storage.iceberg_tables',
        'storage.migrations',
        'storage.objects',
        'storage.prefixes',
        'storage.s3_multipart_uploads',
        'storage.s3_multipart_uploads_parts',
        'storage.vector_indexes'
    ];
BEGIN
    FOREACH tbl IN ARRAY tbls LOOP
        BEGIN
            EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', tbl);
        EXCEPTION
            WHEN undefined_table THEN
                RAISE NOTICE 'Skipping RLS for non-existent table: %', tbl;
            WHEN insufficient_privilege THEN
                RAISE NOTICE 'Skipping RLS for table not owned by current role: %', tbl;
        END;
    END LOOP;
END
$$;

-- RLS policies for realtime.messages - required for private broadcast channels.
-- Without these, authenticated users cannot subscribe to or receive private broadcasts.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'realtime' AND table_name = 'messages') THEN
    EXECUTE 'DROP POLICY IF EXISTS "authenticated_users_can_receive" ON realtime.messages';
    EXECUTE 'CREATE POLICY "authenticated_users_can_receive" ON realtime.messages FOR SELECT TO authenticated USING (public.can_subscribe_to_topic(topic))';
    EXECUTE 'DROP POLICY IF EXISTS "authenticated_users_can_send" ON realtime.messages';
    EXECUTE 'CREATE POLICY "authenticated_users_can_send" ON realtime.messages
      FOR INSERT TO authenticated
      WITH CHECK (
        topic = ''user:'' || public.get_current_profile_id()::text
        OR (
          topic LIKE ''server-presence:%''
          AND EXISTS (
            SELECT 1 FROM public.user_servers us
            WHERE us.server_id = substring(topic from 17)::uuid
              AND us.user_id = public.get_current_profile_id()
              AND us.status = ''accepted''
          )
        )
      )';
  END IF;
END
$$;

